// MyNCE practice question bank — generated from QuestionBank.swift (rewritten options)
const QUESTION_BANK = [{"id": "q001", "text": "A client asks at the first session what information may be shared with others. Which counselor response best reflects ethical informed consent?", "options": ["Provide the written consent document for the client to review at home and sign at the next session.", "Review confidentiality and its limits now, deferring fees and records policies until the client raises them.", "Explain confidentiality and its limits, fees, records, credentials, and client rights before treatment proceeds.", "Assure the client that information is disclosed only with a court order or the client's written permission."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Informed consent requires clear discussion of the counseling relationship, confidentiality and its limits, records, fees, credentials, and client rights before or at the beginning of services."}, {"id": "q002", "text": "A counselor learns that a client has a specific plan, means, and intent to seriously harm an identifiable person. What is the counselor's best initial ethical action?", "options": ["Terminate and refer the client to a higher level of care immediately to limit liability exposure.", "Take reasonable protective action consistent with law and policy, such as consultation, notification, or contacting authorities.", "Break confidentiality only after obtaining the client's written consent to contact the potential victim.", "Document the threat thoroughly and address it as clinical material in the next scheduled session."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Confidentiality has exceptions when there is serious, foreseeable, and imminent risk to an identifiable person. Counselors should follow law, policy, consultation, and documentation."}, {"id": "q003", "text": "A former client sends a counselor a social media friend request. What is the most ethical response?", "options": ["Accept the request but keep interactions brief and never reference the former counseling relationship.", "Accept the request, since the professional relationship ended and ordinary social contact is now permissible.", "Decline and send a message explaining that ethics codes prohibit all post-termination contact.", "Maintain professional boundaries and discuss social media policies if contact with the client resumes."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Social media contact can blur boundaries and expose client privacy. Ethical practice uses clear policies and boundary protection."}, {"id": "q004", "text": "A counselor receives a subpoena for a client's complete record. What should the counselor do first?", "options": ["Consult with the client, supervisor, or attorney as appropriate, and release only what is legally required or authorized.", "Provide a written treatment summary in place of the record to protect the client's privacy.", "Assert privilege and decline to respond until the client's own attorney contacts the counselor.", "Release the requested record promptly, because a subpoena carries the same binding legal force as a court order."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "A subpoena does not automatically authorize full disclosure. Counselors protect confidentiality, seek consultation, and disclose the minimum required information."}, {"id": "q005", "text": "A counselor begins working with a client whose concerns require a specialized treatment in which the counselor has no training. What is the most ethical course?", "options": ["Obtain the client's written consent to receive a treatment the counselor is still learning.", "Proceed using general evidence-based techniques while studying the treatment manual between sessions.", "Refer immediately, since providing any service outside one's specialty exceeds the scope of practice.", "Seek supervision, consultation, training, or referral so the client receives competent services."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Counselors practice within the boundaries of competence and must obtain training, supervision, consultation, or make an appropriate referral when needed."}, {"id": "q006", "text": "Which documentation practice is most consistent with ethical record keeping?", "options": ["Keep detailed psychotherapy process notes in the official record for continuity of care.", "Record clinically relevant, accurate, timely information while protecting client privacy.", "Document sessions verbatim so the record is complete for any future provider or review.", "Keep notes brief and general so that records released under subpoena cannot harm the client."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Records should be accurate, timely, clinically relevant, and written with privacy and continuity of care in mind."}, {"id": "q007", "text": "A client asks to see their counseling record. Which counselor response is generally most appropriate?", "options": ["Follow applicable law and policy while facilitating access and protecting against serious, foreseeable harm.", "Provide the complete record on request, since clients own their records and access cannot be limited.", "Release the record only to another licensed professional whom the client designates.", "Offer a thorough verbal summary in session in place of releasing the written record."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Clients typically have rights related to access to records, but counselors must follow law, agency policy, and ethical standards regarding privacy and potential harm."}, {"id": "q008", "text": "A counselor is offered an expensive gift by a client near termination. What should the counselor do first?", "options": ["Accept the gift and document its value and the clinical rationale in the record.", "Accept graciously, because refusing a termination gift risks rupturing the relationship and undoing gains.", "Explore the meaning of the gift, cultural context, potential boundary issues, and agency policy before deciding.", "Decline politely and explain that gifts of significant value create a conflict of interest."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Gift decisions require clinical judgment, cultural sensitivity, boundary awareness, documentation, and attention to policy rather than a rigid automatic rule."}, {"id": "q009", "text": "A counselor has strong personal values that conflict with a client's goals. What is the ethical priority?", "options": ["Bracket personal values by steering sessions away from topics related to the conflict.", "Avoid imposing personal values and seek consultation or referral only when competence or harm is at issue.", "Refer the client to a counselor whose values align more closely with the client's goals.", "Disclose the value conflict to the client so the client can decide whether to continue."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Counselors respect client autonomy and avoid value imposition. Consultation helps determine how to serve the client ethically."}, {"id": "q010", "text": "A counselor in a small town recognizes that a new client is also the counselor's child's teacher. Which action best addresses the ethical concern?", "options": ["Discuss the potential multiple relationship, risks, boundaries, and alternatives before proceeding.", "Refer the client elsewhere, since foreseeable multiple relationships should be avoided when alternatives exist.", "Check the ethics code and proceed only if this relationship is not explicitly prohibited.", "Proceed and maintain strict role separation by not acknowledging the client at school functions."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Not every multiple relationship is prohibited, but counselors must evaluate potential harm, exploitation, impaired objectivity, and alternatives."}, {"id": "q011", "text": "A counselor suspects child abuse based on a minor client's disclosure. What is the counselor's responsibility?", "options": ["Inform the family of the duty to report and offer them the opportunity to self-report first.", "Consult a supervisor and report only if the supervisor agrees the disclosure is credible.", "Gather corroborating detail over the next several sessions so any report will be credible.", "Follow mandated reporting laws and document the report and clinical rationale."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Mandated reporting laws require timely reporting of suspected abuse; proof beyond suspicion is not typically the counselor's role."}, {"id": "q012", "text": "Which action best demonstrates ethical use of consultation?", "options": ["Present the full case history so the consultant's recommendations rest on complete information.", "Consult only with professionals outside the agency to shield the client from internal exposure.", "Share only the information necessary for consultation and protect the client's identity when possible.", "Obtain the client's written authorization before any case consultation can occur."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Consultation is ethical when used to improve care, but disclosures should be limited and client privacy protected."}, {"id": "q013", "text": "A counselor's personal stress is impairing concentration and judgment in sessions. What is the ethical response?", "options": ["Increase personal therapy while keeping the caseload unchanged to preserve continuity of care.", "Refer all current clients and take a leave of absence until fully recovered.", "Seek supervision, reduce impairment, and take steps to protect clients from harm.", "Inform clients of the stress and let each decide whether to continue treatment."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Counselors monitor impairment and take corrective action, including supervision, self-care, referral, or temporary adjustment of duties."}, {"id": "q014", "text": "A client signs a release of information for coordination with a physician. What should the counselor disclose?", "options": ["The complete record, since the physician is a covered entity under the same privacy rules.", "Diagnosis and medications only, because releases govern administrative rather than clinical data.", "Nothing in writing; coordinate verbally so no protected documentation changes hands.", "Only information authorized by the release and relevant to the coordination purpose."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "A valid release should guide the scope, purpose, recipient, and duration of disclosure; counselors use minimum necessary information."}, {"id": "q015", "text": "A counselor advertises being certified in a treatment approach after attending a one-day introductory workshop. What is the ethical concern?", "options": ["The advertisement is acceptable if the counselor practices the approach under supervision.", "The advertisement may misrepresent the counselor's training and competence.", "The wording distinction between certified and trained carries little ethical weight.", "The workshop certificate permits the claim as long as the issuing organization is legitimate."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Counselors must accurately represent credentials, training, experience, and competence in public statements."}, {"id": "q016", "text": "A counselor wants to use artificial intelligence to summarize session notes. What ethical step is most important before use?", "options": ["Verify privacy, consent, security, accuracy, and compliance with law and agency policy.", "Pilot the tool with lower-risk clients before expanding it to the full caseload.", "Add a signed consent addendum, which authorizes the use of any secure technology.", "Deidentify the notes before entry, which satisfies confidentiality requirements for outside tools."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Technology use requires attention to confidentiality, informed consent, data security, accuracy, and professional responsibility."}, {"id": "q017", "text": "A client can no longer afford the counselor's fee. What response best reflects ethical practice?", "options": ["Arrange to barter services with the client as an equitable alternative to fees.", "Offer pro bono sessions until the client's finances recover, since clinical need outweighs fees.", "Transfer the client to a community agency within the week to prevent an unpaid balance.", "Discuss options such as fee adjustment, referral, or continuity planning without abandoning the client."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Counselors manage fees transparently and avoid client abandonment, especially when financial barriers arise."}, {"id": "q018", "text": "A counselor is asked by an employer to reveal whether an employee-client is attending sessions. What should the counselor do?", "options": ["Obtain the client's written authorization before confirming attendance, unless another legal exception applies.", "Confirm attendance dates only, while withholding all clinical content from the employer.", "Decline to respond and inform the employer that such inquiries are prohibited by law.", "Refer the employer to human resources, since employment matters fall outside the counselor's role."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Even confirming a counseling relationship can disclose protected information. Written authorization is usually required."}, {"id": "q019", "text": "Which practice best protects confidentiality in group counseling?", "options": ["Direct sharing toward less sensitive topics so any breach carries little consequence.", "Explain that group disclosures carry the same legal privilege as individual sessions.", "Screen members, explain confidentiality and its limits, and clarify that member privacy cannot be guaranteed.", "Have members sign confidentiality contracts that are legally enforceable if privacy is broken."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Group leaders must clearly explain confidentiality expectations and limits, including the counselor's inability to guarantee member behavior."}, {"id": "q020", "text": "A counselor has a client who repeatedly misses appointments. Which action best avoids abandonment?", "options": ["Hold the case open and wait for the client to initiate contact, out of respect for autonomy.", "Review attendance policies, assess barriers, document outreach, and provide referrals if services end.", "Reserve the client's time slot and bill for missed sessions until attendance resumes.", "Send a certified termination letter after the second consecutive absence, per standard risk management."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Ethical termination includes notice, attention to barriers, documentation, and appropriate referral or follow-up planning."}, {"id": "q021", "text": "A counselor is conducting research with clients at the agency. What is the most important ethical safeguard?", "options": ["Obtain review board approval, which itself ensures that client participants are protected.", "Use voluntary informed consent and protect clients from coercion or compromised services.", "Have a colleague recruit participants so the counselor's dual role never touches enrollment.", "Offer a modest fee reduction to compensate clients fairly for their participation."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Research with clients requires voluntary consent, confidentiality protections, risk disclosure, and avoidance of coercion."}, {"id": "q022", "text": "A counselor receives a complaint from a client about feeling misunderstood because of cultural identity. What is the best ethical response?", "options": ["Invite discussion, seek cultural consultation or training, and repair the relationship without defensiveness.", "Acknowledge the concern and offer a referral to a counselor who shares the client's background.", "Review session notes to verify whether a misunderstanding actually occurred before responding.", "Apologize and reorient the treatment plan to focus primarily on cultural identity."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Culturally responsive practice requires humility, openness, consultation, and attention to the client's lived experience."}, {"id": "q023", "text": "Which action is most consistent with ethical supervision?", "options": ["A supervisor evaluates supervisees chiefly on measurable client outcome data.", "A supervisor intervenes directly with supervisees' clients whenever clinical risk arises.", "A supervisor monitors client welfare, counselor development, documentation, and scope of practice.", "A supervisor reviews every recorded session to guarantee that no client is harmed."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Supervision includes gatekeeping, client welfare, professional development, ethical practice, and clinical oversight."}, {"id": "q024", "text": "A client asks the counselor to write a custody recommendation after only individual therapy with one parent. What is the best response?", "options": ["Refer the parent to a custody evaluator and forward the full clinical record to that evaluator.", "Provide a recommendation limited to parenting strengths directly observed in treatment.", "Defer until subpoenaed, at which point offering a custody opinion becomes permissible.", "Clarify role limitations and avoid offering an opinion that exceeds available data or competence."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Counselors must avoid role confusion and forensic opinions that exceed their role, data, training, or objectivity."}, {"id": "q025", "text": "During an intake, a client reports depressed mood. Which assessment question most directly evaluates suicide risk?", "options": ["How long have you felt this way, and has the sadness been getting worse recently?", "Have you had thoughts of killing yourself, and do you have a plan, intent, or access to means?", "What has kept you going during the most difficult periods in the past?", "When the mood is at its worst, do you ever feel like life is too much to handle?"], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Suicide assessment requires direct inquiry about ideation, plan, intent, means, prior attempts, protective factors, and risk factors."}, {"id": "q026", "text": "A client is alert, oriented, and cooperative but speaks rapidly, reports sleeping two hours nightly, and describes grand business plans. Which MSE area is most clearly indicated?", "options": ["Stimulant and substance use should be screened before any mood episode is considered.", "Orientation and memory should be evaluated first to rule out an emerging delirium.", "Mood, thought process, and possible manic symptoms should be assessed further.", "Insight and judgment should be assessed, since cooperation may be masking impairment."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Rapid speech, decreased need for sleep, and grandiosity suggest possible mania or hypomania and require further assessment."}, {"id": "q027", "text": "Which item is most central to a biopsychosocial assessment?", "options": ["Current symptoms, medical factors, family history, social supports, culture, risks, and strengths.", "Presenting symptoms mapped to DSM criteria, since diagnosis drives the treatment plan.", "The client's developmental history from infancy through adolescence.", "Standardized instrument scores spanning biological, psychological, and social domains."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "A biopsychosocial assessment integrates biological, psychological, social, cultural, risk, and strength-based data."}, {"id": "q028", "text": "A standardized test yields consistent scores across repeated administrations. Which psychometric property is being described?", "options": ["Validity.", "Objectivity.", "Standardization.", "Reliability."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Reliability refers to consistency of measurement, such as test-retest or internal consistency."}, {"id": "q029", "text": "A depression inventory actually measures depressive symptoms rather than general distress. Which property is best represented?", "options": ["Validity.", "Reliability.", "Standardization.", "Sensitivity."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Validity concerns whether an instrument measures what it is intended to measure."}, {"id": "q030", "text": "A counselor uses a screening tool that was not normed with the client's cultural group. What is the best next step?", "options": ["Adjust the cutoff score to account for expected cultural differences in responding.", "Interpret cautiously and consider cultural, linguistic, and contextual factors before making conclusions.", "Administer the tool but report only raw scores rather than normed comparisons.", "Replace it with a clinical interview, since tools without matching norms should not be used."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Assessment interpretation must consider cultural fairness, language, context, norms, and possible bias."}, {"id": "q031", "text": "A client presents with panic attacks and heavy caffeine use. Which assessment priority is most appropriate?", "options": ["Ask the client to reduce caffeine and reassess the symptoms in two weeks.", "Begin psychoeducation about the panic cycle while monitoring attack frequency.", "Administer a standardized anxiety inventory to establish a symptom baseline.", "Assess medical, substance, medication, and lifestyle factors that may mimic or worsen anxiety."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Differential assessment considers medical and substance-related contributors before final diagnosis and treatment planning."}, {"id": "q032", "text": "Which client statement most strongly suggests a need to assess for psychosis?", "options": ["I feel like everyone is judging me whenever I walk into a room.", "I keep having the same vivid nightmare about being chased.", "I hear voices commenting on my behavior when no one else is present.", "I sometimes talk to myself out loud when I am alone at home."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Auditory hallucinations, delusions, disorganized speech, or impaired reality testing warrant assessment for psychotic symptoms."}, {"id": "q033", "text": "A client reports intrusive unwanted thoughts and repetitive checking to reduce anxiety. Which area should be assessed further?", "options": ["Trauma history, since intrusive thoughts typically indicate re-experiencing.", "Obsessive-compulsive symptoms, including obsessions, compulsions, impairment, and avoidance.", "Psychotic processes, since the client cannot control the thoughts.", "Generalized anxiety, since chronic worry is what drives repetitive behavior."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Intrusive thoughts and rituals aimed at reducing anxiety are characteristic of obsessive-compulsive presentations."}, {"id": "q034", "text": "A client reports nightmares, avoidance, hypervigilance, and intrusive memories after an assault. Which assessment focus is most indicated?", "options": ["Trauma-related symptoms, duration, impairment, dissociation, safety, and supports.", "Sleep pathology, since nightmares and hypervigilance point to a primary sleep disorder.", "Panic disorder, since hyperarousal and intrusive fear are central to both conditions.", "Depressive symptoms, since avoidance and withdrawal usually reflect low mood."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Trauma assessment examines intrusion, avoidance, arousal, mood/cognition changes, duration, impairment, safety, and supports."}, {"id": "q035", "text": "A counselor screens a client for alcohol use. Which question best assesses hazardous drinking behavior?", "options": ["Do you usually drink alone at home, or mostly in social settings with friends and coworkers?", "Has anyone in your immediate family struggled with alcohol use or dependence over the years?", "Do you tend to drink more than usual when you are stressed, upset, or under pressure?", "How often and how much do you drink, and what consequences have occurred because of drinking?"], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Substance assessment includes frequency, quantity, consequences, loss of control, tolerance, withdrawal, risk, and readiness to change."}, {"id": "q036", "text": "What is the primary purpose of a Mental Status Examination?", "options": ["To generate a provisional DSM diagnosis by applying structured criteria to the interview.", "To establish the developmental and social history behind the presenting problem.", "To assess current functioning, appearance, behavior, mood, thought, cognition, insight, and judgment.", "To track symptom change systematically across the full course of treatment for outcome review."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "The MSE is a structured snapshot of current psychological functioning and behavioral presentation."}, {"id": "q037", "text": "A client reports elevated mood only after starting a stimulant medication. Which diagnostic principle is most relevant?", "options": ["Refer to the prescriber and defer mood assessment until the medication stabilizes.", "Attribute the elevation to the medication only if psychotic features are present.", "Consider substance- or medication-induced symptoms in the differential diagnosis.", "Diagnose bipolar II disorder if the elevation persists four days, regardless of timing."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Differential diagnosis considers whether symptoms are attributable to substances, medications, medical conditions, or another disorder."}, {"id": "q038", "text": "Which factor is a protective factor in suicide risk assessment?", "options": ["Strong reasons for living and connected social support.", "A no-suicide contract signed during session.", "Recent discharge from psychiatric hospitalization.", "A firearm stored in a locked cabinet in the home."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Protective factors may reduce risk, while prior attempts, access to means, and recent losses increase concern."}, {"id": "q039", "text": "A counselor asks a client to describe the problem in the client's own words during intake. What is the primary purpose?", "options": ["To build rapport before transitioning into standardized measures.", "To observe speech, affect, and thought organization for the mental status exam.", "To identify discrepancies between the client's account and the referral information.", "To gather the client's subjective experience and presenting concern."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Client self-report is central to intake because it clarifies the client's perspective, goals, symptoms, and context."}, {"id": "q040", "text": "Which information is most important before assigning a diagnosis?", "options": ["Scores from at least one validated diagnostic instrument administered under standard conditions.", "Symptom pattern, duration, impairment, exclusions, cultural context, and differential diagnosis.", "Corroborating history obtained from a family member or from a prior treatment provider's records.", "The client's response to an initial trial of evidence-based treatment."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Diagnosis should be based on criteria, impairment, duration, context, exclusions, and clinical judgment rather than a single impression."}, {"id": "q041", "text": "A client reports memory gaps, depersonalization, and losing time after trauma reminders. Which assessment area is most relevant?", "options": ["Dissociative symptoms and trauma history.", "Substance-induced blackouts, the most common cause of lost time.", "Attention deficits, since losing time reflects impaired concentration.", "Malingering, given that the memory gaps surround specific events."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Dissociation can include depersonalization, derealization, amnesia, and identity disruption, especially in trauma contexts."}, {"id": "q042", "text": "A counselor wants to select an assessment for an eight-year-old. What consideration is most important?", "options": ["Whether teacher ratings can substitute for the child's own self-report.", "Whether the tool shows strong reliability in adult clinical samples.", "Developmental appropriateness, validity for age, caregiver input, and cultural context.", "Whether the instrument can be completed within a single session to limit burden."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Assessment selection must match the client's developmental level, culture, language, presenting concern, and available norms."}, {"id": "q043", "text": "Which finding during intake most strongly suggests need for a higher level of care evaluation?", "options": ["Daily alcohol use that the client acknowledges but minimizes.", "Current suicidal intent with plan, means, and inability to commit to safety planning.", "Panic attacks occurring several times per week with agoraphobic avoidance.", "Passive wishes to not wake up, without any plan or stated intent."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "High acuity risk, impaired safety, or inability to maintain safety may require emergency evaluation or a higher level of care."}, {"id": "q044", "text": "A client says, 'I cannot stop gambling even though I lost rent money.' Which assessment area should be explored?", "options": ["Depressive symptoms, since mounting losses typically drive low mood first.", "Financial counseling needs that should be addressed before clinical assessment.", "Impulse control deficits secondary to a possible manic episode.", "Behavioral addiction symptoms, financial consequences, comorbidity, risk, and readiness to change."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Compulsive gambling can involve loss of control, consequences, impairment, comorbidity, and financial or safety risks."}, {"id": "q045", "text": "Which statement best describes clinical screening?", "options": ["A triage decision that determines the required level of care.", "A brief process used to identify whether further assessment is indicated.", "A structured interview that yields a provisional diagnosis.", "A repeated measure used to monitor response to treatment."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Screening is preliminary; positive screens require additional assessment, context, and clinical judgment."}, {"id": "q046", "text": "A counselor notices that a client avoids eye contact. What is the best assessment interpretation?", "options": ["Consider multiple explanations, including culture, anxiety, neurodiversity, trauma, or personal style.", "Note it as a nonverbal indicator of the client's discomfort with the counselor or the setting.", "Treat it as early supporting evidence of social anxiety while awaiting further symptoms.", "Record it as constricted affect within the mental status examination section of the intake."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Behavioral observations must be interpreted cautiously and culturally; one behavior rarely supports a diagnosis by itself."}, {"id": "q047", "text": "Which assessment practice is most trauma-informed?", "options": ["Ask about trauma a single time at intake and never return to it unless the client raises it first.", "Use written questionnaires only, so the client never has to speak about the trauma.", "Explain the purpose of questions, offer choice when possible, and monitor the client's distress and safety.", "Defer all trauma screening until at least the third session, once trust has been established."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Trauma-informed assessment balances needed information with safety, choice, collaboration, empowerment, and pacing."}, {"id": "q048", "text": "A client reports irritability, distractibility, and sleep problems. What is the best diagnostic approach?", "options": ["Screen formally for ADHD first, since distractibility is the cardinal feature of that disorder.", "Treat the sleep disturbance first, and then reassess whichever symptoms remain afterward.", "Prioritize a mood disorder workup, since irritability spans depression and mania.", "Evaluate multiple explanations, including anxiety, depression, ADHD, trauma, substance use, and medical factors."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Overlapping symptoms require differential diagnosis and assessment of duration, context, impairment, development, and contributing factors."}, {"id": "q049", "text": "A client reports low mood, anhedonia, sleep disturbance, guilt, and impaired concentration for more than two weeks. Which clinical focus is most relevant?", "options": ["Major depressive symptoms and suicide risk assessment.", "Generalized anxiety, given the concentration and sleep complaints.", "Adjustment disorder with depressed mood following a recent stressor.", "Occupational burnout, if the symptoms track with work demands."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "A cluster of depressive symptoms lasting at least two weeks with impairment warrants assessment for depressive disorders and suicide risk."}, {"id": "q050", "text": "A client has panic attacks followed by persistent worry about having more attacks and avoidance of exercise. Which concern is most likely?", "options": ["Agoraphobia, given the avoidance behavior that followed the attacks.", "Panic disorder with avoidance related to bodily sensations.", "Generalized anxiety disorder, given the persistent ongoing worry.", "Illness anxiety disorder, given the focus on bodily sensations."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Panic disorder involves recurrent unexpected panic attacks and ongoing concern or behavior change related to attacks."}, {"id": "q051", "text": "A client avoids social events because of fear of being judged or humiliated. Which area of clinical focus best fits?", "options": ["Agoraphobic avoidance of situations where escape might be difficult.", "Avoidant personality disorder, given a pervasive lifelong pattern.", "Social anxiety symptoms.", "Panic disorder with situational avoidance of crowded events."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Social anxiety centers on fear of negative evaluation and avoidance of social or performance situations."}, {"id": "q052", "text": "A client washes their hands for hours because of intrusive contamination fears. Which clinical focus is most relevant?", "options": ["Delusional contamination beliefs requiring reality testing.", "Illness anxiety focused on contracting a serious disease.", "A specific phobia of germs with associated avoidance behavior.", "Obsessive-compulsive symptoms involving obsessions and compulsions."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Obsessions are intrusive unwanted thoughts; compulsions are repetitive behaviors or mental acts used to reduce distress."}, {"id": "q053", "text": "A veteran reports intrusive memories, avoidance, negative mood changes, and hyperarousal after combat. Which clinical focus is most relevant?", "options": ["Major depressive symptoms with intrusive ruminations.", "Posttraumatic stress symptoms.", "Generalized anxiety with combat-related worry content.", "An adjustment disorder tied to the transition out of military service."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "PTSD involves trauma exposure plus intrusion, avoidance, mood/cognition changes, and arousal/reactivity symptoms."}, {"id": "q054", "text": "A client alternates between intense idealization and devaluation of others, fears abandonment, and engages in self-harm. Which area should be assessed?", "options": ["Borderline personality features and safety risk.", "Bipolar II disorder, given the alternation between emotional extremes.", "A histrionic pattern of attention-seeking and shifting emotionality.", "Dependent personality features, given the fear of abandonment."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Borderline features include instability in relationships, self-image, affect, impulsivity, abandonment fears, and possible self-harm."}, {"id": "q055", "text": "A client reports grandiosity, decreased need for sleep, pressured speech, and risky spending. Which clinical concern should be assessed?", "options": ["Adult ADHD, given the distractibility and high activity level.", "Mania or hypomania.", "Generalized anxiety, given the racing thoughts and sleep loss.", "Narcissistic traits, given the grandiose self-appraisal."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Elevated or irritable mood with increased energy and symptoms such as decreased need for sleep may indicate mania or hypomania."}, {"id": "q056", "text": "A client uses opioids daily and becomes ill when trying to stop. Which clinical issue is most relevant?", "options": ["Physiological dependence alone, which is not clinically significant.", "Chronic pain behavior maintained by negative reinforcement.", "An anxiety disorder expressed through withdrawal-like somatic symptoms.", "Opioid use disorder with possible withdrawal risk."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Daily use with inability to stop and withdrawal symptoms suggests substance use disorder and requires safety-informed assessment."}, {"id": "q057", "text": "A child repeatedly argues with adults, loses temper, and deliberately annoys others without serious rights violations. Which concern best fits?", "options": ["ADHD-related impulsivity presenting as defiance toward adults.", "Conduct disorder, given the deliberate provocation of others.", "Oppositional defiant behavior.", "Disruptive mood dysregulation, given the recurring temper outbursts."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Oppositional defiant disorder involves angry/irritable mood, argumentative/defiant behavior, or vindictiveness without the more severe rights violations of conduct disorder."}, {"id": "q058", "text": "An adolescent repeatedly violates rules, steals, and shows aggression toward people and animals. Which concern is most relevant?", "options": ["Conduct-disordered behavior.", "Antisocial personality disorder, given the pattern of rights violations.", "Oppositional defiant behavior that has not crossed diagnostic thresholds.", "Intermittent explosive episodes triggered by frustration."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Conduct disorder involves repetitive violation of rights, norms, or rules, including aggression, destruction, deceit/theft, or serious rule violations."}, {"id": "q059", "text": "A client has persistent restriction of food intake, intense fear of weight gain, and distorted body image. Which clinical focus is most relevant?", "options": ["Avoidant/restrictive food intake, given the persistent restriction.", "Body dysmorphic concerns without an eating disorder component.", "Bulimia nervosa, given the preoccupation with weight and shape.", "Anorexia nervosa symptoms and medical risk."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Restrictive eating with fear of weight gain and body image disturbance suggests anorexia nervosa and requires medical risk assessment."}, {"id": "q060", "text": "A client has recurrent binge eating followed by self-induced vomiting. Which clinical focus is most relevant?", "options": ["Bulimia nervosa symptoms and medical complications.", "Purging behavior secondary to somatic preoccupation.", "Anorexia nervosa, binge-eating/purging type, given the compensation.", "Binge-eating disorder, given the recurrent episodes of overeating."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Bulimia nervosa involves binge eating with compensatory behaviors and potential electrolyte, dental, and medical risks."}, {"id": "q061", "text": "A client reports excessive worry across work, health, finances, and family most days for months. Which concern best fits?", "options": ["Obsessive-compulsive symptoms, given the repetitive worried thinking.", "Panic disorder, given the persistent anticipatory anxiety.", "Generalized anxiety symptoms.", "An adjustment reaction to accumulating life stressors."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Generalized anxiety involves persistent, excessive worry across domains with associated symptoms and impairment."}, {"id": "q062", "text": "A client avoids driving after a car accident even though the client is physically recovered. Which focus should be assessed?", "options": ["A specific phobia of driving that predated the accident.", "Trauma-related avoidance, anxiety, and functional impairment.", "Agoraphobic avoidance of situations away from home.", "Illness anxiety about undetected injuries from the crash."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Avoidance after trauma can maintain PTSD or anxiety symptoms and should be assessed in context."}, {"id": "q063", "text": "A recently bereaved client cries daily but also experiences moments of connection, meaning, and intact reality testing. Which conceptualization is most appropriate?", "options": ["A major depressive episode, given daily crying beyond the first two weeks of loss.", "Persistent complex bereavement requiring immediate grief-specific treatment protocols.", "An adjustment disorder, since full daily functioning has not yet returned.", "Grief may be a normal response, while monitoring for impairment, risk, and complicated grief."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Grief is not automatically pathological; counselors assess duration, impairment, risk, culture, and meaning."}, {"id": "q064", "text": "A client reports hearing voices, believing neighbors control their thoughts, and difficulty maintaining work. Which clinical focus is most relevant?", "options": ["Obsessive intrusive thoughts misinterpreted as external voices.", "Severe social anxiety with ideas of reference about neighbors.", "Psychotic symptoms and functional impairment.", "Trauma-related hypervigilance with flashback phenomena."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Hallucinations, delusions, and impaired functioning warrant assessment for psychotic disorders and safety needs."}, {"id": "q065", "text": "A child is inattentive, forgetful, disorganized, and has impairment at school and home. Which area should be assessed?", "options": ["Attention-deficit/hyperactivity symptoms across settings.", "Normal developmental variability in executive maturation.", "A specific learning disorder underlying the school problems.", "An anxiety presentation, since chronic worry disrupts attention."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "ADHD assessment considers inattention and/or hyperactivity-impulsivity, impairment, onset, and presence across settings."}, {"id": "q066", "text": "A client reports intrusive memories and self-blame after sexual assault. Which counseling focus is especially important?", "options": ["Exposure-based retelling of the assault beginning in the first sessions.", "Trauma symptoms, safety, shame, support, and empowerment.", "Guilt processing framed primarily as a moral or spiritual concern.", "Cognitive restructuring of the self-blame as the immediate first intervention."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Sexual assault work requires trauma-informed attention to safety, choice, shame, support, and pacing."}, {"id": "q067", "text": "A client is being monitored by a partner who controls money, transportation, and phone access. Which concern should be assessed first?", "options": ["Financial strain as the primary driver of the partner's behavior.", "Codependent relational patterns maintained by both partners.", "Intimate partner violence, coercive control, and safety planning.", "Communication deficits best addressed through couples counseling."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Coercive control and surveillance can indicate intimate partner violence and require careful, non-escalating safety planning."}, {"id": "q068", "text": "A client reports using alcohol to sleep after trauma. Which clinical focus is most relevant?", "options": ["Co-occurring trauma symptoms and substance use.", "Primary insomnia, with the alcohol use as a secondary detail.", "The trauma symptoms alone, deferring substance assessment until later.", "The drinking alone, since substance use must resolve before trauma work."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Trauma and substance use often co-occur; assessment should address both rather than treating them in isolation."}, {"id": "q069", "text": "A client has chronic pain and increasing hopelessness. Which clinical focus should not be missed?", "options": ["Somatic symptom disorder, given the persistence of the pain complaints.", "Depression, suicide risk, functioning, medical coordination, and coping.", "Pain catastrophizing addressed through cognitive techniques alone.", "Health anxiety maintained by the cycle of repeated medical visits."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Chronic pain can interact with mood, functioning, identity, and suicide risk and may require interdisciplinary care."}, {"id": "q070", "text": "A teenager reports cutting to feel relief but denies suicidal intent. What clinical focus remains essential?", "options": ["Peer contagion effects best handled through school intervention.", "Emotion regulation deficits alone, since suicidal intent is denied.", "A borderline personality process requiring long-term treatment first.", "Nonsuicidal self-injury, emotion regulation, suicide risk, and safety planning."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Nonsuicidal self-injury requires assessment of function, frequency, medical risk, suicidality, emotion regulation, and supports."}, {"id": "q071", "text": "A client reports fear of leaving home because escape may be difficult during panic-like symptoms. Which concern is most relevant?", "options": ["Agoraphobic avoidance.", "A specific situational phobia of enclosed public spaces.", "Panic disorder, since the fear centers on panic-like symptoms.", "Social anxiety about being observed while symptomatic."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Agoraphobia involves fear or avoidance of situations where escape may be difficult or help unavailable if panic-like symptoms occur."}, {"id": "q072", "text": "A client experiences recurrent nightmares and hypervigilance after years of childhood abuse. Which clinical lens is most helpful?", "options": ["Borderline personality pathology as the primary organizing conceptualization.", "PTSD from a single index event, treated with a brief exposure protocol.", "Generalized anxiety with trauma-themed worry content across domains.", "Complex trauma and its effects on affect regulation, relationships, and self-concept."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Chronic interpersonal trauma can affect affect regulation, relationships, self-concept, trust, and safety."}, {"id": "q073", "text": "An older adult client reports memory decline, medication changes, and sudden confusion. What clinical focus is most important?", "options": ["Normal age-related decline calling for reassurance rather than further workup.", "Differentiate mental health symptoms from medical, medication, delirium, or neurocognitive concerns.", "Begin cognitive testing for dementia staging before any medical review occurs.", "Late-onset depression presenting as pseudodementia, to be treated with counseling before medical workup."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Sudden confusion may indicate delirium or medical issues; older adult assessment should consider medical, medication, mood, and cognitive factors."}, {"id": "q074", "text": "A client who immigrated recently reports sadness, isolation, and identity strain. Which focus is most culturally responsive?", "options": ["Premigration trauma presumed to be the primary cause of the current symptoms.", "Culture-bound beliefs to be carefully assessed for possible delusional intensity.", "Acculturation stress, migration history, supports, discrimination, loss, and resilience.", "A major depressive episode best treated with standard first-line protocols for mood."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Migration and acculturation can involve loss, stress, discrimination, identity strain, and resilience."}, {"id": "q075", "text": "A client reports repeated job loss due to conflict with supervisors and rigid perfectionism. Which area may be clinically relevant?", "options": ["An adjustment disorder arising from the accumulated job losses.", "Generalized anxiety expressed through recurring workplace conflict.", "Personality patterns, interpersonal functioning, and occupational impairment.", "Obsessive-compulsive disorder, given the perfectionistic standards."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Persistent interpersonal and personality patterns can contribute to impairment and may be a focus of assessment."}, {"id": "q076", "text": "A child has separation distress, nightmares about caregivers dying, and refusal to attend school. Which concern is most relevant?", "options": ["A specific phobia of school and its performance demands.", "Separation anxiety symptoms.", "Generalized anxiety with worries that include the caregivers.", "An attachment disorder rooted in early caregiving disruption."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Separation anxiety involves excessive fear concerning separation from attachment figures and can impair school attendance."}, {"id": "q077", "text": "A client experiences obsessions about harming others but finds the thoughts horrifying and avoids knives. What is the best conceptual focus?", "options": ["Emerging psychosis, since the thought content involves harming others.", "Homicidal ideation warranting a full duty-to-protect analysis.", "An impulse-control disorder requiring ongoing safety monitoring.", "Intrusive ego-dystonic obsessions and compulsive avoidance in OCD."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "OCD harm obsessions are typically unwanted and distressing; clinicians still assess safety but conceptualize ego-dystonic intrusions carefully."}, {"id": "q078", "text": "A college student reports using stimulants without a prescription to study and needing higher amounts. Which area should be assessed?", "options": ["Stimulant misuse, tolerance, impairment, medical risk, and academic pressures.", "Performance anxiety driving the reliance on study aids.", "Undiagnosed ADHD, since the stimulants improve the client's studying.", "Normative collegiate use comparable to heavy caffeine reliance."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Nonmedical stimulant use can involve substance use risk, tolerance, health consequences, and academic functioning."}, {"id": "q079", "text": "A client reports persistent fatigue, low mood, and appetite changes after beginning a new medication. What should the counselor consider?", "options": ["Somatic symptom amplification maintained by health-related worry.", "Medication or medical contributors while continuing mental health assessment.", "A recurrence of major depression independent of the new medication.", "Disrupted sleep hygiene as the sufficient explanation for the fatigue."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Counselors consider medical and medication factors and coordinate care when symptoms may have physical contributors."}, {"id": "q080", "text": "A client has intense fear of gaining weight but is medically stable. What is still necessary?", "options": ["Weekly outpatient counseling accepted as sufficient, given the current medical stability.", "Family-based treatment alone, since eating disorders are fundamentally relational.", "Ongoing assessment of eating disorder severity, medical risk, and appropriate level of care.", "Body-image work first, deferring any direct discussion of weight and food until later."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Eating disorders can carry serious medical risk even before obvious instability; level of care and medical coordination matter."}, {"id": "q081", "text": "A client reports compulsive pornography use that conflicts with values and relationships. What should the counselor assess first?", "options": ["The values conflict alone, since the behavior itself is statistically normative.", "Underlying attachment injuries presumed to be driving the compulsive behavior patterns.", "A behavioral addiction framework applied from the outset of treatment.", "Function, impairment, compulsivity, shame, values, relational impact, and co-occurring concerns."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Counselors assess behavior function, impairment, distress, values, compulsivity, and relational context without imposing values."}, {"id": "q082", "text": "A client recently lost employment and reports identity loss, shame, and family conflict. Which clinical focus is most relevant?", "options": ["Adjustment, grief, mood, family stress, financial strain, and coping resources.", "Family systems treatment before any individual assessment.", "An occupational problem best referred to career services alone.", "A major depressive episode, given the reported shame and profound loss of identity."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Employment loss can create adjustment stress, grief, identity disruption, relational strain, and mood symptoms."}, {"id": "q083", "text": "A client has repeated intrusive health worries despite medical reassurance and frequently checks symptoms online. Which focus is most relevant?", "options": ["Obsessive-compulsive checking as the primary clinical process.", "Health anxiety and reassurance-seeking patterns.", "Somatic symptom disorder, given the focus on bodily complaints.", "A delusional conviction of illness requiring reality testing."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Health anxiety often involves preoccupation with illness, checking, reassurance seeking, and persistent distress despite reassurance."}, {"id": "q084", "text": "A client reports episodes of binge eating without compensatory behaviors and feels shame and loss of control. Which clinical focus is most relevant?", "options": ["Bulimia nervosa, given the recurrent episodes involving a felt loss of control.", "Night-eating patterns tied to circadian and sleep disruption.", "Binge-eating symptoms, shame, impairment, and medical/psychological factors.", "Emotional eating within normal limits, given the shame response."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Binge-eating disorder involves recurrent binge episodes with loss of control and distress, without regular compensatory behaviors."}, {"id": "q085", "text": "A client reports flashbacks and panic when smelling smoke after a house fire. Which process is most relevant?", "options": ["A conditioned specific phobia of fire and smoke.", "Olfactory hallucinations warranting psychotic assessment.", "Panic disorder with an identifiable situational trigger.", "Trauma cue reactivity."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Trauma reminders can trigger physiological, emotional, and sensory re-experiencing symptoms."}, {"id": "q086", "text": "A client has persistent conflict with family over caregiving for an aging parent. Which focus may be appropriate?", "options": ["Family roles, caregiver stress, boundaries, grief, and support resources.", "Anticipatory grief about the parent's decline treated as the sole clinical concern.", "A relational problem coded without any clinical focus.", "Caregiver burnout addressed only through a respite referral."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Caregiving can involve role strain, boundaries, grief, burnout, relational conflict, and support needs."}, {"id": "q087", "text": "A client reports being bullied at school and now avoids lunch, has stomachaches, and feels worthless. What focus is most relevant?", "options": ["A peer conflict best left to the school's administrative discipline channels.", "Social skills deficits treated as the primary target of intervention.", "Bullying impact, safety, anxiety, depression, somatic symptoms, and school supports.", "Somatic symptom disorder, given the pattern of recurring stomachaches at school."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Bullying can affect safety, mood, anxiety, somatic complaints, school attendance, and self-worth."}, {"id": "q088", "text": "A client describes recurrent nightmares after military service and uses anger to keep people away. Which clinical focus is most relevant?", "options": ["An anger problem best treated through skills groups alone.", "Depressive irritability, given the pattern of social withdrawal.", "Intermittent explosive episodes as the central clinical concern.", "Trauma-related arousal, avoidance, relational impact, and coping."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "PTSD can include hyperarousal, anger, avoidance, sleep disruption, and interpersonal withdrawal."}, {"id": "q089", "text": "A client experiences low mood every winter with improved mood in spring. Which clinical focus should be considered?", "options": ["A medical deficiency to be ruled out before any mood diagnosis.", "Seasonal pattern of depressive symptoms.", "Cyclothymia, given the recurring mood shifts across the year.", "Persistent depressive disorder worsening under winter stress."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Seasonal recurrence of depressive symptoms may suggest a seasonal pattern and should be assessed for severity, impairment, and risk."}, {"id": "q090", "text": "A parent reports a child has repetitive restricted interests, sensory sensitivities, and social communication differences. Which focus is most relevant?", "options": ["Autism spectrum characteristics and functional supports.", "ADHD, given the intense focus on preferred activities.", "Social anxiety producing avoidance of peer interaction.", "Sensory processing differences without broader developmental relevance."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Autism assessment considers social communication differences, restricted/repetitive behaviors, sensory patterns, development, and supports."}, {"id": "q091", "text": "A client who survived a natural disaster has insomnia, startle response, and survivor guilt. Which clinical focus is most relevant?", "options": ["An adjustment disorder, since the disaster was a shared community event.", "Disaster-related trauma, grief, guilt, and stabilization needs.", "Generalized anxiety expressed through disaster-themed worry.", "Uncomplicated grief best supported through community ritual."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Disasters can produce trauma symptoms, loss, guilt, instability, and practical recovery needs."}, {"id": "q092", "text": "A client reports sexual pain and anxiety about intimacy after a medical procedure. Which response best reflects an appropriate clinical focus?", "options": ["Manage the intimacy-related performance anxiety with relaxation techniques alone.", "Treat the pain condition medically first, deferring all related counseling work until the pain fully resolves.", "Assess medical coordination, anxiety, relational impact, consent, and sexual functioning with sensitivity.", "Address the relationship discord primarily through conjoint couples counseling sessions."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Sexual concerns may involve medical, psychological, relational, trauma, and consent factors and require sensitive assessment."}, {"id": "q093", "text": "A client with a disability reports workplace discrimination and internalized shame. Which clinical focus is most relevant?", "options": ["Workplace mediation pursued before any clinical work begins.", "Depressive symptoms understood as inherent to the disability itself.", "Adjustment to disability framed as an individual acceptance process only.", "Disability identity, discrimination, advocacy, coping, and mental health impact."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Counselors consider disability-related barriers, stigma, identity, accessibility, advocacy, and mental health."}, {"id": "q094", "text": "A client reports explosive anger followed by remorse and relationship damage. Which focus is clinically relevant?", "options": ["Emotion regulation, triggers, safety, accountability, and interpersonal repair.", "A normal stress response, given the genuine remorse that follows.", "Assertiveness deficits producing periodic emotional overcorrection.", "Intermittent explosive disorder requiring formal diagnosis before treatment."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Problematic anger work assesses triggers, regulation, safety, harm, responsibility, and relational patterns."}, {"id": "q095", "text": "A client has repeated panic-like symptoms only when using cannabis. Which clinical focus is most relevant?", "options": ["Panic disorder that happens to co-occur with the cannabis use.", "Generalized anxiety intensified by academic and life stress.", "Substance-induced anxiety symptoms and cannabis use patterns.", "Social anxiety emerging in the settings where cannabis is used."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Substances can induce or worsen anxiety symptoms; assessment should consider timing, dose, frequency, and impairment."}, {"id": "q096", "text": "A client reports chronic emptiness, unstable identity, and impulsive spending. Which clinical area should be assessed?", "options": ["A dissociative process underlying the identity instability.", "Personality functioning, mood, impulsivity, and safety risk.", "Bipolar II disorder, given the episodes of impulsive spending.", "Adult ADHD, given the impulsivity and difficulty sustaining direction."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Chronic emptiness, identity disturbance, and impulsivity may indicate personality-related concerns and require careful assessment."}, {"id": "q097", "text": "A client describes repeated unwanted memories and avoidance after witnessing violence at work. Which focus is most relevant?", "options": ["An acute stress response expected to remit without focused assessment.", "Cumulative burnout from ongoing workplace stressors.", "An occupational phobia of the worksite where the violence occurred.", "Secondary or direct trauma exposure and posttraumatic symptoms."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Witnessing violence can be traumatic and may produce intrusive memories, avoidance, arousal, and mood changes."}, {"id": "q098", "text": "A client reports gambling, sexual risk-taking, and little sleep during periods of unusually high energy. Which focus should be assessed?", "options": ["Bipolar-spectrum symptoms and risk behaviors.", "Cluster B personality traits expressed under acute stress.", "An impulse-control disorder spanning the gambling and sexual behavior.", "Substance-driven episodes to be assumed as the default explanation."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Risk-taking with decreased sleep and elevated energy may indicate manic or hypomanic episodes and requires safety assessment."}, {"id": "q099", "text": "A client reports persistent fear of vomiting in public and avoids restaurants. Which clinical focus is most relevant?", "options": ["Specific phobia or anxiety-related avoidance with functional impairment.", "Illness anxiety centered on gastrointestinal disease.", "Social anxiety about negative evaluation while eating with others.", "Panic disorder, given the fear of losing control in public settings."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Specific phobias can involve circumscribed fears that lead to avoidance and functional impairment."}, {"id": "q100", "text": "A client reports grief after a miscarriage and feels isolated because others minimize the loss. Which clinical focus is most appropriate?", "options": ["Complicated grief requiring immediate specialized treatment.", "Postpartum depression requiring standard perinatal protocols.", "Reproductive grief, disenfranchised grief, support, meaning, and mood risk.", "An adjustment disorder, given how early the pregnancy loss occurred."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Miscarriage can involve profound and sometimes disenfranchised grief; counseling should assess support, meaning, trauma, mood, and risk."}, {"id": "q101", "text": "A client reports persistent shame after religious community rejection. Which focus is clinically relevant?", "options": ["Depressive cognitions treated independently of the religious context.", "A faith crisis best referred to clergy rather than addressed in counseling.", "Scrupulosity, given the religious content of the distress.", "Spiritual/religious injury, identity, support, values, and trauma-related symptoms."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Spiritual and religious experiences can be clinically significant and should be handled with respect, cultural humility, and client-centered values."}, {"id": "q102", "text": "A client has recurrent checking of locks for hours, causing lateness to work. What is the main clinical impairment?", "options": ["Perfectionistic conscientiousness that has become inconvenient.", "Compulsions are consuming time and impairing occupational functioning.", "Executive dysfunction producing planning and punctuality problems.", "Anxiety that will subside once the underlying worry is resolved."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "OCD-related compulsions become clinically significant when time-consuming, distressing, or impairing."}, {"id": "q103", "text": "A client reports emotional numbness, avoidance, and guilt after placing a parent in long-term care. Which focus is most relevant?", "options": ["Caregiver grief, role transition, guilt, and coping resources.", "Complicated grief, even though the parent is still living.", "Family conflict best addressed through conjoint sessions.", "A depressive episode requiring symptom-focused treatment first."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Caregiving transitions can involve grief, guilt, relief, family conflict, and identity changes."}, {"id": "q104", "text": "A client reports persistent worry about deportation, family separation, and safety. Which clinical focus should be prioritized?", "options": ["An adjustment disorder expected to remit naturally as the family settles in.", "Generalized anxiety presenting with catastrophic worry content about the future.", "Contextual stressors, legal vulnerability, trauma, family support, and safety planning.", "Paranoid ideation that should be gently reality-tested within sessions."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Counselors assess sociopolitical and contextual stressors without mislabeling realistic fears as pathology."}, {"id": "q105", "text": "A client with diabetes reports feeling defeated and skipping medical care. Which focus is clinically relevant?", "options": ["Noncompliance reflecting low motivation, to be confronted directly.", "A grief reaction to the diagnosis, treated apart from the medical care.", "Somatic preoccupation with the chronic medical condition.", "Health-related adjustment, depression, adherence barriers, and care coordination."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Chronic illness affects mood, behavior, identity, and functioning; coordination with medical providers may be important."}, {"id": "q106", "text": "A client reports persistent insomnia, racing thoughts at night, and worry about sleep. Which focus is most relevant?", "options": ["Primary insomnia treated through a course of sleep restriction alone.", "Sleep disturbance, anxiety cycle, routines, and possible medical or substance contributors.", "A ruminative depressive process underlying and actively maintaining the nightly sleeplessness.", "Nocturnal panic attacks driving the client's repeated nighttime awakenings."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Sleep problems can interact with anxiety, mood, substances, medical factors, and daily functioning."}, {"id": "q107", "text": "Which treatment goal is written in the most measurable form?", "options": ["Client will use two coping skills to reduce panic-related avoidance from five days per week to two days per week within eight weeks.", "Client will reduce panic-related avoidance and report meaningfully improved daily functioning at school and at work.", "Client will decrease avoidance behaviors as observed by the counselor over the course of treatment.", "Client will practice new coping skills regularly and manage panic-related anxiety much more effectively across everyday situations."], "correct": 0, "domain": "Treatment Planning", "explanation": "Effective treatment goals are specific, measurable, attainable, relevant, and time-linked when appropriate."}, {"id": "q108", "text": "A client with severe alcohol withdrawal risk wants outpatient counseling only. What should the treatment plan prioritize?", "options": ["An intensive outpatient group added to bring accountability to the weekly counseling sessions.", "A harm-reduction taper at home, tracked through daily drinking logs.", "Motivational interviewing to strengthen commitment before any referral.", "Medical evaluation and appropriate level of care before routine outpatient counseling."], "correct": 3, "domain": "Treatment Planning", "explanation": "Treatment planning must consider safety and level of care; withdrawal risk may require medical management."}, {"id": "q109", "text": "A counselor and client identify depression, isolation, and job loss. What should happen next in collaborative treatment planning?", "options": ["Address the job loss first, since practical needs must precede clinical goals in planning.", "Prioritize goals with the client and link objectives and interventions to the client's needs and strengths.", "Begin the interventions right away and formalize the written goals once rapport deepens.", "Draft a complete set of measurable objectives and present them to the client for review and final approval."], "correct": 1, "domain": "Treatment Planning", "explanation": "Treatment plans should be collaborative, individualized, diagnosis-informed, culturally responsive, and strength-based."}, {"id": "q110", "text": "A client is in precontemplation about substance use. Which treatment plan objective fits best?", "options": ["Set a firm quit date within the next two weeks to capitalize on the momentum of treatment entry.", "Teach refusal skills and relapse prevention strategies at the very outset of treatment.", "Increase awareness of consequences and explore ambivalence without demanding immediate abstinence.", "Contract for reduced use, monitored through weekly self-report drinking logs."], "correct": 2, "domain": "Treatment Planning", "explanation": "Stages of change guide realistic objectives; precontemplation often begins with awareness, engagement, and ambivalence exploration."}, {"id": "q111", "text": "Which element is essential in a crisis treatment plan for a suicidal client?", "options": ["A written no-harm contract signed by the client and witnessed again at each session.", "Daily supportive check-in calls from the counselor until the ideation fully resolves.", "Warning signs, coping steps, social supports, emergency resources, means safety, and follow-up.", "Removal of identified stressors and hospitalization whenever any ideation appears."], "correct": 2, "domain": "Treatment Planning", "explanation": "Crisis planning focuses on actionable safety steps, supports, means safety, emergency contacts, and follow-up."}, {"id": "q112", "text": "A client has PTSD and unstable housing. Which treatment planning principle is most appropriate?", "options": ["Resolve the housing crisis fully before any clinical work begins.", "Begin the evidence-based exposure work promptly, since any delay reduces its effectiveness.", "Refer the housing needs to case management and keep counseling strictly clinical.", "Address stabilization and practical barriers while planning trauma treatment at a safe pace."], "correct": 3, "domain": "Treatment Planning", "explanation": "Treatment planning considers safety, stabilization, resources, barriers, and readiness before intensive trauma processing."}, {"id": "q113", "text": "What is the best reason to revise a treatment plan?", "options": ["New assessment information shows the client's needs, risks, goals, or progress have changed.", "The insurer requests updated treatment documentation for continued authorization.", "A routinely scheduled ninety-day review date arrives on the program calendar.", "The client reports an unusually difficult and stressful week at the latest session."], "correct": 0, "domain": "Treatment Planning", "explanation": "Treatment plans are living documents revised when new information, progress, barriers, risk, or goals require changes."}, {"id": "q114", "text": "A client is preparing for discharge after meeting treatment goals. What should the plan include?", "options": ["An open-ended extension of the treatment schedule to guard against any possible recurrence.", "Relapse prevention, warning signs, supports, follow-up options, and steps for returning if needed.", "A gradual increase in session frequency to consolidate gains before ending.", "A final review of progress, with future contact discouraged to support independence."], "correct": 1, "domain": "Treatment Planning", "explanation": "Discharge planning supports maintenance of gains and continuity of care."}, {"id": "q115", "text": "A client wants to reduce anxiety but refuses any mindfulness intervention due to religious concerns. What is the best treatment planning response?", "options": ["Collaboratively select acceptable evidence-informed alternatives that respect the client's values.", "Substitute a psychiatric medication referral for the skills component of the plan.", "Present the supporting outcome research so the client can reconsider the refusal.", "Reframe the mindfulness intervention in fully secular language and proceed with it exactly as planned."], "correct": 0, "domain": "Treatment Planning", "explanation": "Treatment planning should respect client values and use collaborative, culturally responsive intervention selection."}, {"id": "q116", "text": "A counselor writes a plan for a child without input from caregivers or school, despite school impairment. What is the main weakness?", "options": ["The plan overreaches by targeting school behavior beyond the counseling setting.", "The plan lacks standardized testing to justify the school-related goals.", "The objectives rest on caregiver report rather than direct observation.", "The plan lacks relevant system collaboration and collateral information."], "correct": 3, "domain": "Treatment Planning", "explanation": "Child treatment often requires developmentally appropriate collaboration with caregivers, schools, and other systems while respecting consent and confidentiality."}, {"id": "q117", "text": "Which treatment plan objective best matches CBT for depression?", "options": ["Client will replace negative thoughts with positive affirmations practiced daily each morning and evening.", "Client will identify and evaluate three recurring automatic thoughts related to worthlessness each week.", "Client will achieve stable improvement in mood ratings within eight weeks.", "Client will process the developmental origins of the worthlessness schema in session."], "correct": 1, "domain": "Treatment Planning", "explanation": "CBT objectives often target automatic thoughts, behavioral activation, skills practice, and measurable symptom change."}, {"id": "q118", "text": "A client has panic disorder and avoids grocery stores. Which intervention should be considered in the plan?", "options": ["Relaxation training to be fully mastered before any store visits occur.", "Cognitive restructuring alone, since behavior change follows changed thinking.", "Graduated exposure to feared situations paired with coping and cognitive strategies.", "Safety accommodations such as shopping with a companion at low-traffic times."], "correct": 2, "domain": "Treatment Planning", "explanation": "Exposure-based interventions reduce avoidance and fear through planned, gradual contact with feared cues or situations."}, {"id": "q119", "text": "A client with bipolar disorder wants counseling but is not connected to medication management. What should the treatment plan consider?", "options": ["A mood-monitoring phase to confirm the diagnosis before involving prescribers.", "Psychoeducation about mood episodes in place of a psychiatric referral.", "Coordination or referral for psychiatric evaluation while addressing psychosocial goals.", "Documentation that medication was declined, with counseling proceeding as usual."], "correct": 2, "domain": "Treatment Planning", "explanation": "Bipolar presentations often require coordinated care, risk monitoring, psychoeducation, and psychosocial support."}, {"id": "q120", "text": "What is the best treatment planning response when a client faces transportation barriers?", "options": ["Document the transportation barrier thoroughly while keeping the treatment plan otherwise unchanged.", "Transfer the client's care to another qualified provider whose office is located much closer to the client's home.", "Add a motivational enhancement component addressing the client's engagement with the treatment process.", "Identify barriers and adapt the plan through telehealth, referrals, scheduling, or resource coordination when appropriate."], "correct": 3, "domain": "Treatment Planning", "explanation": "Barriers to goal attainment should be assessed and addressed through practical, ethical, and clinically appropriate modifications."}, {"id": "q121", "text": "Which plan best reflects trauma-informed care?", "options": ["Emphasize safety, choice, collaboration, empowerment, stabilization, and paced trauma work.", "Center the counselor's protocol expertise in order to provide needed structure.", "Prioritize rapid symptom reduction through intensive exposure early in treatment.", "Screen for trauma once at intake and revisit it only if the symptoms worsen."], "correct": 0, "domain": "Treatment Planning", "explanation": "Trauma-informed treatment planning prioritizes safety, choice, collaboration, empowerment, cultural responsiveness, and pacing."}, {"id": "q122", "text": "A client and counselor disagree about treatment goals. What should the counselor do?", "options": ["Defer entirely to the client's goals, since autonomy overrides clinical judgment.", "Explore the disagreement, clarify priorities, and collaboratively revise goals when appropriate.", "Proceed with both sets of goals in parallel to honor each perspective.", "Pause the goal-setting process until the alliance is strong enough to prevent further conflict."], "correct": 1, "domain": "Treatment Planning", "explanation": "Collaborative goal setting strengthens alliance and increases relevance, motivation, and accountability."}, {"id": "q123", "text": "A client with OCD wants reassurance-only sessions. What should the plan address?", "options": ["Reduce reassurance-seeking while building exposure, response prevention, and distress tolerance.", "Teach thought-stopping techniques designed to interrupt the obsessional cycle.", "Provide reassurance on a gradually fading schedule to taper the need over time.", "Explore the childhood origins of the client's need for absolute certainty before beginning any exposure."], "correct": 0, "domain": "Treatment Planning", "explanation": "For OCD, reassurance can become a compulsion; ERP targets obsessions, compulsions, avoidance, and distress tolerance."}, {"id": "q124", "text": "Which treatment plan is most appropriate for co-occurring depression and alcohol misuse?", "options": ["Sequential treatment beginning with stable sobriety, then turning to the mood symptoms.", "Integrated planning that addresses mood, substance use, risk, coping, and relapse prevention together.", "Parallel referrals arranged so that each condition is treated separately by its own dedicated specialist.", "Mood-focused treatment first, on the premise that the drinking is self-medication."], "correct": 1, "domain": "Treatment Planning", "explanation": "Co-occurring concerns are often best addressed through integrated, coordinated planning rather than isolated or sequential neglect of one condition."}, {"id": "q125", "text": "A client says, 'I know I need to change, but part of me does not want to give up drinking.' Which response best reflects motivational interviewing?", "options": ["What would it take for you to commit fully to quitting today?", "You have good reasons to quit, and I believe you are ready to take that step.", "Part of you wants change, and part of you is unsure what life would look like without alcohol.", "Many of my clients feel this way at first; the ambivalence usually fades once abstinence begins."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Motivational interviewing uses reflective listening to explore ambivalence and evoke client motivation rather than arguing or confronting prematurely."}, {"id": "q126", "text": "Which counselor statement is an accurate reflection of feeling?", "options": ["It makes complete sense that you would be upset in that situation.", "So your friend canceled after you had already made the plans.", "What went through your mind when your friend did not show?", "You sound hurt and disappointed that your friend did not show up."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Reflection of feeling identifies and tentatively names the emotional meaning in the client's message."}, {"id": "q127", "text": "A client gives a long description of several conflicts. Which skill helps organize the material and check understanding?", "options": ["Clarifying questions.", "Reflection of meaning.", "Summarizing.", "Paraphrasing."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Summarizing condenses themes, sequence, emotions, and content to promote clarity and collaboration."}, {"id": "q128", "text": "Which question is most open-ended?", "options": ["Can you tell me whether the argument is resolved now?", "What has this week been like for you since the argument?", "Did the coping skills we practiced help you this week?", "Would you say the week has been mostly good or mostly bad?"], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Open-ended questions invite elaboration and help clients describe experiences in their own words."}, {"id": "q129", "text": "In CBT, what is the primary purpose of identifying automatic thoughts?", "options": ["To identify the core schemas formed in early development.", "To generate replacement thoughts the client can rehearse daily.", "To demonstrate that anxious predictions rarely come true.", "To examine how interpretations contribute to emotions and behaviors."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "CBT links thoughts, emotions, behaviors, and physiology; automatic thoughts are evaluated and modified when unhelpful."}, {"id": "q130", "text": "A client with panic avoids increased heart rate. Which intervention is commonly used in exposure-based CBT?", "options": ["Interoceptive exposure to feared bodily sensations in a planned and safe way.", "Gradual in-vivo exposure to the places where panic has previously occurred.", "Diaphragmatic breathing to lower baseline arousal before any exposure.", "Cognitive reappraisal of the feared heart-rate sensations."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Interoceptive exposure helps clients learn that feared sensations are tolerable and not necessarily dangerous."}, {"id": "q131", "text": "In ERP for OCD, what does response prevention mean?", "options": ["Refraining from the compulsion after exposure to an obsessional trigger.", "Substituting a less disruptive ritual for the original compulsion.", "Delaying the compulsion briefly and permitting it once distress peaks.", "Pairing each exposure with relaxation so anxiety stays manageable."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Response prevention reduces compulsive rituals that maintain the obsession-compulsion cycle."}, {"id": "q132", "text": "A client says, 'I am a total failure because I made one mistake.' Which CBT distortion is most evident?", "options": ["Personalization.", "Mental filter.", "All-or-nothing thinking.", "Catastrophizing."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "All-or-nothing thinking views outcomes in extreme categories rather than balanced degrees."}, {"id": "q133", "text": "Which intervention best represents behavioral activation?", "options": ["Exploring the significant losses that preceded the client's withdrawal from activity.", "Scheduling meaningful or mastery-building activities even before motivation returns.", "Relaxation training to reduce the discomfort of inactivity.", "Identifying the cognitive distortions that block the client's motivation."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Behavioral activation targets the withdrawal cycle by increasing reinforcing, valued, or mastery-based activities."}, {"id": "q134", "text": "A counselor says, 'On one hand you want independence, and on the other you fear disappointing your parents.' Which skill is being used?", "options": ["Confrontation of discrepancy.", "Summarizing.", "Reframing.", "Double-sided reflection."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "A double-sided reflection captures both sides of ambivalence without forcing resolution."}, {"id": "q135", "text": "Which response best demonstrates immediacy?", "options": ["I wonder what it is that makes trust feel so risky for you.", "I notice that as we talk about trust, you look away and become quieter with me too.", "Trust has clearly been difficult in many of your relationships over the years.", "You seem quieter today than you have been in our previous sessions."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Immediacy uses the here-and-now counseling relationship to explore patterns as they emerge in session."}, {"id": "q136", "text": "Which counselor behavior best supports the therapeutic alliance?", "options": ["Adjusting interventions weekly to keep the sessions engaging.", "Maintaining consistently warm rapport while keeping the treatment goals flexible and unstated.", "Agreeing with the client's perspective to avoid alliance ruptures.", "Collaboratively setting goals, showing empathy, and agreeing on tasks of counseling."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "The alliance includes bond, agreement on goals, and agreement on tasks."}, {"id": "q137", "text": "A client becomes highly distressed during trauma work. Which intervention is most appropriate first?", "options": ["Shift to cognitive processing of the traumatic memory rather than continued imaginal work.", "Continue at a gentler pace so the exposure is not interrupted.", "Pause, orient to safety, use grounding, and assess the client's window of tolerance.", "Schedule a medication consultation before resuming trauma content."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Trauma interventions require pacing, grounding, stabilization, and attention to safety and tolerance."}, {"id": "q138", "text": "Which intervention is most consistent with solution-focused counseling?", "options": ["Ask about exceptions and times when the problem is less intense.", "Interpret the pattern that maintains the problem across relationships.", "Explore the history of the problem to understand its function.", "Assign between-session monitoring of the symptom's intensity."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Solution-focused counseling emphasizes exceptions, strengths, preferred future, scaling, and small next steps."}, {"id": "q139", "text": "In person-centered counseling, which condition involves being real and transparent within professional boundaries?", "options": ["Congruence or genuineness.", "Unconditional positive regard.", "Accurate empathic understanding.", "Therapeutic transparency through self-disclosure."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Congruence refers to the counselor's authenticity and genuineness in the therapeutic relationship."}, {"id": "q140", "text": "Which intervention best reflects unconditional positive regard?", "options": ["Expressing empathy for the feelings while correcting the distorted thinking.", "Maintaining strict neutrality by withholding personal reactions to disclosures.", "Consistently affirming the client's choices in order to strengthen self-efficacy.", "Communicating acceptance of the client's worth while still addressing harmful behavior."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Unconditional positive regard means valuing the person without making acceptance conditional on behavior."}, {"id": "q141", "text": "A client says, 'Nothing ever works.' Which ACT-consistent intervention may help?", "options": ["Trace the origins of the hopelessness back through the client's earlier formative experiences of failure.", "Teach relaxation skills so the feeling becomes less intense before any action gets taken.", "Clarify values and identify a committed action the client can take while making room for difficult feelings.", "Challenge the accuracy of the hopeless thought by examining all of the contrary evidence."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "ACT emphasizes values, acceptance, defusion, present-moment awareness, self-as-context, and committed action."}, {"id": "q142", "text": "Which DBT skill teaches clients to notice emotions, thoughts, and urges without immediately acting on them?", "options": ["Radical acceptance.", "Mindfulness.", "Emotion regulation.", "Distress tolerance."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "DBT mindfulness helps clients observe, describe, and participate with awareness and reduced impulsivity."}, {"id": "q143", "text": "A client is overwhelmed by emotion and at risk of impulsive behavior. Which DBT skill area is most immediately relevant?", "options": ["Emotion regulation.", "Distress tolerance.", "Interpersonal effectiveness.", "Mindfulness."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Distress tolerance skills help clients survive crises without making them worse."}, {"id": "q144", "text": "Which intervention best represents psychoeducation?", "options": ["Normalizing the anxiety as a common and understandable human experience.", "Guiding the client toward discovery through Socratic questioning about the anxiety.", "Teaching a client how anxiety activates the fight-or-flight system and how avoidance maintains fear.", "Collaboratively developing a graduated fear hierarchy with the client in preparation for exposure work."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Psychoeducation provides accurate information that increases understanding, self-efficacy, and treatment engagement."}, {"id": "q145", "text": "What is the main purpose of a genogram?", "options": ["To visually map family structure, relationships, patterns, and intergenerational themes.", "To chart the frequency of symptoms across the family members over time.", "To assess the family members' readiness to participate in conjoint sessions.", "To document the client's current household composition thoroughly for the intake record."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Genograms help counselors explore family patterns, roles, boundaries, losses, and intergenerational dynamics."}, {"id": "q146", "text": "In Bowen family systems theory, differentiation refers to which capacity?", "options": ["Managing anxiety by limiting contact with reactive family members.", "Prioritizing personal goals over the expectations of the family.", "Establishing firm boundaries that keep emotion out of family decisions.", "Maintaining a clear sense of self while staying emotionally connected to others."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Differentiation involves balancing autonomy and connection without being dominated by emotional reactivity."}, {"id": "q147", "text": "Which intervention is most consistent with narrative therapy?", "options": ["Externalize the problem and explore alternative stories of identity and agency.", "Interpret the story's recurring themes as expressions of unconscious material.", "Identify the irrational beliefs embedded within the client's story.", "Reframe the problem as serving a protective function for the client."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Narrative therapy separates the person from the problem and thickens preferred identity stories."}, {"id": "q148", "text": "A group member monopolizes discussion. What should the group counselor do?", "options": ["Use structured go-arounds so every member receives equal speaking time.", "Intervene to protect group process by reflecting the pattern and inviting broader participation.", "Allow the group to address the pattern naturally over time, since members shape their own working norms.", "Meet with the member individually and ask them to speak less in group."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Group leaders manage process, promote safety, and balance participation while respecting members."}, {"id": "q149", "text": "Which group stage is commonly associated with deeper cohesion, risk-taking, and productive work?", "options": ["Storming stage.", "Transition stage.", "Norming stage.", "Working stage."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "The working stage typically involves trust, cohesion, deeper exploration, feedback, and behavior change."}, {"id": "q150", "text": "A client asks for direct advice about whether to divorce. Which response best fits counseling practice?", "options": ["Remain entirely silent on the divorce question to avoid influencing what must be an autonomous client decision.", "Assign a decisional balance worksheet and then endorse the option showing greater benefits.", "Help the client clarify values, options, risks, supports, and consequences rather than deciding for the client.", "Share what the counselor would personally do in the same situation, labeled clearly as opinion."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Counselors support autonomy and decision-making without imposing major life decisions."}, {"id": "q151", "text": "Which response best demonstrates empathy rather than sympathy?", "options": ["That must be hard, but you are clearly strong enough to handle it.", "I feel so sad hearing everything that you have been through.", "I went through something very similar, so I truly understand this.", "You have been carrying this alone for a long time, and it feels exhausting."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Empathy communicates understanding of the client's experience from the client's perspective."}, {"id": "q152", "text": "A client says, 'I am fine,' while crying and clenching fists. What skill is most appropriate?", "options": ["Respect the client's stated experience and revisit the feelings later.", "Gently reflect the discrepancy between words and nonverbal behavior.", "Reflect the stated content so the client feels heard before probing.", "Offer quiet space until the client is ready to name the feeling."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Counselors can use gentle confrontation or reflection to explore discrepancies without shaming the client."}, {"id": "q153", "text": "Which intervention best reflects career counseling assessment?", "options": ["Explore interests, values, abilities, personality, labor information, barriers, and life roles.", "Clarify the client's ideal work-life vision in depth before gathering any formal assessment data.", "Match the client's aptitude profile to current openings in the local labor market.", "Administer an interest inventory and build the career plan from its top scores."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Career counseling integrates self-knowledge, occupational information, context, barriers, and decision-making."}, {"id": "q154", "text": "Which counseling response best uses a scaling question?", "options": ["How confident are you feeling right now about using that coping skill during the coming week?", "What would full confidence in using that skill actually look like for you?", "On a scale from 0 to 10, where are you today in your confidence to use that coping skill?", "Compared to last week, would you say your confidence is higher or lower now?"], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Scaling questions assess perception, progress, confidence, motivation, and next steps."}, {"id": "q155", "text": "A client is grieving and says, 'I should be over this by now.' Which intervention is most helpful?", "options": ["Introduce the stages of grief so the client can locate their own progress.", "Explore whether the guilt reflects unresolved conflict with the deceased.", "Normalize variability in grief while exploring meaning, support, and functioning.", "Assess for persistent complex bereavement, given how long the grief has lasted."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Grief counseling validates individual and cultural variation while assessing impairment, support, meaning, and risk."}, {"id": "q156", "text": "Which intervention best represents crisis counseling?", "options": ["Process the precipitating event in depth to release the underlying affect.", "Build durable long-term coping skills so that the crisis does not recur.", "Normalize the client's reactions and schedule a standard intake appointment for the following week.", "Ensure safety, stabilize, identify supports, address immediate needs, and plan next steps."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Crisis work prioritizes safety, stabilization, practical support, coping, and connection to resources."}, {"id": "q157", "text": "Which counselor response is most consistent with broaching cultural identity?", "options": ["Would it be helpful for us to talk about how culture or identity may shape what you are experiencing here?", "I want you to know I treat every client with the same respect regardless of background.", "If culture or identity ever feels relevant to you, please feel completely free to bring it up in our work together.", "Tell me about your cultural background so that I can better understand your situation."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Broaching invites culturally relevant discussion with humility and client choice."}, {"id": "q158", "text": "A client repeatedly asks whether the counselor is disappointed in them. Which intervention may be useful?", "options": ["Provide the requested reassurance warmly each time and note the frequency of the requests in the clinical record.", "Explore the relational pattern and what it is like to seek reassurance in the counseling relationship.", "Set a limit of one reassurance question per session to gently shape the behavior.", "Interpret the question as transference from an early critical relationship."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Patterns that emerge in session can be explored therapeutically while maintaining empathy and boundaries."}, {"id": "q159", "text": "Which intervention best reflects reflective listening?", "options": ["You want to protect your family, but you are exhausted from being the one everyone relies on.", "That sounds like such a heavy load for one person to have to carry.", "You are exhausted because you have never set any limits with them.", "So what you are saying is that your family relies on you for almost everything they need day to day."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Reflective listening captures content and emotion to deepen understanding and reduce defensiveness."}, {"id": "q160", "text": "A counselor uses too much self-disclosure. What is the primary risk?", "options": ["The disclosures may be shared outside and compromise the counselor's privacy.", "The focus may shift from the client's needs to the counselor's experience.", "Clients may idealize the counselor and begin suppressing disagreement.", "The relationship may drift toward friendship and resist professional structure."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Self-disclosure should be intentional, brief, clinically relevant, and focused on client benefit."}, {"id": "q161", "text": "A client in exposure therapy asks to leave as soon as anxiety rises. What is the therapeutic goal?", "options": ["Allow the client to leave whenever anxiety rises and repeat the same exposure step in later sessions until it finally feels easy.", "Pair each exposure with relaxation until the anxiety is fully suppressed.", "Help the client remain safely engaged long enough to learn anxiety can decrease or be tolerated without avoidance.", "Lower the hierarchy to a step where the anxiety never rises above mild levels."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Exposure works by reducing avoidance and building inhibitory learning or habituation through planned, tolerable contact."}, {"id": "q162", "text": "Which intervention is most consistent with relapse prevention?", "options": ["Strengthen intrinsic motivation so that cravings lose their behavioral pull.", "Build a strong sober support network as the single most protective factor.", "Contract for abstinence with clear consequences attached to any lapse.", "Identify triggers, warning signs, coping responses, supports, and a plan for lapses."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Relapse prevention prepares clients for high-risk situations, coping, support, and recovery after lapses."}, {"id": "q163", "text": "In couples counseling, what is a helpful intervention for escalating conflict?", "options": ["Slow the interaction, reflect each partner's experience, and establish ground rules for respectful dialogue.", "Meet with each partner separately until the strongest emotions have settled.", "Let the argument continue running briefly in session so that the couple's live conflict pattern can be directly assessed.", "Assign a structured communication workbook for practicing conflict at home."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Couples work often requires process management, emotional validation, boundaries, and pattern identification."}, {"id": "q164", "text": "Which intervention is most consistent with emotion-focused counseling?", "options": ["Support full venting of the emotions so they can be completely discharged.", "Identify the cognitive distortions that trigger each emotional episode.", "Track detailed emotional intensity ratings between sessions to measure the client's progress over the course of treatment.", "Help the client access, name, regulate, and transform emotional experience in the relationship context."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Emotion-focused approaches emphasize emotional awareness, regulation, attachment needs, and corrective emotional experience."}, {"id": "q165", "text": "A counselor says, 'What would be different tomorrow if a small part of the problem were improved?' Which approach is reflected?", "options": ["Reality therapy.", "Motivational interviewing.", "Solution-focused counseling.", "Cognitive behavioral therapy."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Solution-focused questions help clients imagine preferred outcomes and identify small observable changes."}, {"id": "q166", "text": "Which intervention is most appropriate when a client is dissociating in session?", "options": ["Continue the work in a softer voice so the narrative is not interrupted.", "Use grounding, orienting to the present, sensory cues, and a calm pace.", "Reflect the underlying affect so the feeling can be processed in the moment.", "Name the dissociation and interpret its protective function for the client."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Dissociation is addressed with grounding, present orientation, stabilization, and safety."}, {"id": "q167", "text": "Which statement best reflects accurate confrontation?", "options": ["Help me understand why you cancel every single invitation that you receive.", "I genuinely care about your goals, and that is exactly why I have to tell you that you are avoiding them.", "You keep telling me you want friends, but your actions say something else entirely.", "You say you want closer friendships, and I also notice you cancel whenever someone invites you out."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Confrontation in counseling highlights discrepancies respectfully and invites exploration rather than blame."}, {"id": "q168", "text": "Which intervention best matches Adlerian encouragement?", "options": ["Highlight strengths, effort, belonging, and movement toward useful goals.", "Praise the client's achievements consistently to build self-esteem.", "Interpret the client's early recollections to reveal lifestyle themes.", "Explore the client's inferiority feelings and their compensatory pattern."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Adlerian counseling emphasizes encouragement, social interest, belonging, goals, and lifestyle patterns."}, {"id": "q169", "text": "A client says, 'I cannot stand this anxiety.' Which ACT skill may be used?", "options": ["Progressive muscle relaxation practiced until the anxiety reaches a manageable level.", "Examining the evidence for and against the client's anxious predictions.", "Cognitive defusion and acceptance of internal experience while choosing valued action.", "Scheduling designated worry time to contain the anxiety to set periods."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "ACT helps clients relate differently to thoughts and feelings rather than requiring their elimination before action."}, {"id": "q170", "text": "Which technique pairs relaxation with gradual exposure to feared stimuli?", "options": ["Flooding.", "Systematic desensitization.", "Stress inoculation training.", "Exposure and response prevention."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Systematic desensitization combines relaxation training with a gradual fear hierarchy."}, {"id": "q171", "text": "A counselor provides homework to test a client's belief that asking for help will always lead to rejection. What CBT method is this?", "options": ["Graded task assignment.", "Socratic questioning.", "Activity scheduling.", "Behavioral experiment."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Behavioral experiments test predictions and generate new learning through planned action."}, {"id": "q172", "text": "What is the primary purpose of silence used skillfully in counseling?", "options": ["To encourage the client to fill the space with deeper disclosure.", "To give the client space to feel, reflect, and continue at their own pace.", "To let the counselor carefully formulate the next intervention.", "To signal that the material deserves serious weight before any response."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Therapeutic silence can deepen reflection when used intentionally and attuned to the client."}, {"id": "q173", "text": "Which intervention is most appropriate for a client with limited emotional vocabulary?", "options": ["Begin with cognitive work, since thoughts are more accessible than feelings.", "Note the limited vocabulary as alexithymia and adjust the goals accordingly.", "Use feeling lists, body cues, scaling, and reflections to build affect identification.", "Model emotional language by describing the counselor's own reactions in session."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Emotion identification can be built through psychoeducation, body awareness, language, reflection, and practice."}, {"id": "q174", "text": "A counselor notices a rupture after mispronouncing a client's name. What should the counselor do?", "options": ["Acknowledge the mistake, apologize, invite correction, and repair without defensiveness.", "Continue warmly and simply pronounce the name correctly from that point on.", "Explore what the client's strong reaction to the mistake might reveal.", "Lighten the moment with a bit of gentle humor so the mistake does not become a focus."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Rupture repair supports alliance, respect, cultural humility, and trust."}, {"id": "q175", "text": "Which intervention best supports a client with social anxiety practicing assertiveness?", "options": ["Assign readings on assertive communication before any in-session practice.", "Role-play a specific conversation and process thoughts, feelings, and skills afterward.", "Have the client observe assertive models before attempting the skill directly.", "Begin with imaginal rehearsal until the anticipatory anxiety fully extinguishes."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Role-play allows skills rehearsal, feedback, exposure, and confidence-building."}, {"id": "q176", "text": "In MI, what does rolling with resistance mean?", "options": ["Postponing all change discussions until the client raises them independently.", "Aligning with the client's view that change is not currently worth pursuing.", "Responding to sustain talk without arguing, while exploring autonomy and ambivalence.", "Redirecting the conversation toward strengths whenever sustain talk appears."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "MI avoids power struggles and supports autonomy while eliciting change talk."}, {"id": "q177", "text": "Which response best evokes change talk?", "options": ["What would be better in your life if this problem changed even a little?", "What do you think keeps this problem going from day to day?", "Would it help to hear what has worked for other people in this situation?", "How long has this pattern been a part of your everyday life?"], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Change talk is elicited through questions about desire, ability, reasons, need, commitment, and steps toward change."}, {"id": "q178", "text": "Which intervention best reflects attachment-informed counseling?", "options": ["Focus the treatment on independence so that relationships matter less.", "Classify the client's attachment style using a validated adult measure.", "Link each of the client's current symptoms back to the earliest caregiving relationship.", "Explore patterns of safety, closeness, threat, and emotion regulation in relationships."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Attachment-informed work considers internal working models, emotional safety, proximity, regulation, and relational patterns."}, {"id": "q179", "text": "A client asks, 'What should I do when anger rises in the moment?' Which skill is most practical?", "options": ["Express the anger fully as it arises so that it does not continue to build up.", "Analyze the childhood roots of the anger thoroughly before trying to respond to it in the moment.", "Pause, notice body cues, lower arousal, choose a values-consistent response, and repair if needed.", "Step away from every situation in which the anger might possibly arise."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Anger interventions often combine arousal regulation, awareness, cognitive appraisal, values, communication, and repair."}, {"id": "q180", "text": "Which intervention best matches grief meaning-making?", "options": ["Invite the client to explore the continuing significance of the loss and how life is reorganized around it.", "Support open emotional expression until the intensity of the grief subsides.", "Help the client say goodbye and withdraw emotional energy from the bond.", "Guide the client systematically through each of the recognized grief stages toward reaching final acceptance."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Meaning-making approaches explore identity, connection, memory, values, and reconstruction after loss."}, {"id": "q181", "text": "Which counselor action best supports termination?", "options": ["Space the final several sessions progressively farther apart and let the ending occur naturally.", "Frame the ending as a graduation and keep the final session celebratory.", "Keep the door open by scheduling standing monthly check-ins indefinitely.", "Review progress, consolidate skills, discuss feelings about ending, and plan future supports."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Termination includes review, consolidation, relapse prevention, referral if needed, and processing the ending."}, {"id": "q182", "text": "A client repeatedly intellectualizes painful experiences. Which intervention may help?", "options": ["Point out the defense directly so that the client can choose to set it down.", "Gently shift from analysis to present emotion, body sensation, and meaning at a tolerable pace.", "Assign expressive writing so the emotions can emerge outside of the session.", "Join the client's intellectual analysis fully until the client feels safe enough for affect."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Counselors can respect defenses while inviting fuller emotional processing within the client's window of tolerance."}, {"id": "q183", "text": "Which intervention best helps a client challenge mind reading?", "options": ["Reassure the client that people rarely think badly of others in daily life.", "Ask for evidence, alternative explanations, and a behavioral test of the prediction.", "Replace the thought with a positive prediction about the interaction.", "Trace back to when the client first began assuming others' judgments."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "CBT addresses mind reading by examining evidence, alternatives, probabilities, and experiments."}, {"id": "q184", "text": "A client needs help communicating a boundary. Which counselor intervention is most appropriate?", "options": ["Teach and rehearse clear, respectful, specific assertive language.", "Encourage an indirect approach first, such as hinting or gradually reduced contact.", "Role-play the other person's objections until the client feels no anxiety at all.", "Provide a written script for the client to send by text, avoiding a live conversation."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Assertiveness training includes clear expression, respectful tone, specificity, rehearsal, and attention to safety."}, {"id": "q185", "text": "Which counselor quality is most directly reflected by accurately sensing and communicating a client's emotional experience?", "options": ["Compassion.", "Genuineness.", "Empathy.", "Warmth."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Empathy involves understanding and communicating the client's experience in a way the client can recognize."}, {"id": "q186", "text": "A counselor notices irritation toward a client who reminds them of a family member. Which attribute is most important?", "options": ["Professional objectivity maintained through detachment.", "Emotional regulation throughout the session.", "Unconditional positive regard toward the client.", "Self-awareness and management of countertransference."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Counselors need self-awareness to recognize personal reactions and prevent them from harming the client."}, {"id": "q187", "text": "Which behavior best reflects cultural humility?", "options": ["Adapting every intervention to fit the client's cultural background.", "Ethnic and cultural matching of the counselor and client whenever matching is possible.", "Remaining open to learning from the client while examining one's own assumptions and power.", "Cultural competence built through formal training and continuing coursework."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Cultural humility includes openness, self-reflection, accountability, and attention to power and context."}, {"id": "q188", "text": "A client describes a choice the counselor strongly disagrees with. Which counselor attribute is most important?", "options": ["Respect for client autonomy and nonjudgmental stance.", "Beneficence expressed through active guidance toward better options.", "Genuineness in sharing the counselor's honest perspective on the choice.", "Professional neutrality that avoids discussing the choice at all."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Effective counselors respect client dignity and autonomy while addressing risk and consequences when needed."}, {"id": "q189", "text": "Which attribute helps a counselor remain grounded when sessions are emotionally intense?", "options": ["Empathic attunement.", "Emotional regulation.", "Cognitive detachment.", "Compartmentalization."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Counselor emotional regulation supports presence, attunement, judgment, and client safety."}, {"id": "q190", "text": "A counselor admits a misunderstanding and repairs it with the client. Which attribute is demonstrated?", "options": ["Transparency about the counseling process.", "Congruence between words and actions.", "Empathic responsiveness to correction.", "Humility and accountability."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Humility and accountability allow counselors to repair alliance ruptures and model respectful responsibility."}, {"id": "q191", "text": "Which counselor attribute is most related to being fully attentive in the session?", "options": ["Empathy.", "Patience.", "Genuineness.", "Presence."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Presence involves attentive, grounded, responsive engagement with the client's unfolding experience."}, {"id": "q192", "text": "A counselor continues learning after noticing gaps in competence. Which attribute is demonstrated?", "options": ["Professional reflectiveness and commitment to growth.", "Established clinical competence.", "Intellectual curiosity about clinical practice.", "Conscientious diligence in daily work."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Effective counselors reflect on limitations and pursue supervision, consultation, and continuing education."}, {"id": "q193", "text": "Which attribute is most important when working with ambiguous client material?", "options": ["Patience while waiting for clarity to emerge.", "Confidence in one's clinical intuition.", "Tolerance for ambiguity and curiosity.", "Analytical precision in organizing unclear material."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Counselors often hold complexity without rushing to simplistic conclusions."}, {"id": "q194", "text": "A counselor communicates hope without minimizing the client's pain. Which attribute is being shown?", "options": ["Compassionate reassurance about the road ahead.", "Balanced optimism and respect for suffering.", "Therapeutic optimism grounded in treatment outcome research.", "Warm encouragement focused on the client's strengths."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Hope is therapeutic when it honors reality and supports agency rather than minimizing distress."}, {"id": "q195", "text": "Which attribute protects clients from exploitation in the counseling relationship?", "options": ["Transparent informed consent at the outset.", "Appropriate professional boundaries.", "Consistent empathic attunement to client needs.", "Regular consultation on challenging cases."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Boundaries protect client welfare, role clarity, and the integrity of the counseling relationship."}, {"id": "q196", "text": "A counselor carefully considers how their identity may affect a client from a marginalized group. Which attribute is most relevant?", "options": ["Cultural empathy.", "Inclusivity.", "Reflexivity.", "Social advocacy."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Reflexivity involves examining one's social location, assumptions, power, and impact on the counseling relationship."}, {"id": "q197", "text": "Which attribute allows a counselor to stay compassionate while not taking responsibility for every client choice?", "options": ["Warm neutrality toward the client's decisions.", "Unconditional acceptance of every client outcome.", "Empathic detachment that preserves clinical objectivity.", "Differentiated compassion with clear professional limits."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Counselors can care deeply while maintaining limits, autonomy, and responsibility boundaries."}, {"id": "q198", "text": "A counselor receives critical feedback from a client and becomes curious rather than defensive. Which attribute is demonstrated?", "options": ["Openness to feedback.", "Professional composure in difficult moments.", "Nondefensive tolerance of client anger.", "Ego resilience under interpersonal stress."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Openness to feedback supports alliance repair, growth, and client-centered responsiveness."}, {"id": "q199", "text": "Which attribute is shown when a counselor consistently honors the client's dignity, even during relapse or setbacks?", "options": ["Hopefulness about eventual recovery.", "Patience with the pace of behavioral change.", "Respect and acceptance of the person.", "Empathy for the shame that accompanies relapse."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Core counseling attributes include respect, acceptance, and belief in the client's dignity even when behavior needs accountability."}, {"id": "q200", "text": "A counselor balances compassion for clients with regular rest, consultation, and realistic caseload limits. Which attribute is demonstrated?", "options": ["Resilience developed through experience with difficult cases.", "Sustainable self-care and professional responsibility.", "Work-life balance maintained through strict separation of roles.", "Compassion satisfaction that offsets the demands of the work."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Sustainable self-care protects counselor functioning and client welfare."}, {"id": "q201", "text": "A counselor in private practice wants to use a sliding fee scale. Which practice is most ethically sound?", "options": ["Establish a clear, consistent fee policy, discuss it during informed consent, and document agreements with clients.", "Adjust the fee informally from session to session as the client's finances shift.", "Apply the sliding scale generously to self-pay clients while continuing to bill insurers at the full standard contracted rate.", "Offer the reduced rate only after clients disclose their financial hardship in detail."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Ethical fee practices require transparency, consistency, and informed consent regarding costs, billing, and any sliding-scale arrangements."}, {"id": "q202", "text": "A client who is no longer in treatment texts a counselor late at night seeking crisis support. The counselor's best first step is to:", "options": ["Resume supportive contact by text until the client appears to have stabilized.", "Reply the next morning during business hours with a list of available referral options.", "Forward the client directly to emergency services and end the late-night exchange without any further assessment, since the treatment relationship and its duties formally concluded at termination.", "Clarify the limits of availability, assess urgency, and direct the client to appropriate crisis resources or re-engagement procedures."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Even after termination, counselors should respond appropriately to crisis contact, clarify boundaries, and facilitate access to suitable care rather than abandoning a client in danger."}, {"id": "q203", "text": "Which situation most clearly requires a counselor to obtain a release of information before communicating with a third party?", "options": ["Discussing a competent adult client's progress with their employer for workplace planning.", "Consulting about the case with a clinical supervisor without disclosing identifying client details.", "Warning an identifiable victim of a client's serious and imminent threat.", "Reporting suspected child abuse to the state agency as mandated by law."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Voluntary disclosures to third parties such as employers generally require client authorization, whereas mandated reporting and certain duty-to-protect situations are legal exceptions."}, {"id": "q204", "text": "A counselor wants to barter counseling services for a client's home-repair work. What is the most ethical approach?", "options": ["Decline all bartering arrangements, since nonmonetary payment is prohibited outright.", "Accept the barter if the client proposes it and the terms of the trade favor the client.", "Consider cultural context, potential for exploitation or dual relationships, and agency policy; barter only when it is fair, documented, and not clinically contraindicated.", "Formalize the barter in a written and signed contract that values the exchange at the counselor's usual hourly rate, since fair documentation of equivalent value is what makes a bartering arrangement ethically permissible."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Bartering can create dual relationships and exploitation risks. Ethical practice evaluates fairness, cultural norms, clinical impact, documentation, and policy before proceeding."}, {"id": "q205", "text": "Which statement best reflects ethical practice when counseling minors?", "options": ["Extend adult confidentiality standards to the minor in order to build early trust.", "Obtain the minor's full consent and treat parental involvement as clinically optional.", "Give guardians complete and unrestricted access to session content in every case, since the parent or guardian who holds consent is the legal owner of the minor's treatment record.", "Counselors clarify assent, parental consent, confidentiality limits, and applicable laws with the minor and guardians as appropriate."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Work with minors requires attention to consent/assent, developmental capacity, parental rights, confidentiality limits, and state-specific legal requirements."}, {"id": "q206", "text": "A counselor discovers that a colleague is practicing while impaired by substance use and posing a risk to clients. What is the most appropriate ethical action?", "options": ["Report anonymously to the licensing board without documentation or prior consultation.", "Address the concern through appropriate channels such as consultation, reporting to supervisors or licensing boards, and protecting client welfare.", "Notify the colleague's current clients directly about the observed impairment so that each of them can make a fully informed decision about whether to continue in that counselor's care.", "Speak privately with the colleague first and monitor whether the impairment continues."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Counselors have an ethical obligation to protect clients when a colleague's impairment or unethical conduct creates risk, using proper professional channels."}, {"id": "q207", "text": "When providing distance counseling via video, which practice is most consistent with ethical standards?", "options": ["Obtain a signed telehealth consent form, which itself satisfies the ethical requirements.", "Verify identity and location as appropriate, discuss technology risks and emergency procedures, and ensure competence with the modality.", "Apply the same clinical procedures as in-person work so the standard of care stays equal.", "Restrict telehealth services to well-established, long-term clients so that formal identity verification and location procedures become unnecessary at the start of each session."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Telehealth ethics include technology competence, privacy and security considerations, emergency planning, identity/location verification, and modality-specific informed consent."}, {"id": "q208", "text": "A counselor is asked to provide a character reference for a current client in a custody dispute. What is the best ethical response?", "options": ["Write the reference after adding a disclaimer that the counselor is not a forensic evaluator.", "Agree to testify as a fact witness about the treatment and offer a custody opinion only in the event that the judge asks the counselor for one directly from the stand.", "Provide the reference but confine it to the positive observations documented in the record.", "Avoid dual roles that blur treatment and forensic functions; limit statements to what is appropriate and supported by the counseling role."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Mixing therapeutic and forensic roles can harm clients and compromise objectivity. Counselors should avoid dual roles and provide only role-appropriate, accurate information."}, {"id": "q209", "text": "Which action best demonstrates ethical multicultural competence?", "options": ["Applying published, research-based norms and values for the client's specific cultural group to guide case conceptualization and each treatment decision.", "Inviting the client to educate the counselor about the relevant cultural factors.", "Engaging in ongoing self-awareness, knowledge, and skill development regarding diverse worldviews and adapting practice accordingly.", "Completing a certificate program in multicultural counseling to establish competence."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Multicultural competence is an ethical responsibility involving continuous self-reflection, cultural knowledge, and culturally responsive counseling skills."}, {"id": "q210", "text": "A standardized test has a reliability coefficient of .92. What does this primarily indicate?", "options": ["Scores are relatively consistent or stable across replications under similar conditions.", "Scores can be interpreted without regard to the standard error of measurement.", "The test correctly predicts relevant clinical outcomes ninety-two percent of the time.", "The instrument accurately measures the construct it was designed to assess."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Reliability refers to consistency or stability of measurement; validity concerns whether the instrument measures the intended construct."}, {"id": "q211", "text": "Which statement best distinguishes criterion-related validity from content validity?", "options": ["Criterion-related validity is established after a test is published; content validity must be established during development only.", "Criterion-related validity applies to aptitude and ability tests; content validity applies only to personality measures.", "Criterion-related validity concerns prediction of or correlation with an external criterion; content validity concerns adequate sampling of the domain of interest.", "Criterion-related validity rests primarily on expert judgment of the individual items; content validity rests on statistical correlation with relevant external outcomes."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Content validity addresses domain coverage; criterion-related validity evaluates relationships with external outcomes or criteria (concurrent or predictive)."}, {"id": "q212", "text": "A client's raw score converts to a percentile rank of 84. Which interpretation is most accurate?", "options": ["The client's raw score falls at the 84th point on the instrument's scale.", "Sixteen percent of the norm group scored above the client, with 84% at the same score.", "The client answered approximately 84% of the test items correctly.", "The client scored higher than approximately 84% of the norm group."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "A percentile rank indicates the percentage of the norm group that scored at or below the client's score, not the percentage of items correct."}, {"id": "q213", "text": "During intake, a client reports passive thoughts of death without plan, intent, or means. What is the counselor's best immediate action?", "options": ["Conduct a thorough suicide risk assessment, develop a collaborative safety plan as indicated, and document the assessment and plan.", "Pause the intake and refer the client for a psychiatric evaluation before continuing.", "Administer a standardized suicide screen and proceed with intake if the score is low.", "Document the passive ideation carefully in the intake record, provide crisis line information, and plan to reassess the client's thoughts of death at the next scheduled session."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Any suicidal ideation warrants structured risk assessment of ideation, plan, intent, means, protective factors, and appropriate safety planning and documentation."}, {"id": "q214", "text": "Which information is most essential when making a differential diagnosis between major depressive disorder and bipolar disorder?", "options": ["The client's response to antidepressants prescribed in previous episodes.", "A careful history of manic or hypomanic episodes, including elevated mood, increased energy, and related impairment or risk.", "A detailed family history of depressive and bipolar mood disorders among the client's first-degree biological relatives across generations.", "The severity and duration of the client's current depressive episode."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Differentiating unipolar depression from bipolar spectrum disorders requires assessment of past or present mania/hypomania and related symptoms and course."}, {"id": "q215", "text": "A counselor uses an assessment instrument that was normed only on a population demographically unlike the client. What is the primary concern?", "options": ["The instrument may be used only qualitatively, with all standardized scores discarded.", "Interpretation may be biased or invalid if norms and cultural context do not fit the client.", "The reliability coefficients reported in the manual will not generalize to the client.", "The client's responses cannot be scored until representative local norms are collected."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Assessment interpretation must consider norm group appropriateness, cultural context, language, and potential bias to avoid invalid conclusions."}, {"id": "q216", "text": "Which intake question best screens for intimate partner violence safety concerns?", "options": ["Do you feel that your partner genuinely supports you emotionally day to day?", "Has stress in the relationship been affecting your sleep, mood, or concentration?", "Are you ever afraid of your partner, or has your partner threatened, controlled, or physically hurt you?", "How do you and your partner usually go about handling disagreements when they come up at home together?"], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "IPV screening should be direct, private, and behavior-specific, addressing fear, control, threats, and physical harm while prioritizing safety."}, {"id": "q217", "text": "What is the main purpose of using standardized intake procedures across clients in an agency?", "options": ["To ensure consistent collection of essential clinical, risk, and demographic information while supporting ethical and legal documentation.", "To ensure that every client entering the agency receives a fully equivalent diagnostic workup regardless of the nature or severity of the presenting concern.", "To generate comparable outcome data for the agency's program evaluation efforts.", "To reduce the influence of individual clinician style on the intake relationship."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Standardized intake supports completeness, consistency, risk screening, and documentation while still allowing individualized clinical judgment."}, {"id": "q218", "text": "A client scores in the clinical range on a depression inventory but denies impairment. What should the counselor do next?", "options": ["Readminister the inventory in two weeks to rule out a transient score elevation.", "Weight the standardized inventory score above the client's verbal self-report, since validated instruments are specifically designed to reduce reporter bias and denial.", "Accept the client's account, since functional impairment is required for the diagnosis.", "Integrate the score with clinical interview, history, functioning, cultural context, and collateral data as appropriate before concluding."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Assessment results are one data source; diagnosis and clinical conclusions require multimethod integration rather than sole reliance on a single score."}, {"id": "q219", "text": "Which treatment goal is written in the most measurable and useful form?", "options": ["Client will develop and consistently apply healthier coping strategies for managing panic symptoms during treatment.", "Client will reduce panic attacks from daily to no more than two per week within 8 weeks, tracked by a symptom log.", "Client will gain insight into the situations and thoughts that trigger the panic attacks.", "Client will report a meaningful reduction in panic frequency by the end of treatment."], "correct": 1, "domain": "Treatment Planning", "explanation": "Effective goals are specific, measurable, achievable, relevant, and time-bound, enabling progress monitoring and collaborative revision."}, {"id": "q220", "text": "A client wants to stop using alcohol but is ambivalent. Which planning approach is most appropriate initially?", "options": ["Collaborate on goals matched to the client's stage of change, using motivational strategies while monitoring safety.", "Set moderation goals from the outset, since abstinence goals deter ambivalent clients.", "Start the treatment with a required two-week abstinence trial period before collaboratively setting any other goals.", "Focus the early plan on the underlying causes of drinking before addressing use itself."], "correct": 0, "domain": "Treatment Planning", "explanation": "Treatment planning should be collaborative and stage-of-change sensitive, especially when ambivalence is present, while still addressing risk."}, {"id": "q221", "text": "What is the primary purpose of including objectives under a treatment goal?", "options": ["To translate the clinical diagnosis into the billable service categories required by the payer.", "To document the client's informed agreement with the overall planned direction of the treatment.", "To break goals into concrete, stepwise actions or skill targets that guide sessions and evaluate progress.", "To specify the theoretical orientation guiding each of the planned interventions."], "correct": 2, "domain": "Treatment Planning", "explanation": "Objectives operationalize goals into actionable steps or skill targets that structure interventions and allow progress evaluation."}, {"id": "q222", "text": "When should a treatment plan be reviewed and updated?", "options": ["After any session in which meaningful new clinical material has emerged.", "Whenever the client's current insurance authorization period comes to an end.", "At the point of termination, so that the full course of the treatment can be evaluated at one time.", "At regular intervals and when there are significant changes in symptoms, goals, risk, or circumstances."], "correct": 3, "domain": "Treatment Planning", "explanation": "Treatment plans are living documents that should be revisited as clients progress, goals change, or clinical status shifts."}, {"id": "q223", "text": "A client presents with severe depression and active suicidal planning. Which planning priority is most appropriate?", "options": ["Immediate behavioral activation scheduling, since increased activity reduces suicidal thinking.", "Treatment of the depressive symptoms first, since resolving them removes the risk.", "Stabilization and safety planning, including appropriate level of care, before less urgent goals.", "Weekly outpatient CBT with the suicide risk monitored from session to session."], "correct": 2, "domain": "Treatment Planning", "explanation": "Safety and stabilization take precedence over lower-priority goals when acute risk is present; level-of-care decisions follow risk severity."}, {"id": "q224", "text": "Which element most strengthens collaborative treatment planning?", "options": ["Selecting the interventions with the strongest research support for the diagnosis.", "Aligning each of the goals tightly with the specific diagnostic criteria that justify the medical necessity of treatment.", "Reviewing the completed plan with the client and obtaining a documented signature.", "Incorporating the client's values, cultural context, strengths, and preferred outcomes into goals and interventions."], "correct": 3, "domain": "Treatment Planning", "explanation": "Collaborative planning centers client goals, values, culture, and strengths, which improves engagement, relevance, and outcomes."}, {"id": "q225", "text": "A treatment plan lists 'use CBT' as the only intervention for social anxiety. What is missing for a stronger plan?", "options": ["A relapse prevention component designed to protect the eventual treatment gains.", "Specific interventions (e.g., psychoeducation, cognitive restructuring, exposure hierarchy), frequency, and measurable targets.", "A written theoretical rationale connecting the cognitive behavioral model to the specific features of the client's social anxiety diagnosis.", "Documentation of the client's informed consent to a cognitive behavioral approach."], "correct": 1, "domain": "Treatment Planning", "explanation": "Strong plans specify interventions, not only orientations, and link them to measurable goals, session structure, and progress indicators."}, {"id": "q226", "text": "Which factor is most important when selecting an evidence-based intervention for a client?", "options": ["Research support, client characteristics and preferences, cultural context, counselor competence, and presenting problem match.", "The client's stated preference among the available treatment options alone.", "The strength and quantity of the randomized controlled trial evidence supporting the intervention for the diagnosis, considered alone.", "The counselor's demonstrated competence and comfort with the chosen approach alone."], "correct": 0, "domain": "Treatment Planning", "explanation": "Evidence-based practice integrates best available research with clinical expertise and client culture, preferences, and context."}, {"id": "q227", "text": "In case management within a treatment plan, what is the counselor's main role?", "options": ["Personally delivering the full range of needed wraparound services directly to the client so that the overall care is never fragmented.", "Managing communications among all of the providers without requiring releases.", "Monitoring the client's weekly follow-through with every provider on the care team.", "Coordinating and linking clients to needed resources while maintaining appropriate boundaries and releases of information."], "correct": 3, "domain": "Treatment Planning", "explanation": "Case management coordinates access to services and supports continuity of care without replacing other systems or violating boundaries."}, {"id": "q228", "text": "A client says, 'I feel stuck and hopeless about ever changing.' Which response best demonstrates accurate empathy?", "options": ["Most people feel stuck at some point; it usually passes with a little time.", "What do you think is keeping you from believing that change is possible?", "It sounds like change feels out of reach right now and that weight is heavy.", "I can hear that you have been trying very hard for a very long time now."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Empathic responses reflect the client's emotional experience and meaning without prematurely advising, disputing, or redirecting."}, {"id": "q229", "text": "Which technique is most characteristic of motivational interviewing?", "options": ["Teaching cognitive and behavioral skills for managing high-risk situations.", "Evoking the client's own reasons for change and rolling with resistance rather than arguing.", "Reinforcing abstinence through a structured schedule of contingency rewards.", "Building discrepancy by presenting objective assessment feedback about consequences."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "MI emphasizes partnership, acceptance, compassion, and evocation—drawing out client motivation and avoiding unproductive confrontation."}, {"id": "q230", "text": "In cognitive therapy, what is the primary target of cognitive restructuring?", "options": ["Unexamined automatic thoughts, intermediate beliefs, and core beliefs that maintain distress.", "The physiological arousal that accompanies exposure to distressing situations.", "The unconscious internal conflicts that find expression through the presenting symptoms.", "The environmental reinforcers that maintain the client's avoidance behavior."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "CBT cognitive work identifies and evaluates automatic thoughts and underlying beliefs that contribute to emotional and behavioral problems."}, {"id": "q231", "text": "A counselor uses an empty-chair dialogue to help a client express unfinished feelings toward a parent. This technique is most associated with which approach?", "options": ["Gestalt therapy.", "Psychodrama.", "Transactional analysis.", "Object relations therapy."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Empty-chair and other experiential experiments are hallmark Gestalt methods for working with unfinished business and present-centered awareness."}, {"id": "q232", "text": "Which statement best describes active listening in counseling?", "options": ["Observing the client's nonverbal behavior closely while minimizing verbal responses.", "Attending fully and using skills such as paraphrase, reflection, clarifying questions, and summarization to convey understanding.", "Restating the client's own words nearly verbatim after each statement in order to confirm the moment-to-moment accuracy of the counselor's listening.", "Allowing the client to speak without interruption until they have completely finished."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Active listening combines attending behavior with verbal skills that check and communicate understanding of content and affect."}, {"id": "q233", "text": "During the working stage of a counseling group, members confront one another and give feedback. What is the leader's most appropriate function?", "options": ["Screen the feedback so that only clearly supportive comments reach the members.", "Step back from the process fully, since groups that reach the working stage function best without active leader involvement.", "Facilitate safe, constructive feedback, maintain norms, and help members process interpersonal learning.", "Redirect the confrontations into individual sessions to protect group cohesion."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "In the working stage, leaders support cohesion, norms, and therapeutic factors while facilitating productive interpersonal work and safety."}, {"id": "q234", "text": "A client catastrophizes about a job interview. Which intervention is most consistent with REBT?", "options": ["Reflect the interview anxiety empathically and patiently until the catastrophic thinking begins to soften on its own.", "Teach mindful acceptance of the anxious thoughts without evaluating their content.", "Set up a behavioral experiment to directly test the feared interview outcome.", "Identify and vigorously dispute irrational beliefs, then replace them with more rational, flexible beliefs."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "REBT targets irrational beliefs through disputation and development of rational, preferential (rather than absolute) beliefs."}, {"id": "q235", "text": "Which counseling skill is most useful when a client gives vague, global statements about their problem?", "options": ["Offering a tentative interpretation to help organize the diffuse material.", "Concrete, open questions and requests for specific examples to increase clarity.", "Reflecting the feelings that seem to sit underneath the global statements.", "Summarizing the themes across everything the client has shared so far."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Concreteness helps clients move from vague descriptions to specific situations, feelings, and behaviors that can be assessed and treated."}, {"id": "q236", "text": "A solution-focused counselor asks, 'If a miracle happened overnight and your problem was solved, what would be different tomorrow?' This is primarily used to:", "options": ["Assess the client's readiness for change by gauging the vividness of the response.", "Externalize the problem so the client can relate to it in a different way.", "Elicit preferred future details and identify signs of progress and goals.", "Interrupt rumination by shifting the client's attention away from the problem."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "The miracle question helps clients articulate a preferred future, which guides goal setting and identification of small solvable steps."}, {"id": "q237", "text": "According to Super's life-span, life-space theory, career development is best understood as:", "options": ["A progression driven by the circumscription and elimination of unacceptable options.", "A product primarily of social learning experiences and planned or chance events.", "A process of matching stable traits to job factors at a single decision point.", "A lifelong process involving self-concept development and multiple life roles across stages."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Super emphasized career as a lifelong developmental process shaped by evolving self-concept and roles across the life span."}, {"id": "q238", "text": "Holland's RIASEC model is primarily used to:", "options": ["Match personality/interest types with congruent work environments.", "Assess the maturity of a client's career decision-making readiness.", "Identify the developmental stage of a client's vocational self-concept.", "Measure discrepancies between work values and workplace rewards."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Holland's typology links six personality/interest types to corresponding occupational environments to support career fit and exploration."}, {"id": "q239", "text": "A client in early recovery from opioid use reports intense craving after seeing old using friends. Which clinical response is most appropriate?", "options": ["Increase the level of care, since strong craving signals an imminent relapse.", "Advise the client to permanently avoid all former using friends as the primary protective strategy in recovery.", "Explore the craving as unresolved ambivalence about recovery before anything else.", "Normalize craving as common, assess relapse risk, strengthen coping and support, and review the recovery plan."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Craving is common in recovery; counselors assess risk, reinforce coping skills, support networks, and recovery planning without moralizing."}, {"id": "q240", "text": "Which statement best reflects a trauma-informed counseling stance?", "options": ["Prioritize safety, trustworthiness, choice, collaboration, and empowerment while recognizing the impact of trauma.", "Minimize any direct discussion of the traumatic material in order to avoid retraumatizing the client during sessions.", "Process the trauma memories early so that the symptoms do not consolidate further.", "Screen every client for PTSD and refer all positive screens to trauma specialists."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Trauma-informed care emphasizes safety, trust, collaboration, empowerment, and cultural sensitivity rather than coercive or invalidating practices."}, {"id": "q241", "text": "A couple reports repeated pursuer–distancer cycles during conflict. Which systems-informed focus is most relevant?", "options": ["Assessing each partner separately for individual diagnoses that explain the pattern.", "Exploring interactional patterns, circular causality, and each partner's role in the cycle.", "Coaching the pursuing partner to reduce demands so that the cycle stops.", "Identifying which partner's attachment injuries originally initiated the cycle."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Systems perspectives examine reciprocal patterns and circular processes rather than linear blame of a single identified patient."}, {"id": "q242", "text": "Erikson's stage of identity versus role confusion is most associated with which developmental period?", "options": ["School age.", "Young adulthood.", "Adolescence.", "Early childhood."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Erikson linked identity versus role confusion primarily to adolescence, when consolidating a coherent sense of self is central."}, {"id": "q243", "text": "A client from a collectivist cultural background prioritizes family harmony over individual preferences in career choice. A culturally responsive counselor would most likely:", "options": ["Help the client carefully separate their authentic personal career preferences from the expectations imposed by the family, so an independent choice becomes possible.", "Explore the client's values, family context, and bicultural pressures without imposing individualistic career norms as the only healthy option.", "Use a values card sort to show the client precisely where family and self diverge.", "Support the family's preferred direction, since harmony is the client's own stated value."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Culturally responsive practice respects diverse value systems, including collectivist priorities, while helping clients navigate conflicts and goals."}, {"id": "q244", "text": "Which feature is most characteristic of grief that may need clinical attention beyond typical bereavement support?", "options": ["Waves of sadness triggered by anniversaries and reminders through the first year.", "Continued daily thoughts about the deceased six months after the loss occurred.", "Noticeable difficulty enjoying previously meaningful activities and social connections during the first several weeks following the death, accompanied by frequent tearfulness.", "Persistent functional impairment, intense yearning or preoccupation, or complicated grief features lasting well beyond culturally expected timelines."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "While grief is normal, prolonged severe impairment, complicated grief features, or safety concerns may warrant more intensive clinical intervention."}, {"id": "q245", "text": "A school-age child is referred for inattention, hyperactivity, and academic decline. What should a counselor prioritize in clinical focus?", "options": ["Standardized teacher rating scales gathered from the school and treated as the definitive basis for establishing the diagnosis, since educators observe the child across the most structured demands of the day.", "Referral for a medication evaluation as the first step, given the academic decline.", "Comprehensive assessment across settings, ruling out trauma, sleep, learning, medical, and environmental contributors, and coordinating with caregivers/school as appropriate.", "A structured trial of behavioral parent training before any assessment is completed."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Child attention concerns require multi-setting assessment and differential consideration of medical, learning, trauma, and environmental factors."}, {"id": "q246", "text": "A counselor notices irritation toward a client who reminds them of a family member. Which attribute is most needed next?", "options": ["Self-awareness and use of supervision/consultation to manage countertransference.", "Deliberately increased empathy to counterbalance the irritation in session.", "Congruence expressed by transparently sharing the reaction with the client.", "Reassignment of the client to another counselor as a protective measure."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Self-awareness and appropriate use of supervision help counselors manage countertransference so personal reactions do not harm the client."}, {"id": "q247", "text": "Which counselor quality is most closely associated with Rogers' necessary and sufficient conditions?", "options": ["Empathy, self-disclosure, and egalitarianism.", "Unconditional positive regard, empathy, and congruence.", "Acceptance, insight, and accurate interpretation.", "Warmth, positive reinforcement, and rapport."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Person-centered theory emphasizes congruence (genuineness), unconditional positive regard, and empathic understanding as core facilitative conditions."}, {"id": "q248", "text": "A counselor admits a mistake about a scheduling error and repairs the rupture. Which attribute is demonstrated?", "options": ["Humility, accountability, and commitment to the alliance.", "Consistency between professional values and daily conduct.", "Responsiveness to client feedback about practice logistics.", "Transparency and appropriate professional self-disclosure."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Acknowledging errors and repairing ruptures reflects professionalism, humility, and investment in a trustworthy therapeutic relationship."}, {"id": "q249", "text": "Which behavior best reflects professional humility?", "options": ["Maintaining an up-to-date generalist competence across each of the major clinical practice areas throughout one's career.", "Presenting credentials and training accurately in all public statements.", "Recognizing limits of knowledge, seeking consultation, and remaining open to learning from clients and colleagues.", "Deferring to clients as the final experts on their own lived experience."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Humility includes knowing one's limits, valuing consultation and learning, and remaining open rather than assuming omniscience."}, {"id": "q250", "text": "A counselor sits with a client's intense grief without rushing to fix it. Which attribute is most evident?", "options": ["Nondirective patience while the client leads the session.", "Unconditional positive regard for the client's grieving style.", "Clinical objectivity that keeps the counselor's emotions contained.", "Emotional presence and capacity to tolerate client affect."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Therapeutic presence includes staying emotionally available with painful affect rather than prematurely shutting it down with advice or distraction."}, {"id": "q251", "text": "Which attribute most supports ethical boundary maintenance?", "options": ["Empathic attunement that senses when clients need more of the counselor.", "Warmth toward clients balanced with a consistently formal professional demeanor maintained across every session and interaction.", "Clarity about professional role, self-awareness of pulls to overstep, and consistent limit-setting for client welfare.", "Strong working knowledge of the ethics code's boundary provisions."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Healthy boundaries require role clarity, self-awareness, and consistent limits that protect the counseling relationship and client welfare."}, {"id": "q252", "text": "A counselor regularly examines how privilege and bias may affect clinical judgment. This primarily reflects:", "options": ["Cultural humility and reflective practice.", "Ethical bracketing of personal values during clinical work.", "Social justice advocacy on behalf of marginalized clients.", "Multicultural knowledge acquired through ongoing training."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Cultural humility involves ongoing self-examination of bias, power, and privilege and their influence on the counseling relationship."}, {"id": "q253", "text": "Which quality best describes genuineness (congruence) in counseling?", "options": ["Professional transparency with clients about the counselor's methods, credentials, and the ongoing progress of treatment.", "Alignment between the counselor's internal experience and professional communication in a helpful, boundaried way.", "Consistent warmth and positive regard toward the client in every session.", "Judicious self-disclosure used at moments when it benefits the client's work."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Genuineness is authentic, congruent presence that remains professionally appropriate rather than unfiltered self-disclosure or total blankness."}, {"id": "q254", "text": "A counselor continues learning after licensure through consultation groups and training. Which attribute is demonstrated?", "options": ["Professional connectedness within the counseling community.", "Intellectual curiosity about emerging clinical research.", "Openness to feedback from colleagues and supervisors.", "Commitment to professional growth and competence."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Ongoing learning, consultation, and skill development reflect a professional commitment to competence and client welfare beyond initial licensure."}, {"id": "q255", "text": "A counselor begins a romantic relationship with a former client three weeks after termination. Which ethical principle is most clearly violated?", "options": ["Avoiding harmful dual/sexual relationships and protecting former clients from exploitation.", "Informed consent, because the risks of the new relationship were never documented.", "Nonmaleficence alone, and only if actual harm to the former client can be shown.", "Fidelity, because the counselor's loyalty shifted from professional to personal."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Sexual or romantic relationships with current clients are prohibited, and relationships with former clients require careful consideration of exploitation risk and applicable ethical standards and waiting periods."}, {"id": "q256", "text": "Which practice best protects client confidentiality in an open office suite?", "options": ["De-identifying charts by using client initials on all paperwork left in view.", "Using soundproofing or white noise, private spaces for sessions, and secure storage of records.", "Obtaining a blanket consent at intake that covers incidental office disclosures.", "Discussing active cases only with suite colleagues who are themselves also bound by confidentiality."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Confidentiality includes physical and electronic safeguards: private session spaces, protected conversations, and secure record handling."}, {"id": "q257", "text": "A client posts a negative online review naming the counselor. What is the most ethical response?", "options": ["Ask the platform to remove the review, citing the client's breach of the counseling agreement.", "Reply publicly without any clinical details, simply noting for readers that the review's description of the services provided is inaccurate.", "Post a general public response thanking the reviewer and inviting offline resolution.", "Avoid confirming the person was a client and address reputation through appropriate professional channels without disclosing PHI."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Public responses can confirm a counseling relationship and breach confidentiality. Counselors should not disclose protected information when managing online reviews."}, {"id": "q258", "text": "When is it generally ethical for a counselor to break confidentiality without client consent?", "options": ["When the client's employer is paying for the treatment under an EAP arrangement.", "When a concerned spouse presents legal proof of the marriage and formally requests a general update on the course of the client's treatment.", "When legally mandated or when there is serious, foreseeable, imminent risk requiring protective action, consistent with law and ethics.", "When a former treatment provider requests the records for continuity of care."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Confidentiality exceptions typically include mandated reporting, duty to protect, and other legally required disclosures; voluntary gossip or convenience is not an exception."}, {"id": "q259", "text": "A counselor receives a large cash gift from a current client mid-treatment. What should the counselor do first?", "options": ["Accept the gift and document it thoroughly in the record to preserve transparency.", "Accept and donate the gift to a charity so that neither party benefits from it.", "Explore meaning, cultural context, clinical impact, and policy; generally decline gifts that may impair objectivity or create exploitation concerns.", "Decline the gift firmly on the spot and document the refusal, since accepting anything of meaningful monetary value from a current client is prohibited."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Gift decisions require clinical and cultural judgment. Large or mid-treatment gifts often raise boundary and exploitation concerns and should be carefully evaluated, usually declined, and documented."}, {"id": "q260", "text": "Which statement best describes counselor competence?", "options": ["Competence is maintained through education, training, supervised experience, consultation, and practice within scope.", "Competence is demonstrated primarily through the counselor's accumulated years of direct clinical experience in the field.", "Competence is established at licensure and maintained through required CEU hours.", "Competence is defined by the scope of practice listed on the counselor's license."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Ethical competence requires appropriate preparation and ongoing development, and practice within the boundaries of one's training and ability."}, {"id": "q261", "text": "A supervisee asks a supervisor to co-sign notes for sessions the supervisor did not review. The ethical supervisor should:", "options": ["Co-sign this single time while scheduling proper reviews going forward to protect billing continuity.", "Delegate the note review to a senior supervisee to distribute the workload.", "Co-sign after receiving a verbal summary from the supervisee about each session.", "Only document and co-sign work that was actually supervised/reviewed according to standards and law."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Supervisors are responsible for accurate documentation and should not misrepresent the nature or extent of supervision provided."}, {"id": "q262", "text": "Which action is most consistent with ethical termination?", "options": ["Extending sessions at a gradually reduced frequency indefinitely so that professional support remains available whenever the client might want it.", "Planning termination collaboratively when goals are met or services are no longer appropriate, with referrals and adequate notice when possible.", "Transferring the client whenever progress has stalled for more than a month.", "Ending treatment when the authorized sessions are exhausted, with documentation."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Ethical termination is planned when possible, avoids abandonment, addresses unfinished business, and provides referrals or continuity of care as needed."}, {"id": "q263", "text": "A counselor wants to use client stories in a public workshop. What is required?", "options": ["Advance written approval obtained from the workshop host organization's own professional standards and ethics review committee before the presentation.", "Adequate disguise of identity or valid authorization, and attention to whether disclosure could still harm the client.", "Brief anonymization by omitting names and locations from each of the stories.", "Verbal permission from each client, noted in the counselor's own records."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Case material used for teaching or writing must protect identity through thorough disguise or authorization, with ongoing attention to residual risk of recognition and harm."}, {"id": "q264", "text": "Which billing practice is unethical?", "options": ["Keeping a card on file and charging copays automatically with the client's authorization.", "Billing different rates for individual and family sessions per the published fee schedule.", "Upcoding sessions or billing for missed sessions as if they occurred without a disclosed policy.", "Charging for a missed session under a fee policy disclosed and agreed to at intake."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Fraudulent or deceptive billing, including representing services that did not occur or miscoding, violates ethical and legal standards."}, {"id": "q265", "text": "A client requests that the counselor withhold a serious suicide plan from the treatment team. The counselor should:", "options": ["Honor the request within the treatment team while documenting the plan in the chart.", "Keep the confidence on a temporary basis while actively working in sessions to obtain the client's voluntary consent to share the plan.", "Negotiate a compromise in which the client discloses to one trusted team member.", "Explain limits of confidentiality related to safety and take appropriate protective action consistent with ethics, law, and agency policy."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Safety overrides a client's request for secrecy about imminent serious risk; counselors must act protectively while remaining transparent about limits of confidentiality."}, {"id": "q266", "text": "What is the best rationale for informed consent being an ongoing process?", "options": ["Treatment goals, risks, roles, and circumstances can change, so clients need updated information to make autonomous decisions.", "Signed consent forms legally expire after a fixed period of time under the licensing laws and regulations of most states.", "Clients rarely retain the details that were reviewed during the first session.", "Periodic re-consent protects the counselor against future liability claims."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Informed consent is continuous because the counseling relationship and relevant information evolve over time."}, {"id": "q267", "text": "A counselor is subpoenaed to testify and has not received a release or court order compelling disclosure. What is the best initial stance?", "options": ["Provide a written treatment summary in place of testimony to satisfy the subpoena.", "File a written objection directly with the court on the client's behalf and withhold all requested records until the scheduled trial date.", "Comply fully with the subpoena, since it is a court document that overrides privilege.", "Assert privilege/confidentiality as appropriate, seek legal consultation, and disclose only what is authorized or legally required."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Counselors protect confidentiality to the extent allowed by law, consult legally, and release only authorized or court-compelled information."}, {"id": "q268", "text": "Which dual relationship is generally most problematic?", "options": ["Counseling a current employee whom the counselor supervises at work.", "Belonging to the same large congregation as a client's extended family.", "Purchasing coffee regularly at a shop where a former client works the counter.", "Attending a client's public graduation ceremony at the client's invitation."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Concurrent hierarchical relationships (e.g., supervisor-employee plus counselor-client) create high risk of exploitation, impaired judgment, and role conflict."}, {"id": "q269", "text": "Ethical use of technology for client records most clearly requires:", "options": ["Keeping all client records stored offline on a single local office computer in order to avoid any network exposure.", "Password protection, access controls, encryption where appropriate, and compliance with applicable privacy laws.", "Restricting record access to clinical staff through a shared office login.", "Storage with a consumer cloud service that offers two-factor authentication."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Electronic records require reasonable administrative, technical, and physical safeguards consistent with professional and legal privacy standards."}, {"id": "q270", "text": "A counselor feels attracted to a current client. The most ethical first step is to:", "options": ["Reduce the session frequency and keep all interactions strictly task-focused.", "Disclose the attraction honestly to the client so that transparency preserves the therapeutic trust.", "Seek supervision/consultation, maintain boundaries, and consider transfer if objectivity is impaired.", "Transfer the client immediately so the feelings cannot affect the treatment."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Attraction to clients requires professional management through consultation and boundaries; sexual/romantic involvement with current clients is prohibited."}, {"id": "q271", "text": "Which practice best reflects ethical cultural sensitivity in assessment interpretation?", "options": ["Supplementing the standardized scores with results from a translated version of the same instrument.", "Considering language, acculturation, test bias, and ecological validity when interpreting results.", "Weighting the clinical interview over the test results for all diverse clients.", "Reporting the scores with a general disclaimer that culture may influence results."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Ethical assessment requires culturally informed interpretation, including awareness of bias, language, and contextual factors affecting scores."}, {"id": "q272", "text": "What does a validity scale on a personality inventory primarily help the counselor evaluate?", "options": ["Whether the instrument retains its measurement accuracy across clients from different cultural groups.", "Whether the client's profile matches established clinical criterion groups.", "Whether the instrument's items adequately sample the construct's full domain.", "Whether the client's response style (e.g., overreporting, underreporting, inconsistency) may distort results."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Validity scales assess response styles and protocol credibility, informing how cautiously clinical scales should be interpreted."}, {"id": "q273", "text": "A z-score of +1.0 approximately corresponds to which percentile in a normal distribution?", "options": ["34th percentile.", "90th percentile.", "84th percentile.", "68th percentile."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "In a normal distribution, about 84% of scores fall at or below one standard deviation above the mean."}, {"id": "q274", "text": "Which reliability type is most relevant when evaluating consistency of ratings between two independent observers?", "options": ["Interrater reliability.", "Split-half reliability.", "Test-retest reliability.", "Parallel-forms reliability."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Interrater reliability examines agreement between different raters or observers scoring the same phenomenon."}, {"id": "q275", "text": "Standard error of measurement (SEM) is most useful for:", "options": ["Setting the cutoff scores that separate clinical from nonclinical ranges.", "Estimating how much of the score variance reflects the measured trait.", "Comparing the relative reliability of two competing instruments.", "Estimating the range in which a client's true score is likely to fall."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "SEM quantifies score imprecision and supports confidence bands around obtained scores."}, {"id": "q276", "text": "A client meets symptom criteria for a disorder but shows no clinically significant distress or impairment. What is the diagnostic implication?", "options": ["Collateral informants should be sought before concluding, since clients often minimize their own functional impairment.", "Many diagnoses require clinically significant distress or impairment; absence may argue against the diagnosis.", "The diagnosis may be assigned provisionally until the impairment emerges.", "An other-specified diagnosis should be used so that treatment can be justified."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Most mental disorder diagnoses require clinically significant distress or functional impairment, not symptoms alone."}, {"id": "q277", "text": "Which assessment approach is most appropriate at first contact with a highly distressed client?", "options": ["Brief risk and needs screening, alliance building, and prioritized clinical assessment.", "A comprehensive battery administered in portions across the first three visits.", "Deferring all formal assessment until the acute distress has fully subsided.", "A structured diagnostic interview to establish the diagnosis before rapport work."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Initial contacts prioritize safety, engagement, and essential clinical information rather than exhaustive testing that may overwhelm the client."}, {"id": "q278", "text": "Construct validity is best described as:", "options": ["The degree to which the items representatively sample the content domain.", "The degree to which scores predict performance on a relevant external criterion.", "The degree to which a test measures the theoretical construct it purports to measure.", "The degree to which examinees perceive the test as measuring what it claims."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Construct validity concerns theoretical meaning of scores and evidence that the instrument measures the intended construct."}, {"id": "q279", "text": "A mental status exam finding of 'tangential thought process' means the client:", "options": ["Repeats the same idea in response to several different questions.", "Shifts between loosely related topics but eventually returns to the point.", "Digresses from the topic and does not return to the original point.", "Provides excessive irrelevant detail before finally answering the question."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Tangentiality involves departing from the topic without returning; it is a thought-process observation on the MSE."}, {"id": "q280", "text": "Which information is most critical when assessing for substance use disorder severity?", "options": ["Pattern of use, loss of control, tolerance/withdrawal, consequences, and impairment across life domains.", "The client's family history of substance use disorders across generations.", "The total duration of use and the specific age at which the client first began using each of the substances.", "The specific substances used and their typical routes of administration."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "SUD assessment examines control, physiological features, risk/consequences, and functional impairment—not legality alone."}, {"id": "q281", "text": "A counselor uses a cutoff score from a screening tool. What is a key limitation to communicate?", "options": ["Scores that fall near the cutoff are more reliable than scores at the extremes.", "The tool detects only those disorders the client is consciously aware of having.", "A score falling above the cutoff reflects symptom severity rather than diagnostic likelihood.", "Screening tools can yield false positives/negatives and require clinical follow-up for diagnosis."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Screening instruments flag risk or possible problems but are not substitutes for comprehensive diagnostic evaluation."}, {"id": "q282", "text": "Which client presentation most warrants immediate medical referral alongside counseling assessment?", "options": ["Occasional palpitations during panic attacks after a recent normal cardiac workup.", "Sudden severe headache, confusion, and neurological changes with anxiety-like symptoms.", "Chronic tension headaches that reliably worsen during stressful workweeks.", "Longstanding fatigue in a client with well-managed hypothyroidism."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Acute medical/neurological red flags require prompt medical evaluation; psychological symptoms can mask medical emergencies."}, {"id": "q283", "text": "In classical test theory, observed score equals:", "options": ["True score multiplied by the reliability coefficient.", "True score minus systematic bias.", "The mean of repeated administrations.", "True score plus error."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Classical test theory models an observed score as the sum of true score and measurement error."}, {"id": "q284", "text": "Which question best assesses protective factors during suicide risk assessment?", "options": ["Have you ever made an attempt to end your life at any point in the past?", "What would need to change in your life for the suicidal thoughts to go away?", "What reasons do you have for living, and who or what helps you stay safe?", "How often do the thoughts of suicide come, and how long do they usually last?"], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Protective factors (reasons for living, supports, coping, future orientation) are essential alongside risk factors in a complete suicide assessment."}, {"id": "q285", "text": "A client reports 'voices' that are actually their own critical thoughts recognized as internal. This is most consistent with:", "options": ["Ordinary negative self-talk requiring only cognitive restructuring rather than assessment.", "An internal experience that should be carefully differentiated from psychotic hallucinations.", "A pseudohallucination indicating the beginning of a psychotic prodrome.", "Intrusive thoughts consistent with an obsessive-compulsive presentation."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Clinicians must distinguish true hallucinations from intrusive thoughts, pseudohallucinations, or metaphorical language before diagnosing psychosis."}, {"id": "q286", "text": "Norm-referenced interpretation compares a client's score to:", "options": ["The performance of a defined norm group.", "An absolute standard of predetermined mastery levels.", "Expert consensus about clinically meaningful thresholds.", "The client's own earlier scores on the same measure."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Norm-referenced scores locate performance relative to a comparison group, unlike criterion-referenced mastery standards."}, {"id": "q287", "text": "Which practice improves the cultural validity of a clinical interview?", "options": ["Exploring explanatory models, language preference, supports, and stressors in cultural context.", "Matching the interviewer's overall communication style to established formal clinical conventions.", "Administering the interview in a fully standardized order for every client.", "Using an interpreter drawn from the client's own family for greater comfort."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Culturally responsive interviewing elicits the client's meaning-making, context, language needs, and culturally relevant stressors and strengths."}, {"id": "q288", "text": "Comorbidity in diagnosis means:", "options": ["One disorder is secondary to and fully explained by another disorder.", "Symptoms cross the thresholds of several related specifiers.", "A medical condition is producing the psychiatric symptoms.", "Two or more disorders are present in the same person."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Comorbidity refers to co-occurrence of multiple disorders, which affects assessment, prognosis, and treatment planning."}, {"id": "q289", "text": "Which is the best example of a process goal versus an outcome goal?", "options": ["Outcome: build a strong working alliance; Process: complete the intake battery.", "Outcome: reduce PHQ-9 by 50%; Process: attend weekly sessions and complete thought records twice weekly.", "Outcome: attend the weekly sessions consistently; Process: reduce the PHQ-9 scores by half within eight weeks.", "Outcome: feel noticeably happier; Process: practice thinking more positively."], "correct": 1, "domain": "Treatment Planning", "explanation": "Outcome goals target clinical results; process goals specify engagement and therapeutic activities that support those results."}, {"id": "q290", "text": "A client's insurance authorizes six sessions. How should this influence treatment planning?", "options": ["Reserve the authorized sessions for crisis use and provide interim support by phone.", "Compress the full original treatment plan so that every one of the goals is at least touched on within the six sessions.", "Prioritize high-impact goals, discuss constraints transparently, and plan for continuity or referral as needed.", "Design the plan for the clinically indicated length and appeal once the sessions end."], "correct": 2, "domain": "Treatment Planning", "explanation": "Ethical brief planning prioritizes feasible goals, informed consent about limits, and aftercare or referral options."}, {"id": "q291", "text": "What is the main advantage of using standardized outcome measures in treatment planning?", "options": ["They provide baseline and progress data to guide collaborative adjustments.", "They help ensure treatment fidelity to the chosen evidence-based protocol.", "They allow comparison of the counselor's outcomes against national benchmarks.", "They satisfy payer documentation requirements for continued authorization."], "correct": 0, "domain": "Treatment Planning", "explanation": "Routine outcome monitoring informs whether interventions are working and when to revise the plan."}, {"id": "q292", "text": "Which treatment plan element best addresses barriers to care?", "options": ["A motivational interviewing component to strengthen commitment to attendance.", "A written attendance agreement with clear expectations for participation.", "Identifying obstacles (schedule, cost, stigma, access) and building strategies to reduce them.", "Flexible treatment goals that can be pursued independently by the client whenever sessions are missed."], "correct": 2, "domain": "Treatment Planning", "explanation": "Effective plans anticipate practical and psychosocial barriers and include strategies to support engagement."}, {"id": "q293", "text": "In crisis-oriented treatment planning, the first-order goals typically focus on:", "options": ["Connection to long-term treatment before the first contact concludes.", "Early insight into the developmental origins of the crisis reaction.", "Rapid clarification of the diagnostic picture to guide the crisis response.", "Safety, stabilization, and reduction of acute distress."], "correct": 3, "domain": "Treatment Planning", "explanation": "Crisis plans emphasize immediate safety and stabilization before longer-term developmental or insight goals."}, {"id": "q294", "text": "A client's goal seems unrealistic within the timeframe. The best approach is to:", "options": ["Postpone the goal setting until the client develops a more accurate self-appraisal.", "Collaboratively refine goals into meaningful, achievable steps while honoring the client's values.", "Accept the goal exactly as stated, since self-determined goals carry the most motivation.", "Substitute a clinically realistic goal and explain the reasoning to the client afterward."], "correct": 1, "domain": "Treatment Planning", "explanation": "Collaborative planning balances hope with feasibility by shaping goals into attainable steps without dismissing client aspirations."}, {"id": "q295", "text": "Which statement best describes an evidence-informed treatment plan?", "options": ["It draws chiefly on the counselor's accumulated experience with similar cases.", "It selects whichever available intervention has the largest published effect size.", "It integrates research-supported interventions with client preferences, culture, and clinical expertise.", "It applies the chosen manualized protocol exactly as the protocol was tested in the original clinical trials."], "correct": 2, "domain": "Treatment Planning", "explanation": "Evidence-based practice combines best research evidence, clinician expertise, and client characteristics and preferences."}, {"id": "q296", "text": "Including family members in a minor's treatment plan is most appropriate when:", "options": ["The minor's symptoms fail to improve after a full month of individual work.", "The caregivers request regular updates, since holding legal consent entitles them to participate in the treatment.", "The family's involvement would make scheduling and transportation much easier.", "Clinically indicated, legally allowed, and aligned with consent/assent and the minor's best interests."], "correct": 3, "domain": "Treatment Planning", "explanation": "Family involvement is planned according to clinical need, developmental status, consent rules, and welfare of the minor."}, {"id": "q297", "text": "What is a discharge criterion in a treatment plan?", "options": ["The first point at which symptoms fall below the instrument's clinical cutoff.", "Predefined indicators that goals are met or services should step down or end.", "A standing agreement to end the treatment whenever the client feels ready.", "The projected number of sessions authorized for the current episode of care."], "correct": 1, "domain": "Treatment Planning", "explanation": "Discharge criteria specify when treatment can appropriately conclude or transition based on goal attainment and clinical status."}, {"id": "q298", "text": "A client with panic disorder and diabetes needs coordinated care. The plan should include:", "options": ["Appropriate releases and collaboration with medical providers when relevant to holistic care.", "A formal recommendation that the client consolidate all of their care under one single provider.", "A referral to medical case management in place of any direct collaboration.", "Psychoeducation about diabetes management delivered directly by the counselor."], "correct": 0, "domain": "Treatment Planning", "explanation": "Integrated planning coordinates mental and physical health care with proper authorization and role boundaries."}, {"id": "q299", "text": "Which goal best fits a client in precontemplation for smoking cessation?", "options": ["Increase awareness of personal impact and explore ambivalence without forcing action.", "Delay any discussion of smoking until the client raises the topic independently.", "Build refusal skills for the situations where the smoking urges run strongest.", "Establish a tapered reduction schedule with specific weekly nicotine targets."], "correct": 0, "domain": "Treatment Planning", "explanation": "Precontemplation work focuses on engagement and awareness rather than premature action goals the client is not ready to pursue."}, {"id": "q300", "text": "Progress notes should relate to the treatment plan by:", "options": ["Tracking the working alliance and session-by-session satisfaction ratings.", "Documenting interventions used and client response relative to planned goals/objectives.", "Summarizing the session narrative in the client's own words for authenticity.", "Recording the interventions delivered along with the session time and billing code."], "correct": 1, "domain": "Treatment Planning", "explanation": "Notes should connect session work to the plan, showing what was done and how the client responded toward goals."}, {"id": "q301", "text": "When two goals conflict (e.g., autonomy vs. safety), the counselor should:", "options": ["Present both goals to the client and follow whichever one the client selects.", "Suspend active work on both of the goals until the conflict between them can be fully explored and resolved in clinical supervision.", "Pursue the two goals in parallel, since treatment plans can hold competing aims.", "Prioritize safety when risk is significant, while maximizing client autonomy to the extent safely possible and documenting rationale."], "correct": 3, "domain": "Treatment Planning", "explanation": "Ethical prioritization places safety first under significant risk while preserving autonomy as much as is clinically and ethically feasible."}, {"id": "q302", "text": "A strength-based treatment plan would most likely include:", "options": ["Goals that emphasize wellness activities rather than direct symptom reduction.", "A standard problem list reframed into positive, achievement-oriented language.", "Client strengths, resources, and protective factors as active supports for change.", "An assets inventory completed at intake and kept on file for later reference."], "correct": 2, "domain": "Treatment Planning", "explanation": "Strength-based planning mobilizes client and environmental resources rather than focusing exclusively on deficits."}, {"id": "q303", "text": "Which is the best reason to revise a treatment plan mid-care?", "options": ["The counselor completes formal training in a promising newly published evidence-based approach.", "New assessment data, stalled progress, changed goals, or emerging risk require adjustment.", "The client requests a different modality after reading about it online.", "The plan reaches its regularly scheduled quarterly review milestone."], "correct": 1, "domain": "Treatment Planning", "explanation": "Plans should change when clinical reality changes—new information, insufficient progress, goal shifts, or risk developments."}, {"id": "q304", "text": "In group counseling treatment planning, individual goals should be:", "options": ["Standardized across the members so that group progress can be compared fairly.", "Written by each member privately to protect intermember confidentiality.", "Linked to group purpose while remaining relevant to each member's presenting concerns.", "Focused on group cohesion first, with individual concerns deferred until later."], "correct": 2, "domain": "Treatment Planning", "explanation": "Effective group work aligns personal goals with the group's purpose and therapeutic factors available in the group modality."}, {"id": "q305", "text": "Minimal encouragers (e.g., 'mm-hmm,' 'go on') are primarily used to:", "options": ["Support client continuation and convey attending without taking the floor.", "Reinforce disclosure selectively so that productive material increases.", "Communicate agreement with the client's perspective and decisions.", "Prompt the client toward the topics the counselor considers most useful."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Minimal encouragers are attending skills that invite the client to continue speaking."}, {"id": "q306", "text": "A reflection of meaning differs from a reflection of feeling because it:", "options": ["Focuses primarily on the cognitive content rather than the emotional tone of the client's narrative.", "Connects the client's present feeling to its origins in earlier life experience.", "Restates the client's narrative at a deeper level of emotional intensity.", "Captures the significance, values, or worldview underlying the client's narrative, not only the emotion."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Reflections of meaning address deeper significance and values; feeling reflections target affect."}, {"id": "q307", "text": "Immediacy in counseling refers to:", "options": ["Responding to the client's statements without any delay or hesitation.", "Prioritizing the client's most urgent presenting concern within each session.", "Addressing the here-and-now relationship or what is occurring between counselor and client in the moment.", "Disclosing the counselor's own immediate personal reactions to the details of the client's story."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Immediacy brings present-tense relational process into the therapeutic dialogue when clinically useful."}, {"id": "q308", "text": "Which intervention is most consistent with behavioral activation for depression?", "options": ["Increasing restful downtime so that energy recovers before new demands.", "Exploring the meaning of the lost activities before rescheduling them.", "Identifying and challenging the depressive thoughts that block activity.", "Increasing engagement in valued, reinforcing activities despite low motivation."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Behavioral activation targets avoidance and withdrawal by scheduling and engaging in reinforcing, valued activities."}, {"id": "q309", "text": "Systematic desensitization classically pairs:", "options": ["Anxiety cues with brief distraction until arousal returns to baseline.", "Gradual exposure hierarchy items with relaxation or competing responses.", "Feared imagery with response prevention until the urge to escape subsides.", "Massed exposure to the most feared stimulus until the anxiety extinguishes."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Systematic desensitization combines hierarchical exposure with relaxation or counterconditioning principles."}, {"id": "q310", "text": "In person-centered counseling, the counselor's primary 'technique' emphasis is on:", "options": ["Facilitative conditions—empathy, congruence, and unconditional positive regard—within the relationship.", "Carefully timed questions that direct the client's attention toward feelings.", "Skillful reflection techniques applied according to a structured sequence.", "Accurate and well-timed interpretations that gradually deepen the client's self-understanding over time."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Person-centered practice centers the therapeutic conditions of the relationship rather than a large toolkit of directive techniques."}, {"id": "q311", "text": "A scaling question (0–10) in solution-focused work is mainly used to:", "options": ["Determine whether the client has met the criteria for stepped-down care.", "Rank the client's problems so that the most severe is addressed first.", "Quantify symptom severity for the clinical record and outcome tracking.", "Assess current status, exceptions, and small steps toward a preferred future."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Scaling helps clients quantify progress, identify partial successes, and define next small improvements."}, {"id": "q312", "text": "Which response is an open question?", "options": ["Would you describe the argument as being mostly about work stress?", "What was going through your mind when the argument started?", "Can you tell me if the argument felt different from the earlier ones?", "Do you think the argument could have been avoided somehow?"], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Open questions invite elaboration; closed questions typically elicit yes/no or brief factual answers."}, {"id": "q313", "text": "Confrontation as a counseling skill is best defined as:", "options": ["Challenging the client's irrational beliefs directly and persistently until the client reconsiders them.", "Presenting evidence that contradicts the client's account of key events.", "Gently pointing out discrepancies among feelings, behaviors, and statements to promote awareness.", "Setting firm limits when a client's behavior disrupts the counseling work."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Therapeutic confrontation highlights inconsistencies in a respectful way to facilitate insight and change, not aggression."}, {"id": "q314", "text": "In MI, 'sustain talk' refers to:", "options": ["Client language favoring the status quo and against change.", "Counselor reflections that keep the conversation focused on change.", "Client statements committing to maintain the changes already made.", "Client language that weighs the pros and cons of making a change."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Sustain talk expresses reasons to stay the same; change talk expresses movement toward change. MI seeks to evoke change talk."}, {"id": "q315", "text": "Which group leadership function is most important in the initial stage?", "options": ["Establishing norms, safety, purpose, and facilitating inclusion and trust-building.", "Linking members' concerns to display the group's common themes.", "Drawing out the quieter members with direct process observations.", "Modeling appropriate self-disclosure so members learn interpersonal risk."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Early group work emphasizes orientation, norms, cohesion beginnings, and psychological safety."}, {"id": "q316", "text": "Reframing helps clients by:", "options": ["Softening the emotional intensity of the client's chosen language.", "Offering an alternative, more workable perspective on a situation or behavior.", "Correcting the distortions in the client's account of the situation.", "Redirecting the client's attention from the problem toward solutions."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Reframes shift meaning in ways that can reduce stuckness and open new behavioral options while still respecting client experience."}, {"id": "q317", "text": "Which technique is most associated with narrative therapy?", "options": ["Mapping the family structure to reveal the roles that maintain the problem.", "Using the miracle question to picture daily life without the problem.", "Assigning between-session behavioral experiments that test the problem's unwritten governing rules.", "Externalizing the problem and exploring unique outcomes that contradict the dominant problem story."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Narrative approaches separate person from problem (externalization) and thicken preferred stories through unique outcomes."}, {"id": "q318", "text": "Self-disclosure by the counselor is most appropriate when it:", "options": ["Is used routinely to model openness and equalize the relationship.", "Is offered whenever the client asks the counselor a direct personal question.", "Is brief, relevant, and likely to benefit the client's therapeutic process.", "Is limited to material the counselor has fully resolved emotionally."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Therapeutic self-disclosure is client-centered, purposeful, and limited—not a vehicle for counselor unmet needs."}, {"id": "q319", "text": "In exposure therapy for specific phobia, safety behaviors are often targeted because they:", "options": ["Can prevent disconfirmation of feared outcomes and maintain anxiety.", "Interfere with building the relaxation response during the exposure.", "Raise physiological arousal and directly intensify the panic response.", "Transfer the avoidance from the situation onto the counselor's presence."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Safety behaviors may block corrective learning during exposure; reducing them carefully can improve treatment effects."}, {"id": "q320", "text": "Summarization is especially useful at:", "options": ["Points where the counselor needs a moment to plan the next intervention.", "Moments when the client pauses and looks to the counselor for direction.", "Times when a client's account of recent events needs to be carefully verified for accuracy.", "Transition points, session openings/closings, and when organizing complex client material."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Summaries organize content and affect, check understanding, and help structure session flow and focus."}, {"id": "q321", "text": "Which intervention best fits dialectical behavior therapy (DBT) skills training?", "options": ["Teaching acceptance, defusion, values clarification, and committed action skills.", "Teaching mindfulness, distress tolerance, emotion regulation, and interpersonal effectiveness skills.", "Teaching assertiveness, relaxation, social skills, and stress inoculation techniques.", "Teaching cognitive restructuring, behavioral activation, exposure, and problem-solving skills."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "DBT skills modules classically include mindfulness, distress tolerance, emotion regulation, and interpersonal effectiveness."}, {"id": "q322", "text": "According to Holland, a person high in Investigative interests is most likely to enjoy:", "options": ["Helping, teaching, and providing direct service to other people.", "Working with tools, machines, and hands-on outdoor tasks.", "Scientific, analytic, and research-oriented activities.", "Leading teams and persuading others toward shared objectives."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Investigative types prefer analytical, scientific, and intellectual problem-solving environments and tasks."}, {"id": "q323", "text": "Krumboltz's social learning theory of career decision making emphasizes:", "options": ["Learning experiences, environmental conditions, task approach skills, and cognitive processes influencing career paths.", "Circumscribing options according to prestige and sex-type acceptability.", "Matching a person's stable measured traits and personal factors to the documented requirements of occupations.", "Implementing the self-concept through progressive life stages and roles."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Krumboltz highlights learning experiences and cognitive-behavioral factors, including the role of planned happenstance/chance."}, {"id": "q324", "text": "The stages of change (transtheoretical model) progress most accurately as:", "options": ["Precontemplation, then preparation, followed by contemplation, action, and finally maintenance.", "Contemplation, precontemplation, preparation, action, and then maintenance.", "Awareness, motivation, commitment, action, and then relapse prevention.", "Precontemplation, contemplation, preparation, action, maintenance (with possible relapse/recycling)."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "TTM stages include precontemplation through maintenance, recognizing non-linear movement and relapse as common."}, {"id": "q325", "text": "A client with PTSD avoids trauma reminders and reports hyperarousal. A first-line counseling consideration is:", "options": ["Prompt trauma-focused exposure within the first sessions to prevent chronicity.", "Relaxation training and symptom management fully completed before any direct discussion of the traumatic material.", "Safety, stabilization, psychoeducation, and evidence-based trauma treatment matched to readiness and training.", "Referral for EMDR, since it is the required first-line treatment for trauma."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Trauma work prioritizes safety and appropriate pacing; evidence-based treatments require competence and client readiness."}, {"id": "q326", "text": "Piaget's stage characterized by abstract reasoning and hypothetical thinking is:", "options": ["Concrete operational.", "Formal operational.", "Sensorimotor.", "Preoperational."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Formal operations involve abstract, hypothetical-deductive reasoning typically emerging in adolescence."}, {"id": "q327", "text": "Bowlby's attachment theory most strongly emphasizes:", "options": ["Inborn temperamental differences that determine relational style.", "Behavior shaped by reinforcement histories within the family system.", "Early caregiver bonds shaping internal working models of self and others.", "Psychosocial crises resolved at each stage of the lifespan."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Attachment theory posits that early relational bonds form internal working models influencing later relationships and emotion regulation."}, {"id": "q328", "text": "A client reports microaggressions at work and resulting anxiety. Culturally responsive counseling would:", "options": ["Validate the experience, explore impact and coping, and consider advocacy/empowerment options as appropriate.", "Focus on cognitive reappraisal so that the events lose their emotional charge.", "Encourage the client to file a formal complaint as the first therapeutic step.", "Assess whether the reported anxiety reflects an oversensitivity to ambiguous interpersonal events at the workplace."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Affirming clients' experiences of discrimination and addressing psychological impact are core to multicultural counseling practice."}, {"id": "q329", "text": "Which family therapy approach is most associated with hierarchical structure, subsystems, and boundaries?", "options": ["Bowenian multigenerational therapy.", "Structural family therapy (Minuchin).", "Strategic family therapy (Haley).", "Experiential family therapy (Satir)."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Minuchin's structural model focuses on family organization, subsystems, boundaries, and hierarchical clarity."}, {"id": "q330", "text": "Bowen family systems theory especially emphasizes:", "options": ["Enactments, joining, and the restructuring of family boundaries.", "Paradoxical directives and prescribed rituals for symptom change.", "Family sculpting, congruent communication, and emotional experiencing.", "Differentiation of self, triangles, and multigenerational patterns."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Bowen concepts include differentiation, triangulation, emotional cutoff, and multigenerational transmission."}, {"id": "q331", "text": "An older adult client presents with sudden cognitive decline and depression. What is an important clinical focus?", "options": ["Begin grief-focused counseling work, since depression late in life typically follows accumulated losses.", "Assess for medical contributions, depression vs. neurocognitive concerns, supports, and appropriate referrals.", "Begin cognitive rehabilitation exercises to slow the observed decline.", "Schedule neuropsychological testing after a trial of antidepressant response."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Late-life changes require careful differential assessment, medical collaboration, and attention to functioning and supports."}, {"id": "q332", "text": "Which issue is most central in counseling clients with chronic illness?", "options": ["Coping, adjustment, meaning, adherence barriers, and mental health comorbidity related to illness course.", "Encouraging optimism, since a positive outlook improves medical outcomes.", "Differentiating the client's psychosomatic complaints from the genuine underlying disease process.", "Deferring the emotional work until the medical condition has stabilized."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Chronic illness counseling addresses adjustment, mood/anxiety, identity, relationships, and practical coping across the illness trajectory."}, {"id": "q333", "text": "A college student presents with perfectionism, all-or-nothing thinking, and binge-purge behaviors. Priority clinical focus includes:", "options": ["Referral to a campus peer support group addressing perfectionism and disordered eating.", "Cognitive restructuring of the all-or-nothing academic thinking first.", "Stress management for the academic pressures driving the behaviors.", "Medical stability assessment and eating-disorder-informed care with appropriate referrals."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Eating disorder presentations require attention to medical risk, specialized treatment, and coordinated care—not minimization."}, {"id": "q334", "text": "Gottman's research on couples most famously identifies which pattern as highly destructive?", "options": ["The pursuer-distancer cycle.", "Mutual negative reciprocity.", "The 'Four Horsemen' (criticism, contempt, defensiveness, stonewalling).", "The demand-withdraw communication pattern that escalates during couple conflict."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Gottman highlighted criticism, contempt, defensiveness, and stonewalling as particularly corrosive interaction patterns."}, {"id": "q335", "text": "Which career assessment is most associated with measuring interests rather than aptitudes?", "options": ["A mechanical reasoning assessment battery.", "A timed clerical speed and accuracy test.", "A values card sort or RIASEC interest inventory.", "A general cognitive ability composite score."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Interest inventories and values tools assess preferences and motivations; aptitude tests estimate abilities."}, {"id": "q336", "text": "A client in acute mania with poor sleep and reckless spending is brought by family. Counseling priority is:", "options": ["Motivational interviewing designed to build the client's insight into the episode's mounting consequences.", "Outpatient CBT targeting the grandiose thinking and racing thoughts directly.", "Family psychoeducation so that the home environment can contain the episode.", "Safety, medical/psychiatric evaluation for level of care, and stabilization before insight-oriented work."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Acute mania often requires medical/psychiatric stabilization and risk management before deeper psychosocial work."}, {"id": "q337", "text": "Acculturative stress is best described as:", "options": ["Discrimination-related stress imposed by the dominant culture.", "Stress arising from adapting to a new cultural environment and navigating cultural conflicts.", "The grief response to the losses experienced during migration.", "Identity confusion arising from ongoing bicultural conflict within the client's family."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Acculturative stress involves psychological strain from cultural adaptation, discrimination, language, and identity conflicts."}, {"id": "q338", "text": "Which factor is most important when counseling LGBTQ+ clients according to affirmative practice?", "options": ["Affirming identity, understanding minority stress, and creating a safe, nonpathologizing therapeutic environment.", "Matching the client with an LGBTQ+ identified counselor whenever possible.", "Maintaining careful therapeutic neutrality about identity so that the client leads all related discussion.", "Focusing the treatment on the client's identity development process itself."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Affirmative practice supports identity, addresses minority stress and discrimination, and rejects pathologizing or conversion approaches."}, {"id": "q339", "text": "Warmth in counseling is best demonstrated by:", "options": ["Prompt responsiveness to client messages and scheduling requests.", "Friendly, accepting nonverbal and verbal behavior that helps clients feel valued without boundary loss.", "A relaxed, informal style that minimizes professional distance.", "Consistent positive verbal feedback offered to the client about their ongoing progress and their visible effort in the work."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Therapeutic warmth conveys acceptance and care while maintaining professional boundaries and client comfort."}, {"id": "q340", "text": "Which attribute most helps a counselor sit with ambiguity in complex cases?", "options": ["Tolerance for uncertainty paired with careful assessment and consultation.", "Decisiveness that keeps the case moving forward despite unclear data.", "Reliance on structured protocols whenever presentations are unclear.", "Confidence in initial clinical impressions until they are contradicted."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Clinical work often involves incomplete data; effective counselors tolerate ambiguity while continuing disciplined inquiry."}, {"id": "q341", "text": "Integrity as a counselor attribute primarily means:", "options": ["Maintaining consistency between one's personal and professional personas.", "Being transparent with clients about the limits of counseling.", "Honoring every commitment made to clients without any exception.", "Acting consistently with ethical principles even when inconvenient."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Integrity involves honesty, ethical consistency, and alignment between professional values and behavior."}, {"id": "q342", "text": "A counselor who regularly seeks feedback on their work is demonstrating:", "options": ["Humility about the limits of independent judgment.", "Appropriate professional reliance on the supervisory relationship.", "Reflective practice and commitment to growth.", "Conscientious adherence to supervision requirements."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Inviting feedback supports reflective practice, skill development, and higher-quality care."}, {"id": "q343", "text": "Compassion fatigue risk is reduced most by:", "options": ["Emotional detachment techniques that limit empathic engagement.", "Rotating to lower-acuity clients whenever symptoms of fatigue appear.", "Sustainable caseloads, supervision, self-care, and organizational supports.", "Personal therapy focused on the counselor's early caregiving roles."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Preventing compassion fatigue requires systemic and personal strategies that protect counselor functioning and client care."}, {"id": "q344", "text": "Nonjudgmental acceptance means the counselor:", "options": ["Respects the client's worth even while addressing harmful behaviors and consequences.", "Suspends evaluation of the client's choices during the sessions.", "Interprets the client's harmful behaviors as expressions of unmet needs rather than problems.", "Prioritizes validation over behavior change throughout the work."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Acceptance of the person coexists with ethical responsibility to address harm, risk, and behavior change collaboratively."}, {"id": "q345", "text": "Which quality is most essential when a client challenges the counselor's cultural assumptions?", "options": ["Equanimity that keeps the challenge from disrupting the session.", "Openness, humility, and willingness to repair and learn.", "Fairness in weighing the client's perspective against one's own.", "Confidence in the training and intentions behind one's approach."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Cultural humility includes receiving client feedback nondefensively and adjusting practice."}, {"id": "q346", "text": "Professional presence includes:", "options": ["A calm and steady demeanor maintained regardless of session content.", "Consistently efficient sessions that respect the client's time and financial investment in counseling.", "Warm rapport built through appropriate humor and easy small talk.", "Reliability, preparedness, and respectful engagement that communicates the client matters."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Presence and professionalism are shown through reliability, attention, and respectful engagement."}, {"id": "q347", "text": "A counselor feels hopeless about a chronic client's progress. The healthiest attribute-driven response is to:", "options": ["Accept the plateau and shift the client to maintenance-only contact.", "Use supervision to process reactions, reassess the plan, and sustain a realistic hopeful stance.", "Transfer the client's care to a trusted colleague who can bring a fresh sense of optimism to the case.", "Disclose the discouragement so that the client understands the stakes."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Counselors manage their own reactions professionally, seek consultation, and maintain a balanced therapeutic stance."}, {"id": "q348", "text": "Authenticity without ethics is problematic because:", "options": ["Clients may feel pressure to reciprocate with personal disclosures that exceed their actual readiness.", "Authenticity varies too widely across counselors to guide practice.", "It erodes the counselor's credibility as an objective professional.", "Unfiltered self-expression can harm clients; genuineness must remain boundaried and client-centered."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Therapeutic genuineness is not license for harmful disclosure; it is authenticity within professional role and ethics."}, {"id": "q349", "text": "Patience as a counseling attribute is most evident when the counselor:", "options": ["Accepts missed sessions and incomplete homework without comment.", "Deliberately withholds planned interventions until the client explicitly asks for them.", "Allows clients to move at a clinically appropriate pace while still addressing safety and goals.", "Extends the overall treatment timeline whenever progress slows."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Patience supports client pacing and readiness without abandoning structure, goals, or safety responsibilities."}, {"id": "q350", "text": "Which attribute best supports working with clients who hold values different from the counselor's?", "options": ["Respect for autonomy and bracketing personal values that would interfere with client welfare.", "Strict ethical neutrality that keeps all discussion of values out of the counseling room.", "Genuine curiosity about how the client's values first developed.", "Flexibility to adapt one's own values to align with the client's."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Ethical practice respects client autonomy and avoids imposing the counselor's personal values on client goals."}, {"id": "q351", "text": "Courage in counseling may look like:", "options": ["Persisting steadily with the agreed treatment plan despite slow early progress.", "Addressing risk, rupture, or hard truths compassionately when it serves the client.", "Sharing one's honest reactions whenever they arise during the session.", "Tolerating intense client affect without changing the subject."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Therapeutic courage involves entering difficult but necessary conversations with care and skill."}, {"id": "q352", "text": "A counselor who notices preferential treatment toward clients similar to themselves is demonstrating a need for:", "options": ["Self-awareness and corrective action regarding countertransference and equity.", "Additional formal training in multicultural counseling competencies.", "Stronger reliance on structured, manualized treatment protocols.", "Consultation to determine whether the preference has harmed anyone."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Awareness of bias and preferential pulls is essential to fair, ethical, and effective care for all clients."}, {"id": "q353", "text": "Hope as a counselor attribute is best described as:", "options": ["Optimism that consistently highlights client strengths over the presenting problems.", "An expectation of steady progress communicated consistently to clients.", "A realistic belief that change is possible, paired with honest appraisal of challenges.", "Confidence that evidence-based treatment produces reliable improvement."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Therapeutic hope is grounded and honest—supporting possibility without denying difficulty or promising impossible results."}, {"id": "q354", "text": "Which combination best captures mature professional empathy?", "options": ["Deep emotional resonance that closely and consistently mirrors the client's affective state.", "Compassionate concern combined with warm and supportive responses.", "Accurate cognitive perspective-taking on the client's situation.", "Feeling with the client while maintaining differentiation and the capacity to think clinically."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Mature empathy joins affective attunement with professional boundaries and clinical thinking rather than fusion or cold detachment."}, {"id": "q355", "text": "A counselor discovers an unpaid client balance after termination. The most ethical first step is to:", "options": ["Follow the fee agreement and ethical collection practices, avoiding harmful or confidential disclosures.", "Offer the former client additional sessions in exchange for settling the balance.", "Write off the remaining balance quietly to avoid any dual-role tension.", "Send the account directly to collections without prior notice, disclosing only the amount owed."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Fee recovery must respect dignity, confidentiality, and the original fee agreement; coercive or public shaming tactics are unethical."}, {"id": "q356", "text": "Which situation most clearly constitutes client abandonment?", "options": ["Terminating the work collaboratively with appropriate referrals once the agreed treatment goals have been met.", "Ending services abruptly without adequate notice or referral while the client still needs care, especially in crisis.", "Transferring a client to a new provider through a planned and warm handoff.", "Taking a scheduled vacation with emergency coverage arranged and communicated."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Abandonment involves discontinuing needed services without appropriate notice, planning, or referral."}, {"id": "q357", "text": "A counselor wants to accept a friend as a therapy client in a rural area with few providers. The best ethical approach is to:", "options": ["Refer the friend to telehealth options regardless of the local provider shortage.", "Accept the friend as a client with a detailed written agreement specifying that all sessions and related contact will remain strictly professional.", "Carefully evaluate dual-relationship risks, alternatives, informed consent, and consultation before deciding; refer when risk is too high.", "Accept the friend but limit the work to a brief, structured, goal-limited model."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Nonsexual dual relationships require case-by-case evaluation of benefit, risk, alternatives, consent, and documentation—especially in rural settings."}, {"id": "q358", "text": "Which statement about counselor values and client autonomy is most accurate?", "options": ["Counselors remain silent about all value-laden topics in order to protect autonomy.", "Counselors promptly arrange a referral whenever a client's personal life decisions come into direct conflict with the counselor's own deeply held personal values.", "Counselors may share their personal values whenever clients directly ask for them.", "Counselors respect client autonomy and avoid imposing personal values, seeking consultation or referral when competence or harm is at issue."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Ethical practice honors client self-determination and forbids value imposition while addressing competence and welfare concerns appropriately."}, {"id": "q359", "text": "HIPAA-related counseling practice most directly concerns:", "options": ["Privacy, security, and permitted uses/disclosures of protected health information.", "Mandated reporting duties for abuse, neglect, and imminent danger.", "Informed consent requirements for treatment and fee agreements.", "Professional licensure standards and mandatory continuing education requirements."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "HIPAA sets national standards for protecting health information privacy and security for covered entities."}, {"id": "q360", "text": "A client who is a minor discloses ongoing physical abuse by a caregiver. The counselor should:", "options": ["Assess the credibility and consistency of the disclosure over several sessions before filing any report.", "Follow mandated reporting laws and agency policy while attending to the minor's safety and support.", "Report only if physical evidence of the abuse is directly observable.", "Refer the family to protective parenting services in place of filing a report."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Suspected child abuse typically requires mandated reporting; counselors act to protect the child within legal and ethical frameworks."}, {"id": "q361", "text": "Which practice is most appropriate when a counselor lacks competence in a needed specialty?", "options": ["Co-treat informally with a colleague who holds the needed specialty.", "Proceed using common therapeutic factors, since the relationship drives most treatment outcomes.", "Obtain training/supervision or make an appropriate referral so the client receives competent care.", "Disclose the limitation and let the client decide whether to continue."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Practice within competence; seek training, supervision, or referral rather than providing inadequate care."}, {"id": "q362", "text": "An ethical informed consent discussion for group counseling should include:", "options": ["A clear guarantee that the group leader will personally maintain each individual member's confidentiality at all times.", "Assurance that participation will remain comfortable for every member.", "The group schedule, the fees, and the leader's professional credentials.", "Group purpose, format, risks/benefits, confidentiality limits among members, and expectations for participation."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Group consent covers process, risks, benefits, and the special confidentiality limits that arise with multiple members."}, {"id": "q363", "text": "A counselor is asked to evaluate a current therapy client for a court custody case. The best response is to:", "options": ["Accept the role after obtaining the client's written consent to the dual function.", "Complete the evaluation using only the information already in the clinical record.", "Avoid dual roles; decline forensic evaluation of a current client and explain role conflicts.", "Perform the evaluation with a second counselor reviewing the report for objectivity."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Therapeutic and forensic roles conflict; counselors avoid dual roles that impair objectivity and harm the therapeutic relationship."}, {"id": "q364", "text": "Which action best supports ethical advertising of counseling services?", "options": ["Featuring client testimonials collected after successful termination of treatment.", "Describing the outcomes that typical clients can expect from the services.", "Listing the techniques the counselor is currently completing training in.", "Providing accurate credentials, services, and claims without deceptive guarantees."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Advertising must be truthful regarding qualifications, services, and expected outcomes without deception."}, {"id": "q365", "text": "When a client dies, ethical record handling generally includes:", "options": ["Transferring the record to the client's physician for medical archiving.", "Maintaining records securely per law/policy and releasing information only to authorized parties.", "Sealing the record permanently from everyone, since confidentiality survives the client's death absolutely.", "Releasing the record to the next of kin upon request as the natural heir."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Records remain protected after death; disclosure follows legal authority and professional standards."}, {"id": "q366", "text": "A counselor provides pro bono services. Ethically, the counselor should:", "options": ["Maintain the same professional standards of competence, consent, and documentation as with other clients.", "Prioritize paying clients in scheduling while maintaining the same care quality.", "Set somewhat more flexible boundaries, since the usual fee structure no longer defines the treatment frame.", "Limit documentation to attendance, since no billing records will be required."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Pro bono work still requires full professional standards; reduced fees do not reduce ethical obligations."}, {"id": "q367", "text": "Which scenario most clearly requires consultation?", "options": ["A complex ethical dilemma involving dual relationships, risk, or competence boundaries.", "A client's routine written request for a copy of their own treatment records.", "A colleague's request to trade office hours for schedule coverage.", "A first-time no-show from a long-term and clinically stable client."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Consultation is indicated for ethical complexity, risk, dual roles, and competence questions."}, {"id": "q368", "text": "A client asks the counselor to lie to an insurer about diagnosis to obtain coverage. The counselor should:", "options": ["Bill under a covered diagnosis the client technically meets at a subthreshold level.", "Refuse fraudulent documentation and discuss ethical/legal alternatives and accurate advocacy options.", "Document the requested diagnosis provisionally while the ongoing treatment clarifies the picture.", "Refer the client to a provider whose services the insurance plan will cover."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Fraudulent billing or diagnosis is unethical and illegal; counselors maintain honesty in records and claims."}, {"id": "q369", "text": "Distance counseling across state lines most critically requires attention to:", "options": ["Time zone coordination and secure electronic scheduling procedures.", "The client's comfort with technology and access to a private space.", "Licensure/jurisdiction, emergency procedures, and technology-related informed consent.", "Platform encryption standards and the counselor's professional liability coverage."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Telehealth practice must address jurisdiction/licensure, crisis response by location, and modality-specific consent."}, {"id": "q370", "text": "Which is the best example of a boundary crossing that may be ethical if carefully managed?", "options": ["Inviting a long-term client to attend one of the counselor's own family celebrations as a shared therapeutic milestone.", "Employing a current client part-time to help them through financial hardship.", "Lending a client a small sum of money for transportation to sessions.", "Attending a client's graduation when clinically appropriate, with clear rationale, cultural sensitivity, and documentation."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Some boundary crossings can be beneficial if intentional, non-exploitative, and well processed; sexual dual roles are not in this category."}, {"id": "q371", "text": "Ethical research with counseling clients requires:", "options": ["Compensation generous enough to ensure adequate participant enrollment.", "A waiver of documented consent whenever the study poses only minimal risk.", "Informed consent, minimization of harm, voluntary participation, and IRB/ethical oversight as applicable.", "Preferential enrollment of the counselor's own active clients to help control treatment fidelity."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Research ethics require consent, voluntary participation, risk minimization, and appropriate review."}, {"id": "q372", "text": "A counselor's personal social media should ideally:", "options": ["Use privacy settings and professional policies that prevent harmful dual relationships and confidentiality breaches.", "Maintain a single combined personal-professional account that clients may follow strictly for psychoeducation.", "Accept client follow requests while never initiating any contact with clients.", "Share public posts discussing clinical themes without using any client names."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Social media policies and privacy practices help maintain boundaries and protect client confidentiality."}, {"id": "q373", "text": "Which record-keeping practice is most ethical?", "options": ["Comprehensive near-verbatim accounts of each session for completeness.", "Timely, accurate, and sufficiently thorough documentation of clinically relevant information.", "Delaying documentation until the end of each week to allow for reflection.", "Deliberately concise notes limited to dates and attendance in order to minimize liability exposure."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Records should be timely, accurate, relevant, and protective of privacy while supporting continuity of care."}, {"id": "q374", "text": "A supervisor asks a counselor to ignore a mandated report to protect agency reputation. The counselor should:", "options": ["Defer to the supervisor's authority while documenting the disagreement.", "File the report while omitting any record of the supervisor's request.", "Raise the concern first with the agency's internal review board before any external report.", "Follow legal/ethical reporting duties and seek appropriate consultation/advocacy channels."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Legal and ethical duties to protect vulnerable persons supersede organizational pressure to suppress reports."}, {"id": "q375", "text": "Which best describes privileged communication?", "options": ["A legal protection limiting compelled disclosure of confidential counseling communications in legal proceedings, with exceptions.", "The ethical duty of counselors to protect client information in all settings.", "A formal private agreement made between the counselor and the client at intake to keep everything said in all of the sessions strictly confidential.", "The client's legal right to review and amend their own counseling records."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Privilege is a legal concept restricting courtroom disclosure of confidential communications, subject to exceptions and jurisdiction."}, {"id": "q376", "text": "When translating services are needed, ethical practice favors:", "options": ["Machine translation tools used with the client's documented consent.", "Qualified interpreters and attention to confidentiality, accuracy, and cultural nuance.", "Simplified spoken English carefully supplemented with written translated materials.", "Bilingual family members who already know the client's situation well."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Qualified interpretation protects informed consent, accuracy, and confidentiality better than ad hoc family interpreters."}, {"id": "q377", "text": "A counselor receives a request for records from a third party without a release. The counselor should:", "options": ["Provide a brief treatment summary rather than the full record as a middle path.", "Release the records if the requesting party is another treating provider.", "Confirm only the dates of treatment attendance, since scheduling data is not clinical content.", "Decline unauthorized disclosure and request proper authorization or legal compulsion as applicable."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Absent authorization or legal requirement, counselors protect confidentiality and do not release records."}, {"id": "q378", "text": "Ethical multiple relationships are evaluated primarily based on:", "options": ["Whether the additional role begins before or after treatment terminates.", "Whether the client initiated the additional relationship and consents to it.", "Potential for impairment of judgment, exploitation, and harm versus benefit, with informed consent and documentation.", "Whether the specific additional relationship is explicitly and formally prohibited by the profession's ethics code."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Risk of exploitation and impaired objectivity is central to dual/multiple relationship decisions."}, {"id": "q379", "text": "Which action best demonstrates ethical gatekeeping in counselor education/supervision?", "options": ["Extending the trainee's practicum timeline and waiting for the competence concerns to resolve gradually on their own.", "Transferring the trainee's clients to stronger peers while coursework proceeds.", "Addressing trainee competence problems through remediation, documentation, and due process as needed to protect clients.", "Raising admission standards so struggling trainees are screened out earlier."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Gatekeeping protects clients by ensuring trainees meet competence standards through fair, documented processes."}, {"id": "q380", "text": "Content validity is primarily concerned with:", "options": ["Whether test items adequately sample the domain of interest.", "Whether examinees judge the items to be relevant and fair.", "Whether the test measures the theoretical construct as intended.", "Whether scores correlate with an established external criterion measure."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Content validity addresses representativeness of items relative to the content domain."}, {"id": "q381", "text": "A reliability coefficient of .40 for a high-stakes clinical decision instrument suggests:", "options": ["Strong evidence that the underlying construct is unstable over time.", "Substantial measurement error; interpret scores cautiously and avoid overreliance.", "Adequate reliability for screening, since precision matters mainly in research.", "Acceptable precision when the instrument is paired with clinical judgment."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Low reliability implies large error; high-stakes interpretations require adequate reliability."}, {"id": "q382", "text": "Which scale of measurement allows meaningful ratios and a true zero?", "options": ["Nominal.", "Interval.", "Ordinal.", "Ratio."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Ratio scales have equal intervals and a true zero (e.g., reaction time, weight)."}, {"id": "q383", "text": "The primary purpose of a mental status examination is to:", "options": ["Describe current cognitive, emotional, and behavioral functioning systematically.", "Assess premorbid functioning and early developmental history.", "Track longitudinal change in symptoms across the treatment episode.", "Establish the working diagnostic impression from the structured observations."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "The MSE is a structured cross-sectional description of present functioning."}, {"id": "q384", "text": "Which finding most strongly suggests need to assess for mania?", "options": ["Irritability and ongoing insomnia during a period of unusually high work stress.", "Decreased need for sleep, grandiosity, pressured speech, and risky behavior lasting days.", "Two weeks of elevated productivity following a promotion at work.", "Bursts of energetic goal pursuit that resolve within a few hours."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Mania involves elevated/irritable mood with increased energy/activity and associated symptoms over a period of days."}, {"id": "q385", "text": "False negatives on a depression screener mean:", "options": ["The screener's specificity is too low for routine clinical use.", "The cutoff score has been set too low for the population.", "People without depression are incorrectly flagged as positive.", "People who have depression are missed by the screener."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "A false negative fails to detect a condition that is actually present (missed case)."}, {"id": "q386", "text": "Which interview style is most structured?", "options": ["A clinical intake that follows the agency's standard outline of topics.", "A motivational interviewing session with consistent use of the OARS skills.", "A standardized diagnostic interview with prescribed questions and scoring rules.", "A semistructured interview covering required domains with flexible follow-up."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Structured interviews use standardized questions and decision rules to improve reliability."}, {"id": "q387", "text": "Base rate is important in assessment because:", "options": ["Base rates apply to screening instruments but not to diagnostic interviews.", "Low base rates make the positive results more trustworthy than the negative results.", "Base rates determine the reliability coefficient of the instrument itself.", "The prevalence of a condition influences how predictive a positive/negative test result is."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Predictive value depends on prevalence/base rates as well as sensitivity and specificity."}, {"id": "q388", "text": "Which is the best example of an aptitude test purpose?", "options": ["Estimating potential to learn or perform in a domain with training.", "Measuring current mastery of a formally taught curriculum domain.", "Describing enduring patterns of temperament and disposition.", "Identifying stable preferences among different types of activities."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Aptitude assessment estimates capacity to develop skills or succeed in particular areas."}, {"id": "q389", "text": "A client scores two standard deviations above the mean on a normally distributed test. Approximate percentile is:", "options": ["95th.", "98th.", "90th.", "84th."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "About 98% of scores fall below +2 SD in a normal distribution."}, {"id": "q390", "text": "Which assessment is most appropriate for immediate suicide risk?", "options": ["A standardized depression severity inventory administered and scored against established clinical cutoffs.", "A structured review of risk factors from the intake history and family record.", "Direct inquiry about ideation, plan, intent, means, history, protective factors, and current safety.", "Careful observation of affect and behavior across the next several sessions."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Suicide risk assessment requires direct, thorough inquiry and safety evaluation."}, {"id": "q391", "text": "Criterion-referenced interpretation emphasizes:", "options": ["Standing relative to a representative norm group.", "Rank within the current cohort of examinees.", "Performance against a defined standard or learning objective.", "Growth relative to the client's own earlier performance."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Criterion-referenced scores indicate mastery relative to a standard rather than rank in a group."}, {"id": "q392", "text": "Which DSM principle is most accurate?", "options": ["Diagnosis requires laboratory or biological confirmation wherever available.", "Diagnosis reflects the single most severe presenting symptom cluster.", "Diagnosis is definitively established as soon as the client's symptom count crosses the listed criterion threshold.", "Diagnosis considers clinically significant disturbance, duration, impairment/distress, and differential considerations."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Diagnosis integrates symptoms, duration, impairment, differentials, and contextual factors."}, {"id": "q393", "text": "Internal consistency reliability is often estimated with:", "options": ["Agreement indices computed between two independent raters.", "Coefficient alpha (or related indices) based on item interrelationships.", "Correlations between carefully constructed alternate forms.", "Correlations between two administrations separated by a set interval."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Internal consistency reflects how consistently items on a test measure the same construct."}, {"id": "q394", "text": "A client appears sedated, with slowed speech and poor concentration after starting a new medication. The counselor should:", "options": ["Assess safety, document observations, and coordinate with the prescriber as appropriate with authorization.", "Explore the psychological meaning of the client's slowed presentation.", "Advise the client to pause the medication until normal alertness returns.", "Postpone all further counseling sessions until the prescriber has completed a full medication review."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Medication side effects can mimic or worsen psychiatric symptoms and require collaborative medical attention."}, {"id": "q395", "text": "Which statement about projective tests is most balanced for NCE-level practice?", "options": ["They may yield clinical hypotheses but often have contested psychometric properties and require cautious use.", "They uniquely access unconscious processes that structured measures cannot reach, making them essential.", "They retain their validity only when administered in the original language.", "They are most useful when scored with strict actuarial formulas alone."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Projectives can generate hypotheses but typically require careful, limited interpretation given psychometric limitations."}, {"id": "q396", "text": "Functional assessment of behavior often identifies:", "options": ["The cognitive distortions that precede the problem behavior.", "The developmental period in which the behavior first emerged.", "The diagnostic category that best accounts for the behavior.", "Antecedents, behaviors, and consequences maintaining a problem pattern."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "ABC functional assessment links context and reinforcement contingencies to problem behaviors."}, {"id": "q397", "text": "Which is a biopsychosocial assessment element?", "options": ["A chronological account of the client's previous treatment episodes.", "Biological, psychological, and social contributors to the presenting problem.", "The client's mental status at the time of the clinical interview.", "The client's presenting symptoms mapped to the diagnostic criteria."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Biopsychosocial assessment integrates medical/biological, psychological, and social/contextual domains."}, {"id": "q398", "text": "Malingering differs from factitious disorder primarily in that malingering involves:", "options": ["Exaggeration of genuine symptoms in order to obtain emotional support.", "Unconscious symptom production in response to psychological conflict.", "Intentional symptom production motivated by external incentives.", "Intentional symptom production motivated by assuming the sick role."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Malingering is intentional feigning for external secondary gain; factitious disorder is driven by the sick role without obvious external rewards."}, {"id": "q399", "text": "Which cognitive screening concern is most urgent?", "options": ["Slowed processing in a client taking a sedating antihistamine.", "Stable mild forgetfulness that the family reports has not worsened.", "Gradual word-finding difficulty that has progressed slowly over the past several years.", "Sudden confusion, disorientation, and fluctuating alertness suggesting possible delirium."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Acute fluctuating confusion raises concern for delirium and medical emergency evaluation."}, {"id": "q400", "text": "Convergent validity evidence is shown when:", "options": ["A test shows low correlations with measures of unrelated constructs.", "A test predicts membership in a known diagnostic group.", "A test correlates strongly with measures of the same construct.", "A test's items correlate strongly with the total test score."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Convergent validity is supported by correlations with similar constructs/measures."}, {"id": "q401", "text": "Discriminant (divergent) validity is supported when:", "options": ["A depression scale shows lower correlations with measures of dissimilar constructs than with depression measures.", "A depression scale's items correlate strongly with the scale's own total score.", "A depression scale accurately predicts later depressive episodes over time.", "A depression scale correlates strongly and consistently with several other well-established depression measures."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Discriminant validity requires measures not to correlate highly with unrelated constructs."}, {"id": "q402", "text": "Which intake area is essential for almost all first sessions?", "options": ["Developmental milestones from infancy through late adolescence.", "Presenting problem, history, risk, functioning, supports, and goals.", "Standardized personality and symptom inventory results.", "Diagnostic impressions, treatment recommendations, and prognosis."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Core intake covers problem definition, history, risk, functioning, resources, and treatment goals."}, {"id": "q403", "text": "A bilingual client requests assessment in their preferred language. Best practice is to:", "options": ["Defer formal testing until the client's English is sufficient for the instruments.", "Provide linguistically appropriate assessment or qualified interpretation and consider language effects on results.", "Administer the assessment in English with extra time and simplified instructions.", "Use the client's preferred language for the interview while keeping English for the standardized instruments."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Language-appropriate assessment improves validity and ethics; interpretation quality matters."}, {"id": "q404", "text": "Which best defines sensitivity of a diagnostic test?", "options": ["Degree to which the test detects change in symptom severity over time.", "Probability that a person without the disorder tests negative.", "Proportion of positive results that reflect true cases of the disorder.", "Probability that a person with the disorder tests positive."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Sensitivity is the true positive rate among those who have the condition."}, {"id": "q405", "text": "SMART goals are designed to be:", "options": ["Specific, measurable, achievable, relevant, and time-bound.", "Standardized, monitored, adjustable, research-based, and theory-driven.", "Sequential, manageable, attainable, reviewed, and terminable.", "Strengths-based, motivational, action-oriented, realistic, and therapeutic."], "correct": 0, "domain": "Treatment Planning", "explanation": "SMART criteria make goals trackable and clinically useful."}, {"id": "q406", "text": "The primary purpose of a problem list in a treatment plan is to:", "options": ["Translate the clinical diagnosis into the client's everyday language.", "Provide the payer with justification for the diagnosis on the claim.", "Identify and prioritize clinically relevant issues guiding interventions.", "Record every concern the client raises so nothing is lost between sessions."], "correct": 2, "domain": "Treatment Planning", "explanation": "Problem lists organize and prioritize targets for intervention."}, {"id": "q407", "text": "Which is the best initial objective for severe panic with avoidance?", "options": ["Stabilize the panic with relaxation training before introducing any exposure work.", "Track the panic frequency for one month to establish a reliable baseline first.", "Begin interoceptive exposure at the very top of the hierarchy to maximize the early learning.", "Develop a collaborative hierarchy and begin graded exposure with coping skills over defined weeks."], "correct": 3, "domain": "Treatment Planning", "explanation": "Anxiety plans often combine psychoeducation, coping skills, and graded exposure with measurable steps."}, {"id": "q408", "text": "Level-of-care decisions should be based primarily on:", "options": ["Risk, severity, supports, functioning, and least restrictive appropriate setting.", "The most common placement for clients presenting with similar diagnoses.", "The diagnostic severity specifier assigned at the intake evaluation.", "The client's stated preference for the least disruptive treatment option."], "correct": 0, "domain": "Treatment Planning", "explanation": "Care level matches clinical severity and safety while preferring the least restrictive effective setting."}, {"id": "q409", "text": "A treatment plan that lists interventions without goals is weak because:", "options": ["Interventions cannot be selected until a formal diagnosis has been documented.", "Goals define desired outcomes that give interventions purpose and allow evaluation.", "Payers will reimburse only those plans with measurable outcome benchmarks.", "Clients cannot give valid consent to interventions that lack written objectives."], "correct": 1, "domain": "Treatment Planning", "explanation": "Goals specify outcomes; interventions are means toward those outcomes."}, {"id": "q410", "text": "When progress stalls, an evidence-informed next step is to:", "options": ["Extend the overall treatment timeline, since plateaus typically resolve with patience.", "Switch promptly to a different evidence-based modality to restore momentum.", "Reassess alliance, goals, barriers, diagnosis, and intervention fit; then revise the plan.", "Increase the session frequency in order to intensify the current approach."], "correct": 2, "domain": "Treatment Planning", "explanation": "Stalled progress prompts systematic review of alliance, case formulation, and plan fit."}, {"id": "q411", "text": "Psychoeducation belongs in treatment planning when it:", "options": ["Reduces liability by documenting that the risks were fully reviewed.", "Establishes the counselor's clinical expertise early in the treatment relationship.", "Helps clients understand symptoms, rationale for interventions, and self-management skills.", "Ensures that clients can explain their diagnosis accurately to others."], "correct": 2, "domain": "Treatment Planning", "explanation": "Psychoeducation supports engagement, adherence, and skill building when matched to client needs."}, {"id": "q412", "text": "Which is a reasonable short-term goal for major depression in outpatient care?", "options": ["Client will experience improved mood and greater engagement in valued daily activities.", "Increase behavioral activation to three valued activities per week and reduce PHQ-9 by a defined amount in 6–8 weeks.", "Client will understand the connections among activity, thought patterns, and mood.", "Client will meaningfully process the significant losses contributing to the current depressive episode in session."], "correct": 1, "domain": "Treatment Planning", "explanation": "Short-term goals should be realistic, measurable, and linked to evidence-based strategies."}, {"id": "q413", "text": "Informed consent intersects treatment planning when counselors:", "options": ["Collaborate on goals/interventions and discuss risks, benefits, and alternatives.", "Provide the completed plan in writing with space for the client's signature.", "Explain the chosen approach and its typical structure during the first session.", "Review the diagnosis so the client understands why treatment is necessary."], "correct": 0, "domain": "Treatment Planning", "explanation": "Collaborative planning is part of ongoing informed consent and shared decision-making."}, {"id": "q414", "text": "Case formulation differs from diagnosis by:", "options": ["Summarizing the specific diagnostic criteria the client meets in a narrative form.", "Rating the severity and functional impact of each diagnosed condition.", "Classifying the presentation within an accepted nosological system.", "Explaining how factors maintain problems and guiding individualized intervention selection."], "correct": 3, "domain": "Treatment Planning", "explanation": "Formulation is an explanatory map connecting assessment to treatment choices."}, {"id": "q415", "text": "Which element is most important in safety planning?", "options": ["A signed commitment to contact the counselor before acting on any urges.", "Warning signs, coping strategies, social/professional supports, means reduction, and crisis contacts.", "A written schedule of temporarily increased session frequency maintained throughout the period of elevated risk.", "Psychoeducation about the cognitive distortions that accompany crisis states."], "correct": 1, "domain": "Treatment Planning", "explanation": "Safety plans are concrete, collaborative, and include means safety and crisis resources."}, {"id": "q416", "text": "Cultural adaptation of a treatment plan may include:", "options": ["Fully replacing the established evidence-based treatment protocol with the client community's traditional healing practices instead.", "Translating all of the treatment materials into the client's first language.", "Matching the client with a counselor who shares the client's cultural background.", "Modifying language, metaphors, family involvement, and goals to fit client cultural context while preserving core effective elements."], "correct": 3, "domain": "Treatment Planning", "explanation": "Cultural adaptation improves fit and engagement without abandoning effective core components."}, {"id": "q417", "text": "A parallel process in supervision that affects treatment planning is best handled by:", "options": ["Identifying it in supervision and using insight to improve clinical decision-making with the client.", "Disclosing the details of the supervisory conflict to the client in the name of transparency.", "Switching supervisors so that the dynamic cannot contaminate the case.", "Documenting the dynamic in the client's chart to preserve continuity of care."], "correct": 0, "domain": "Treatment Planning", "explanation": "Recognizing parallel process in supervision can refine the counselor's planning and relational work."}, {"id": "q418", "text": "Which discharge plan component is most essential?", "options": ["A personalized summary letter to the client celebrating the gains made during the treatment.", "Booster sessions automatically scheduled at three months and six months.", "Relapse prevention, aftercare/referrals, medication coordination as relevant, and crisis instructions.", "Documentation confirming that all treatment goals were fully attained."], "correct": 2, "domain": "Treatment Planning", "explanation": "Discharge planning supports continuity, relapse prevention, and safe transitions."}, {"id": "q419", "text": "Session frequency decisions should consider:", "options": ["The standard weekly cadence, since consistency is itself therapeutic.", "The counselor's realistic availability across the current caseload.", "Symptom severity, risk, treatment phase, client preference, and practical constraints.", "The maximum session frequency authorized by the payer for the given diagnosis."], "correct": 2, "domain": "Treatment Planning", "explanation": "Frequency is individualized based on clinical need and constraints."}, {"id": "q420", "text": "An objective written for skill building is strongest when it includes:", "options": ["The client's motivation level and commitment to practicing the skill.", "The theoretical mechanism through which the skill produces clinical change.", "A description of the skill written out in the client's own words.", "Observable skill, practice frequency, and criterion for success within a timeframe."], "correct": 3, "domain": "Treatment Planning", "explanation": "Skill objectives specify observable behaviors and success criteria."}, {"id": "q421", "text": "When a client prefers a non-evidence-based approach that is not harmful, the counselor should:", "options": ["Decline the preferred approach and document the client's informed refusal.", "Discuss evidence, risks/benefits, and collaboratively integrate preferences when ethically and clinically appropriate.", "Adopt the client's preferred approach fully, since the alliance predicts outcome better than technique choice.", "Offer the evidence-based option first and revisit the preference if progress stalls."], "correct": 1, "domain": "Treatment Planning", "explanation": "Shared decision-making respects preferences while providing honest information about evidence and fit."}, {"id": "q422", "text": "Treatment plans for co-occurring substance use and depression should:", "options": ["Integrate assessment and interventions for both conditions, sequencing based on risk and readiness.", "Treat the depression first on the premise that the drinking is self-medication.", "Sequence the substance work first, since sobriety is required for accurate mood diagnosis.", "Divide the conditions between two specialists with separate treatment plans."], "correct": 0, "domain": "Treatment Planning", "explanation": "Co-occurring disorders benefit from integrated planning rather than siloed neglect."}, {"id": "q423", "text": "Which metric best evaluates goal attainment for social anxiety exposure work?", "options": ["The client's session-by-session verbal reports of increased confidence in social settings.", "Completed hierarchy steps, SUDS trends, and functional approach behavior in target situations.", "Weekly self-ratings of overall anxiety and general life satisfaction.", "Reduction in the use of anxiety medication across the treatment period."], "correct": 1, "domain": "Treatment Planning", "explanation": "Exposure progress is tracked via hierarchy completion, distress ratings, and real-world functioning."}, {"id": "q424", "text": "A counselor includes advocacy goals in a plan when:", "options": ["Systemic barriers are central to client welfare and advocacy is appropriate to the counselor role and client consent.", "The client's presenting problems include a societal component of any kind.", "The counselor independently identifies an injustice that the client appears to have normalized over the years.", "Individual-level interventions have failed to produce measurable progress."], "correct": 0, "domain": "Treatment Planning", "explanation": "Advocacy can be part of counseling when systemic barriers affect welfare and actions stay within role and consent."}, {"id": "q425", "text": "Which is the best example of a maintenance-phase goal?", "options": ["Complete a differential assessment to confirm the working diagnosis.", "Reduce the client's acute symptoms to below clinical thresholds within four weeks.", "Consolidate skills, prevent relapse, and generalize gains to new contexts over 8 weeks.", "Build the therapeutic alliance and clarify the goals of the treatment."], "correct": 2, "domain": "Treatment Planning", "explanation": "Maintenance focuses on consolidating gains and preventing relapse after acute improvement."}, {"id": "q426", "text": "Documentation of medical necessity typically connects:", "options": ["Collected outcome measures to the agency's quality benchmarks.", "The chosen treatment modality to the counselor's licensure scope.", "Session attendance records to the payer's utilization review requirements.", "Services provided to diagnosed conditions, impairment, and planned interventions."], "correct": 3, "domain": "Treatment Planning", "explanation": "Medical necessity links functional impairment and diagnosis to services and goals."}, {"id": "q427", "text": "If a client repeatedly no-shows, the plan should address:", "options": ["Automatic discharge criteria triggered after a fixed number of absences.", "A stricter cancellation fee schedule as the primary corrective measure.", "A single direct conversation clarifying whether the client truly wants to be in counseling.", "Barriers, alliance, motivation, scheduling fit, and a clear attendance/re-engagement policy."], "correct": 3, "domain": "Treatment Planning", "explanation": "Engagement problems are clinical data requiring collaborative problem-solving and clear policies."}, {"id": "q428", "text": "Which planning approach best fits brief solution-focused counseling?", "options": ["Insight into recurring patterns with interpretation and working through.", "Functional analysis of triggers and reinforcers with graded practice.", "Preferred future, exceptions, small measurable steps, and client strengths.", "Structured cognitive restructuring with scheduled behavioral experiments."], "correct": 2, "domain": "Treatment Planning", "explanation": "Solution-focused planning emphasizes preferred future, exceptions, and incremental change."}, {"id": "q429", "text": "Attending behavior typically includes:", "options": ["Detailed note-taking that captures the client's exact concerns.", "Appropriate eye contact, body posture, following, and psychological presence.", "Accurate reflections of feeling and meaning throughout the session.", "Consistent verbal encouragement and supportive affirmations."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Attending communicates presence through nonverbal and verbal following behaviors."}, {"id": "q430", "text": "A paraphrase primarily:", "options": ["Restates the client's content in fresh words to check understanding.", "Highlights the values and meaning implied by the client's account.", "Captures the emotion beneath the client's statement in fresh words.", "Condenses several client themes into one organizing statement."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Paraphrase mirrors content to confirm understanding without adding deep interpretation."}, {"id": "q431", "text": "Which is the best example of a feeling reflection?", "options": ["What feelings come up for you when you think about the changes ahead?", "It sounds like the upcoming changes have a lot of moving parts to manage.", "Anyone facing changes like these would feel some stress about them.", "You're feeling overwhelmed and scared about the upcoming changes."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Feeling reflections name the client's affect to convey empathy and deepen awareness."}, {"id": "q432", "text": "Closed questions are most useful when the counselor needs:", "options": ["Specific facts, yes/no clarity, or focused details efficiently.", "To deepen emotional exploration at key therapeutic moments.", "To help hesitant clients open up about difficult experiences.", "To communicate empathy while gathering background information."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Closed questions efficiently gather specific data; open questions invite elaboration."}, {"id": "q433", "text": "The skill of clarifying is used to:", "options": ["Encourage deeper elaboration of briefly mentioned material.", "Confirm the counselor's hypothesis about the underlying issue.", "Resolve ambiguity and ensure accurate understanding of the client's message.", "Summarize the session's themes before transitioning to a new topic."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Clarifying questions/statements reduce misunderstanding of vague or complex material."}, {"id": "q434", "text": "In CBT, a thought record typically helps clients:", "options": ["Track the physical sensations that precede episodes of strong emotion.", "Identify situations, automatic thoughts, emotions, evidence, and alternative responses.", "Log their daily activities alongside mood ratings to reveal behavioral patterns.", "Record obsessive thoughts and the rituals used to neutralize them."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Thought records structure cognitive assessment and restructuring practice between sessions."}, {"id": "q435", "text": "Exposure and response prevention (ERP) is most associated with treating:", "options": ["Posttraumatic stress, by revisiting the trauma memory without avoidance.", "Panic disorder, by facing feared bodily sensations without escape.", "OCD-related rituals by facing cues without performing compulsions.", "Specific phobia, by graduated contact with the feared object."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "ERP is a first-line behavioral treatment for OCD involving exposure without ritualizing."}, {"id": "q436", "text": "Which Yalom therapeutic factor involves learning from others' feedback in group?", "options": ["Instillation of hope.", "Interpersonal learning.", "Altruism.", "Universality."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Interpersonal learning includes insight and new relational experiences through member feedback and interaction."}, {"id": "q437", "text": "A counselor says, 'On one hand you want to leave the job, and on the other you fear financial instability.' This is:", "options": ["A confrontation of discrepancy / double-sided reflection.", "An open-ended question.", "A summarization.", "A reflection of the meaning and values beneath the client's statement."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Double-sided reflections capture ambivalence and discrepancies constructively, common in MI and advanced empathy."}, {"id": "q438", "text": "Token economies are based primarily on:", "options": ["Cognitive restructuring of reward-related beliefs.", "Classical conditioning through repeated stimulus pairing.", "Social learning through modeling and vicarious reward.", "Operant conditioning principles of reinforcement."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Token economies systematically reinforce target behaviors using secondary reinforcers."}, {"id": "q439", "text": "Which intervention is most consistent with acceptance and commitment therapy (ACT)?", "options": ["Building psychological flexibility through acceptance, defusion, values, and committed action.", "Building insight into how past relationships shape present emotional responses.", "Building distress tolerance through crisis survival strategies and radical acceptance.", "Building rational thinking by disputing demands, awfulizing, and low frustration tolerance."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "ACT fosters psychological flexibility rather than experiential avoidance as the main aim."}, {"id": "q440", "text": "Linking in group counseling means:", "options": ["Summarizing each member's progress at the close of the session.", "Redirecting member-to-leader comments back to the whole group.", "Pairing group members together for structured dyadic exercises between sessions.", "Connecting members' themes or experiences to promote cohesion and universality."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Linking highlights commonalities and interpersonal connections among members."}, {"id": "q441", "text": "Which is a risk of premature advice-giving?", "options": ["It shortens the treatment by resolving problems before insight develops.", "It shifts the alliance toward a teaching relationship that most clients prefer.", "It can foster dependency, miss key data, and weaken client agency.", "It obligates the counselor to ensure that the advice produces results."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Early advice may short-circuit exploration and reduce client ownership of solutions."}, {"id": "q442", "text": "Role-play in counseling is often used to:", "options": ["Assess the accuracy of the client's account of past interactions.", "Practice new interpersonal skills and prepare for real-life situations in a safe setting.", "Surface unconscious relational material through spontaneous dramatic enactment.", "Demonstrate to clients how their behavior affects other people."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Behavioral rehearsal via role-play builds skills and confidence before real-world application."}, {"id": "q443", "text": "Which best describes a genogram's clinical use?", "options": ["Mapping multigenerational family patterns, relationships, and significant events.", "Assessing current household roles in preparation for structural interventions.", "Recording the family's medical history for referral coordination.", "Charting the client's social network and community support systems."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Genograms visualize family structure and patterns across generations for assessment and intervention."}, {"id": "q444", "text": "Socratic questioning in CBT aims to:", "options": ["Present logical counterarguments until the client's belief finally shifts.", "Use strategically ordered questions that lead the client toward the counselor's conclusion.", "Guide clients to examine evidence and generate alternative perspectives through guided discovery.", "Ask progressively deeper questions about the childhood origins of beliefs."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Socratic dialogue promotes guided discovery rather than didactic imposition of beliefs."}, {"id": "q445", "text": "Which group stage is characterized by conflict, dominance struggles, and resistance?", "options": ["Orientation/forming.", "Transition/storming.", "Termination/adjourning.", "Working/performing."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "The transition/storming stage often includes conflict and testing of norms and leadership."}, {"id": "q446", "text": "Mindfulness-based interventions primarily train clients to:", "options": ["Achieve relaxed states that lower baseline physiological arousal.", "Redirect attention away from distressing internal experiences.", "Observe their thoughts in order to identify and correct distortions.", "Pay nonjudgmental attention to present-moment experience."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Mindfulness cultivates present-centered, nonjudgmental awareness."}, {"id": "q447", "text": "A counselor uses 'when you look away each time we discuss anger…' This skill is:", "options": ["A confrontation of discrepancy.", "Immediacy / process comment.", "A clarifying question.", "An interpretation."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Process comments/immediacy address here-and-now behavior in the therapeutic relationship."}, {"id": "q448", "text": "Which is most characteristic of feminist counseling interventions?", "options": ["Analysis of family structure, hierarchy, and boundary realignment.", "Insight into internalized objects from early relational life.", "Attention to power, egalitarianism, social context, and empowerment.", "Value-neutral exploration that avoids influencing the client's roles."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Feminist approaches emphasize power analysis, egalitarian relationship, and empowerment."}, {"id": "q449", "text": "Contingency contracts in counseling specify:", "options": ["Agreed behaviors and consequences/reinforcers for meeting or not meeting targets.", "The client's core values and the committed actions that express them.", "The topics reserved for sessions and those handled as homework.", "The feared situations to be faced in order and the coping skills for each step."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Contingency contracts make behavioral expectations and consequences explicit and collaborative."}, {"id": "q450", "text": "Which response best demonstrates advanced empathy?", "options": ["So many people struggle deeply with closeness after they have been hurt; you are truly not alone in carrying this burden.", "You're feeling lonely, and it hurts that reaching out feels so hard right now.", "It sounds like your early relationships taught you that closeness is never safe.", "It seems part of you wants closeness, while another part expects rejection if you reach out—leaving you stuck and lonely."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Advanced empathy captures deeper, often unspoken meanings and conflicts with accuracy and care."}, {"id": "q451", "text": "Flooding as an exposure method involves:", "options": ["Very gradual hierarchy only.", "Prolonged exposure to high-intensity feared stimuli without escape, when clinically appropriate.", "Avoidance homework.", "Only imaginal career fantasies."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Flooding uses intense prolonged exposure; it requires careful selection, consent, and competence."}, {"id": "q452", "text": "Which intervention targets family enmeshment in structural therapy?", "options": ["Strengthening diffuse boundaries and supporting appropriate subsystem differentiation.", "Increasing triangulation intentionally.", "Removing all rules permanently.", "Only individual free association."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Structural work clarifies boundaries and strengthens appropriate subsystem functioning when enmeshment is present."}, {"id": "q453", "text": "According to Erikson, the psychosocial crisis of generativity vs. stagnation is typical of:", "options": ["Infancy.", "Adolescence.", "Middle adulthood.", "Only late adulthood."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Generativity vs. stagnation is associated with middle adulthood and concern for guiding the next generation."}, {"id": "q454", "text": "Vygotsky's zone of proximal development refers to:", "options": ["Tasks a learner can do only with no help and no challenge.", "The range between independent performance and performance with guided support.", "Genetic IQ fixed at birth.", "Only motor reflexes."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "ZPD is the gap between solo capability and capability with scaffolding from a more knowledgeable other."}, {"id": "q455", "text": "Which career theory emphasizes matching traits to occupational factors?", "options": ["Trait-and-factor / person-environment fit approaches (e.g., Parsons, Holland-related fitting).", "Only pure existential counseling.", "Only Gestalt unfinished business.", "Classical conditioning of job titles."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Trait-and-factor approaches assess individual traits and match them to job requirements/environments."}, {"id": "q456", "text": "The concept of career adaptability is most associated with:", "options": ["Savickas and career construction perspectives emphasizing coping with career tasks and transitions.", "Only Holland codes without development.", "Ignoring life themes.", "Fixed matching at age 16 only."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Career construction/adaptability focuses on how people navigate career tasks, transitions, and trauma."}, {"id": "q457", "text": "Which symptom cluster is most characteristic of PTSD?", "options": ["Only increased appetite.", "Intrusion, avoidance, negative alterations in cognition/mood, and arousal/reactivity after trauma.", "Only lifelong schizoid detachment without trauma.", "Mild preference for solitude."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "PTSD includes intrusion, avoidance, negative cognition/mood changes, and hyperarousal after qualifying trauma."}, {"id": "q458", "text": "Motivational interviewing is especially useful for clients who are:", "options": ["Fully decided and finished with change.", "Ambivalent about behavior change.", "Unable to speak.", "Seeking only IQ testing."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "MI is designed to work with ambivalence and strengthen intrinsic motivation for change."}, {"id": "q459", "text": "Which best describes minority stress?", "options": ["Stress unrelated to identity.", "Chronic stress from stigma, prejudice, and discrimination experienced by marginalized groups.", "Only acute medical pain.", "A formal thought disorder."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Minority stress theory links excess stress from social stigma to mental health disparities."}, {"id": "q460", "text": "In addiction counseling, harm reduction approaches primarily aim to:", "options": ["Require immediate lifelong abstinence as the only acceptable goal for every client.", "Reduce substance-related harm and engage clients at their readiness level.", "Ignore safety entirely.", "Shame clients into change."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Harm reduction meets clients where they are to reduce negative consequences and support engagement."}, {"id": "q461", "text": "Which childhood disorder category involves persistent pattern of violating others' rights or major norms?", "options": ["Specific phobia.", "Conduct disorder.", "Selective mutism only.", "Enuresis only."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Conduct disorder features repetitive behavior that violates rights of others or age-appropriate norms."}, {"id": "q462", "text": "A client with somatic symptom concerns repeatedly fears serious illness despite medical reassurance. Counseling focus often includes:", "options": ["Only more unnecessary invasive tests ordered by the counselor.", "Anxiety, health-related beliefs, functioning, and coordinated care with medical providers.", "Ignoring distress as fake always.", "Forcing a single diagnosis of malingering."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Somatic symptom work addresses health anxiety, beliefs, functioning, and collaborative medical care."}, {"id": "q463", "text": "Which is a key feature of burnout among counselors?", "options": ["Increased energy and idealism only.", "Emotional exhaustion, cynicism/depersonalization, and reduced sense of efficacy.", "Perfect work-life balance.", "Only physical fitness gains."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Burnout involves exhaustion, depersonalization/cynicism, and diminished professional accomplishment."}, {"id": "q464", "text": "Gender-affirming counseling practice includes:", "options": ["Conversion efforts.", "Respecting affirmed name/pronouns, exploring identity supportively, and addressing minority stress.", "Forcing disclosure to all family immediately.", "Assuming identity is the sole cause of all symptoms always."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Affirmative care respects identity and addresses related stressors without pathologizing identity itself."}, {"id": "q465", "text": "Which couple pattern involves one partner seeking closeness while the other withdraws?", "options": ["Pursuer–distancer dynamics.", "Perfect synchrony always.", "Only parallel play in children.", "Unrelated to attachment."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Pursuer–distancer cycles are common complementary patterns in distressed couples."}, {"id": "q466", "text": "Learned helplessness is most associated with:", "options": ["Belief that outcomes are uncontrollable after repeated failure experiences, linked to depression research.", "High self-efficacy always.", "Only manic grandiosity.", "Career inventiveness only."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Learned helplessness describes passive responding after uncontrollable aversive events and relates to depression models."}, {"id": "q467", "text": "Which developmental concept describes adolescents' belief that others are as focused on them as they are on themselves?", "options": ["Imaginary audience.", "Object permanence.", "Conservation.", "Secure base only in infancy."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Imaginary audience is an adolescent egocentrism concept (Elkind) about perceived scrutiny by others."}, {"id": "q468", "text": "Primary prevention in counseling aims to:", "options": ["Treat only chronic severe disorders after disability is entrenched.", "Reduce incidence of problems by targeting well populations before onset.", "Provide tertiary rehabilitation only.", "Ignore community factors."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Primary prevention seeks to prevent problems before they occur in at-risk or general populations."}, {"id": "q469", "text": "Which statement about grief is most accurate?", "options": ["All grief follows five fixed stages in order for everyone.", "Grief is variable; cultural norms, relationship, and meaning shape expression and course.", "Grief never involves yearning.", "Counseling should force rapid closure."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Contemporary grief models emphasize variability and cultural context rather than rigid universal stages."}, {"id": "q470", "text": "A client with ADHD reports workplace underperformance. Clinical focus may include:", "options": ["Only personality assassination.", "Executive functioning supports, environmental modifications, skills, and possible medical collaboration.", "Ignoring accommodations as coddling.", "Assuming laziness without assessment."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Adult ADHD care often targets executive skills, structure, and collaborative treatment options."}, {"id": "q471", "text": "Which research design best supports causal inference about an intervention's effect?", "options": ["Anecdote.", "Well-controlled randomized experiment.", "Single correlational survey only.", "Uncontrolled case opinion only."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Randomized controlled designs best support causal claims about treatment efficacy."}, {"id": "q472", "text": "External validity refers to:", "options": ["Whether results generalize beyond the study conditions/sample.", "Whether the independent variable caused the outcome inside the study.", "Scorer agreement only.", "Item wording beauty."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "External validity is generalizability; internal validity concerns causal interpretability within the study."}, {"id": "q473", "text": "Which anxiety disorder is characterized by recurrent unexpected panic attacks with persistent concern/change in behavior?", "options": ["Specific phobia limited to one object without panic history necessarily.", "Panic disorder.", "Selective mutism only.", "Oppositional defiant disorder."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Panic disorder involves recurrent unexpected panic attacks plus worry or maladaptive change related to attacks."}, {"id": "q474", "text": "Spiritual/religious assessment in counseling is appropriate when:", "options": ["The counselor imposes a belief system.", "Spirituality may be a source of meaning, coping, conflict, or identity for the client and is explored respectfully.", "It replaces all ethical codes.", "It is used to proselytize."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Spiritually responsive counseling explores client spirituality as potentially relevant without imposition."}, {"id": "q475", "text": "Which best describes circular causality in family systems?", "options": ["One person is solely to blame in a linear chain always.", "Mutual influence patterns in which each person's behavior shapes and is shaped by others' responses.", "Genetics only.", "Random unrelated events."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Systems thinking emphasizes reciprocal, ongoing influence rather than simple linear blame."}, {"id": "q476", "text": "A school counselor coordinating services for a student with disabilities is most clearly engaged in:", "options": ["Only private long-term psychoanalysis.", "Advocacy and systems-level support within educational contexts.", "Forensic evaluation for criminal court only.", "Prescribing medication."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "School counseling often includes educational advocacy and coordination within systems of care."}, {"id": "q477", "text": "Congruence in the counselor means:", "options": ["Saying everything without filters.", "Alignment between inner experience and outward professional communication in a helpful way.", "Never having emotions.", "Copying the client's posture only as mimicry without presence."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Congruence is genuine, integrated presence within professional boundaries."}, {"id": "q478", "text": "Which attribute most supports ethical decision-making under pressure?", "options": ["Impulsivity.", "Moral courage and commitment to client welfare over personal comfort.", "People-pleasing at any cost.", "Avoidance of codes of ethics."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Moral courage helps counselors act ethically despite pressure, fear, or inconvenience."}, {"id": "q479", "text": "Empathic accuracy is best described as:", "options": ["Projecting the counselor's feelings onto the client.", "Correctly understanding the client's internal experience.", "Finishing the client's sentences always.", "Agreeing with all content."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Empathic accuracy is the degree to which the counselor correctly perceives the client's thoughts/feelings."}, {"id": "q480", "text": "A nondefensive stance when receiving client anger most reflects:", "options": ["Fragility.", "Emotional regulation, humility, and alliance repair capacity.", "Agreement that the counselor is always wrong.", "Immediate counterattack."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Regulated, nondefensive responding supports safety and repair when clients express anger."}, {"id": "q481", "text": "Professional diligence includes:", "options": ["Chronic lateness.", "Thorough preparation, follow-through on commitments, and careful clinical work.", "Skipping documentation.", "Ignoring emails about risk for weeks."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Diligence is careful, reliable, and thorough professional practice."}, {"id": "q482", "text": "Which quality helps counselors avoid burnout-related ethical slips?", "options": ["Endless overwork without limits.", "Self-awareness of impairment and willingness to adjust load and seek support.", "Isolation and secrecy about stress.", "Caffeine only."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Recognizing impairment early and seeking support protects clients and counselors."}, {"id": "q483", "text": "Respect in counseling is demonstrated when the counselor:", "options": ["Mocks client dialect.", "Honors dignity, culture, and autonomy even during disagreement.", "Uses sarcasm to motivate.", "Imposes nicknames without consent."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Respect upholds client dignity and autonomy across differences and conflict."}, {"id": "q484", "text": "Which attribute is most tied to maintaining confidentiality habits day to day?", "options": ["Curiosity about gossip.", "Conscientiousness and habitual privacy discipline.", "Forgetfulness about chart security.", "Public processing of cases for fun."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Conscientious privacy habits operationalize confidentiality ethics in daily behavior."}, {"id": "q485", "text": "Therapeutic optimism differs from toxic positivity in that it:", "options": ["Denies pain.", "Holds realistic hope while validating suffering and constraints.", "Guarantees outcomes.", "Avoids hard topics."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Healthy hope validates difficulty while supporting possibility; toxic positivity invalidates pain."}, {"id": "q486", "text": "A counselor who can laugh gently with a client at appropriate moments may be showing:", "options": ["Boundary-less chaos always.", "Human warmth and relational flexibility within professional judgment.", "Incompetence.", "Avoidance of all affect."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Appropriate shared humor can strengthen alliance when attuned and respectful."}, {"id": "q487", "text": "Self-reflection after sessions primarily supports:", "options": ["Rumination without learning.", "Professional growth, countertransference awareness, and improved future interventions.", "Only self-criticism.", "Billing fraud."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Reflective practice turns experience into learning and safer, more effective care."}, {"id": "q488", "text": "Which attribute best describes fairness in allocating time and resources among clients?", "options": ["Favoritism toward easy clients.", "Justice-oriented equity and consistent professional standards.", "Ignoring high-risk clients.", "Random cancellation patterns."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Justice involves fair, non-discriminatory treatment and equitable professional conduct."}, {"id": "q489", "text": "Emotional availability means the counselor:", "options": ["Is flooded and uncontained every session.", "Can be present with client affect while remaining regulated and boundaried.", "Avoids all emotion.", "Requires the client to caretake the counselor."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Availability is present and responsive without role reversal or dysregulation."}, {"id": "q490", "text": "Which behavior shows intellectual humility?", "options": ["Claiming certainty without evidence.", "Revising views when new data or client feedback warrants it.", "Never reading after graduation.", "Dismissing supervision."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Intellectual humility includes openness to correction and limits of knowledge."}, {"id": "q491", "text": "A counselor feels bored with a client and secretly blames the client. Growth-oriented response is to:", "options": ["Express boredom as the client's fault in session one.", "Explore the reaction in supervision as possible countertransference or case stagnation.", "Terminate abruptly via text.", "Yawn loudly each session intentionally."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Boredom can be clinical data; supervision helps interpret and respond professionally."}, {"id": "q492", "text": "Dependability as a counselor attribute is shown by:", "options": ["Frequent unexplained no-shows.", "Keeping appointments, honoring agreements, and communicating changes promptly.", "Changing fees randomly each week without notice.", "Losing records often."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Dependability builds trust through reliability and clear communication."}, {"id": "q493", "text": "Which quality is essential for multicultural orientation?", "options": ["Cultural concealment of all differences.", "Cultural humility, comfort with diversity, and responsiveness to client cultural identity.", "Colorblind denial of culture.", "Stereotyping as efficiency."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Multicultural orientation emphasizes humility, comfort with diversity, and cultural responsiveness."}, {"id": "q494", "text": "Compassion differs from pity in that compassion:", "options": ["Elevates the helper and diminishes the client.", "Joins with suffering while affirming dignity and agency.", "Avoids action entirely.", "Requires rescuing without consent."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Compassion is solidarity with suffering that preserves dignity, unlike pity's hierarchy."}, {"id": "q495", "text": "A counselor admits limits of expertise to a client. This most often reflects:", "options": ["Incompetence only.", "Honesty, humility, and ethical transparency that can strengthen trust.", "A boundary violation.", "Abandonment automatically."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Transparent limits, paired with appropriate help-seeking or referral, support ethical trust."}, {"id": "q496", "text": "Which attribute helps counselors navigate strong political differences with clients?", "options": ["Debate to convert the client.", "Bracketing, respect for autonomy, and focus on the client's goals and welfare.", "Ending therapy for any disagreement.", "Secretly sabotaging goals."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Professional bracketing keeps the work centered on client welfare rather than counselor ideology."}, {"id": "q497", "text": "Mindful self-care is best framed as:", "options": ["Selfish neglect of clients.", "An ethical responsibility that sustains competence and presence.", "Optional only for weak counselors.", "A replacement for clinical skill."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Self-care supports sustainable, ethical practice and client welfare."}, {"id": "q498", "text": "Which best illustrates accountability?", "options": ["Blaming systems for every personal error without change.", "Owning mistakes, repairing harm, and adjusting practice.", "Hiding errors from supervisors.", "Documenting falsely to look better."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Accountability includes ownership, repair, and learning after missteps."}, {"id": "q499", "text": "Gentleness in confrontation means:", "options": ["Avoiding all difficult feedback.", "Delivering necessary honesty with care, timing, and respect.", "Using insults softly.", "Only written feedback never spoken."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Effective confrontation pairs truth with relational care and good timing."}, {"id": "q500", "text": "Which combination best describes professional maturity?", "options": ["Technical skill without ethics.", "Competence, ethical integrity, self-awareness, and relational steadiness under stress.", "Confidence without feedback.", "Experience years alone without growth."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Professional maturity integrates skill, ethics, self-awareness, and stable relational presence."}];
